            return httpRequest({
                Url = VEXORA_VALIDATE_URL,
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json",
                    ["apikey"] = VEXORA_PUBLISHABLE_KEY,
                },
                Body = requestBody,
            })
        end)
        if not requestOk or type(response) ~= "table" then
            return false
        end

        local parsed
        pcall(function()
            parsed = VEXORA_HttpService:JSONDecode(response.Body or "")
        end)

