    local function VEXORA_Validate()
        if VEXORA_Busy or VEXORA_Authorized or VEXORA_Cancelled then return end
        local enteredKey = VEXORA_KeyBox.Text:match("^%s*(.-)%s*$")
        if enteredKey == "" then
