-- LARGE GENERAL KNOWLEDGE EXPANSION (generated lookup facts).
-- These entries are added directly to RiddleDatabase to avoid creating thousands
-- of redundant wrapper aliases for every generated fact.
function addGK(question, answer)
    RiddleDatabase[string.lower(question)] = tostring(answer)
end

-- Arithmetic lookup bank: addition, subtraction, multiplication, division,
-- squares, cubes, and powers. Word forms + symbols so spoken riddles match.
-- Live arithmeticAnswer() still handles arbitrary expressions beyond this grid.
-- Keep precomputed math modest so index builds stay fast.
-- Free-form arithmetic is still handled live by arithmeticAnswer().
for a = 0, 40 do
    addGK("what is " .. a .. " plus " .. a, a + a)
    addGK("what is " .. a .. " doubled", a * 2)
    addGK("what is double " .. a, a * 2)
    addGK("what is " .. a .. " squared", a * a)
    addGK("what is the square of " .. a, a * a)
    addGK("square of " .. a, a * a)
    if a <= 20 then
        addGK("what is " .. a .. " cubed", a * a * a)
        addGK("what is the cube of " .. a, a * a * a)
    end
    if a > 0 and a % 2 == 0 then addGK("what is half of " .. a, a // 2) end
    for b = 0, 40 do
        local sum, diff, prod = a + b, a - b, a * b
        addGK("what is " .. a .. " plus " .. b, sum)
        addGK(a .. " + " .. b, sum)
        addGK(a .. " plus " .. b, sum)
        if a >= b then
            addGK("what is " .. a .. " minus " .. b, diff)
            addGK(a .. " - " .. b, diff)
            addGK(a .. " minus " .. b, diff)
        end
        if a <= 20 and b <= 20 then
            addGK("what is " .. a .. " times " .. b, prod)
            addGK("what is " .. a .. " multiplied by " .. b, prod)
            addGK(a .. " x " .. b, prod)
            addGK(a .. " * " .. b, prod)
            addGK(a .. " times " .. b, prod)
        end
        if b > 0 and a % b == 0 and a <= 40 then
            local quot = a // b
            addGK("what is " .. a .. " divided by " .. b, quot)
            addGK(a .. " / " .. b, quot)
            addGK(a .. " divided by " .. b, quot)
        end
    end
end
for n = 1, 40 do
    addGK("what is " .. n .. " to the power of 2", n * n)
    addGK("what is half of " .. (n * 2), n)
    addGK("what is double " .. n, n * 2)
    addGK("what is triple " .. n, n * 3)
    addGK(n .. "^2", n * n)
end
for n = 1, 40 do
    addGK("what is 50 percent of " .. n, n / 2)
    addGK("what is 100 percent of " .. n, n)
end

