}) do
    local n = stat[1]:lower()
    local compact = n:gsub("%s+", ""):gsub("[^%w]", "")
    local income = stat[3]
    local rarity = stat[2]
    local cost = stat[4]
    -- Store multiple natural phrasings so questions do not need to match a template.
    for _, q in ipairs({
        n .. " income", "income of " .. n, "how much does " .. n .. " make",
        "how much does " .. n .. " generate", "how much money does " .. n .. " make",
        "how much money does " .. n .. " generate", "how much does " .. n .. " earn",
        "how much does " .. n .. " make per second", n .. " income per second",
        n .. " earns", n .. " generates", n .. " makes", "money per second from " .. n,
        "cash per second from " .. n, "per second " .. n
    }) do
        registerRiddleFact(q, income)
    end
    for _, q in ipairs({n .. " rarity", "rarity of " .. n, "what rarity is " .. n,
        "what is the rarity for " .. n, "which rarity is " .. n}) do
        registerRiddleFact(q, rarity)
    end
    if cost ~= "not listed" then
        for _, q in ipairs({n .. " cost", "cost of " .. n, "price of " .. n,
            "how much does " .. n .. " cost", "how much is " .. n,
            "buy price of " .. n, n .. " price"}) do
            registerRiddleFact(q, cost)
        end
    end
end

