-- Generated lookup facts. Every answer is computed or taken from a fixed reference table,
-- so the thousands of entries here are exact. Only fills keys that are still empty.
do
    local function setFact(question, answer)
        local key = string.lower(question)
        if RiddleDatabase[key] == nil then RiddleDatabase[key] = tostring(answer) end
    end
    local function roman(n)
        local pairsList = {{1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"}, {100, "C"}, {90, "XC"},
            {50, "L"}, {40, "XL"}, {10, "X"}, {9, "IX"}, {5, "V"}, {4, "IV"}, {1, "I"}}
        local out = ""
        for _, pair in ipairs(pairsList) do
            while n >= pair[1] do
                out = out .. pair[2]
                n = n - pair[1]
            end
        end
        return out
    end
    local function binary(n)
        if n == 0 then return "0" end
        local out = ""
        while n > 0 do
            out = tostring(n % 2) .. out
            n = math.floor(n / 2)
        end
        return out
    end
    -- Primes up to 1000 (sieve).
    local composite, primes = {}, {}
    for i = 2, 1000 do
        if not composite[i] then
            primes[#primes + 1] = i
            for j = i * i, 1000, i do composite[j] = true end
        end
    end
    for n = 1, 1000 do
        local isPrime = n >= 2 and not composite[n]
        setFact("is " .. n .. " prime", isPrime and "yes" or "no")
        setFact("is " .. n .. " a prime number", isPrime and "yes" or "no")
        setFact("roman numeral for " .. n, string.upper(roman(n)))
    end
    for n = 1, #primes do
        setFact("prime number " .. n, primes[n])
        setFact("the " .. n .. " prime", primes[n])
    end
    for n = 1, 100 do
        setFact("square of " .. n, n * n)
        setFact(n .. " squared", n * n)
        setFact("cube of " .. n, n * n * n)
        setFact(n .. " cubed", n * n * n)
        setFact("square root of " .. (n * n), n)
    end
    for n = 0, 255 do
        setFact("binary of " .. n, binary(n))
        setFact("hex of " .. n, string.format("%X", n))
        setFact("hexadecimal of " .. n, string.format("%X", n))
    end
    local fact = 1
    for n = 0, 12 do
        if n > 0 then fact = fact * n end
        setFact(n .. " factorial", fact)
    end
    local a, b = 0, 1
    for n = 1, 30 do
        a, b = b, a + b
        setFact("fibonacci number " .. n, a)
    end
    local power = 1
    for n = 0, 20 do
        setFact("2 to the power of " .. n, power)
        setFact("2 to the " .. n, power)
        power = power * 2
    end
    for n = 1, 52 do setFact("days in " .. n .. " weeks", n * 7) end
    for n = 1, 60 do setFact("seconds in " .. n .. " minutes", n * 60) end
    for n = 1, 24 do setFact("minutes in " .. n .. " hours", n * 60) end
    for n = 1, 31 do setFact("hours in " .. n .. " days", n * 24) end

    -- Elements 1-118: name and symbol, with four question forms each.
    local elements = "Hydrogen H;Helium He;Lithium Li;Beryllium Be;Boron B;Carbon C;Nitrogen N;Oxygen O;Fluorine F;Neon Ne;Sodium Na;Magnesium Mg;Aluminum Al;Silicon Si;Phosphorus P;Sulfur S;Chlorine Cl;Argon Ar;Potassium K;Calcium Ca;Scandium Sc;Titanium Ti;Vanadium V;Chromium Cr;Manganese Mn;Iron Fe;Cobalt Co;Nickel Ni;Copper Cu;Zinc Zn;Gallium Ga;Germanium Ge;Arsenic As;Selenium Se;Bromine Br;Krypton Kr;Rubidium Rb;Strontium Sr;Yttrium Y;Zirconium Zr;Niobium Nb;Molybdenum Mo;Technetium Tc;Ruthenium Ru;Rhodium Rh;Palladium Pd;Silver Ag;Cadmium Cd;Indium In;Tin Sn;Antimony Sb;Tellurium Te;Iodine I;Xenon Xe;Cesium Cs;Barium Ba;Lanthanum La;Cerium Ce;Praseodymium Pr;Neodymium Nd;Promethium Pm;Samarium Sm;Europium Eu;Gadolinium Gd;Terbium Tb;Dysprosium Dy;Holmium Ho;Erbium Er;Thulium Tm;Ytterbium Yb;Lutetium Lu;Hafnium Hf;Tantalum Ta;Tungsten W;Rhenium Re;Osmium Os;Iridium Ir;Platinum Pt;Gold Au;Mercury Hg;Thallium Tl;Lead Pb;Bismuth Bi;Polonium Po;Astatine At;Radon Rn;Francium Fr;Radium Ra;Actinium Ac;Thorium Th;Protactinium Pa;Uranium U;Neptunium Np;Plutonium Pu;Americium Am;Curium Cm;Berkelium Bk;Californium Cf;Einsteinium Es;Fermium Fm;Mendelevium Md;Nobelium No;Lawrencium Lr;Rutherfordium Rf;Dubnium Db;Seaborgium Sg;Bohrium Bh;Hassium Hs;Meitnerium Mt;Darmstadtium Ds;Roentgenium Rg;Copernicium Cn;Nihonium Nh;Flerovium Fl;Moscovium Mc;Livermorium Lv;Tennessine Ts;Oganesson Og"
    local number = 0
    for name, symbol in elements:gmatch("(%a+) (%a+)") do
        number = number + 1
        local lowerName = string.lower(name)
        local lowerSymbol = string.lower(symbol)
        setFact("atomic number of " .. lowerName, number)
        setFact("atomic number for " .. lowerName, number)
        setFact("symbol for " .. lowerName, symbol)
        setFact("chemical symbol for " .. lowerName, symbol)
        setFact("element with atomic number " .. number, name)
        setFact("element with symbol " .. lowerSymbol, name)
        setFact("name of element " .. symbol, name)
    end

    -- Country capitals (common, widely accepted answers).
    local capitals = "Afghanistan|Kabul;Albania|Tirana;Algeria|Algiers;Andorra|Andorra la Vella;Angola|Luanda;Argentina|Buenos Aires;Armenia|Yerevan;Australia|Canberra;Austria|Vienna;Azerbaijan|Baku;Bahamas|Nassau;Bahrain|Manama;Bangladesh|Dhaka;Barbados|Bridgetown;Belarus|Minsk;Belgium|Brussels;Belize|Belmopan;Benin|Porto-Novo;Bhutan|Thimphu;Bosnia and Herzegovina|Sarajevo;Botswana|Gaborone;Brazil|Brasilia;Brunei|Bandar Seri Begawan;Bulgaria|Sofia;Burkina Faso|Ouagadougou;Burundi|Gitega;Cambodia|Phnom Penh;Cameroon|Yaounde;Canada|Ottawa;Cape Verde|Praia;Central African Republic|Bangui;Chad|NDjamena;Chile|Santiago;China|Beijing;Colombia|Bogota;Comoros|Moroni;Costa Rica|San Jose;Croatia|Zagreb;Cuba|Havana;Cyprus|Nicosia;Czech Republic|Prague;Denmark|Copenhagen;Djibouti|Djibouti City;Dominica|Roseau;Dominican Republic|Santo Domingo;Ecuador|Quito;Egypt|Cairo;El Salvador|San Salvador;Equatorial Guinea|Malabo;Eritrea|Asmara;Estonia|Tallinn;Eswatini|Mbabane;Ethiopia|Addis Ababa;Fiji|Suva;Finland|Helsinki;France|Paris;Gabon|Libreville;Gambia|Banjul;Georgia|Tbilisi;Germany|Berlin;Ghana|Accra;Greece|Athens;Grenada|Saint Georges;Guatemala|Guatemala City;Guinea|Conakry;Guinea-Bissau|Bissau;Guyana|Georgetown;Haiti|Port-au-Prince;Honduras|Tegucigalpa;Hungary|Budapest;Iceland|Reykjavik;India|New Delhi;Iran|Tehran;Iraq|Baghdad;Ireland|Dublin;Italy|Rome;Ivory Coast|Yamoussoukro;Jamaica|Kingston;Japan|Tokyo;Jordan|Amman;Kazakhstan|Astana;Kenya|Nairobi;Kiribati|South Tarawa;Kuwait|Kuwait City;Kyrgyzstan|Bishkek;Laos|Vientiane;Latvia|Riga;Lebanon|Beirut;Lesotho|Maseru;Liberia|Monrovia;Libya|Tripoli;Liechtenstein|Vaduz;Lithuania|Vilnius;Luxembourg|Luxembourg City;Madagascar|Antananarivo;Malawi|Lilongwe;Malaysia|Kuala Lumpur;Maldives|Male;Mali|Bamako;Malta|Valletta;Marshall Islands|Majuro;Mauritania|Nouakchott;Mauritius|Port Louis;Mexico|Mexico City;Micronesia|Palikir;Moldova|Chisinau;Monaco|Monaco;Mongolia|Ulaanbaatar;Montenegro|Podgorica;Morocco|Rabat;Mozambique|Maputo;Myanmar|Naypyidaw;Namibia|Windhoek;Nauru|Yaren;Nepal|Kathmandu;Netherlands|Amsterdam;New Zealand|Wellington;Nicaragua|Managua;Niger|Niamey;Nigeria|Abuja;North Korea|Pyongyang;North Macedonia|Skopje;Norway|Oslo;Oman|Muscat;Pakistan|Islamabad;Palau|Ngerulmud;Panama|Panama City;Papua New Guinea|Port Moresby;Paraguay|Asuncion;Peru|Lima;Philippines|Manila;Poland|Warsaw;Portugal|Lisbon;Qatar|Doha;Romania|Bucharest;Russia|Moscow;Rwanda|Kigali;Saint Kitts and Nevis|Basseterre;Saint Lucia|Castries;Samoa|Apia;San Marino|San Marino;Sao Tome and Principe|Sao Tome;Saudi Arabia|Riyadh;Senegal|Dakar;Serbia|Belgrade;Seychelles|Victoria;Sierra Leone|Freetown;Singapore|Singapore;Slovakia|Bratislava;Slovenia|Ljubljana;Solomon Islands|Honiara;Somalia|Mogadishu;South Korea|Seoul;South Sudan|Juba;Spain|Madrid;Sudan|Khartoum;Suriname|Paramaribo;Sweden|Stockholm;Switzerland|Bern;Syria|Damascus;Tajikistan|Dushanbe;Tanzania|Dodoma;Thailand|Bangkok;Timor-Leste|Dili;Togo|Lome;Tonga|Nukualofa;Trinidad and Tobago|Port of Spain;Tunisia|Tunis;Turkey|Ankara;Turkmenistan|Ashgabat;Tuvalu|Funafuti;Uganda|Kampala;Ukraine|Kyiv;United Arab Emirates|Abu Dhabi;United Kingdom|London;United States|Washington DC;Uruguay|Montevideo;Uzbekistan|Tashkent;Vanuatu|Port Vila;Vatican City|Vatican City;Venezuela|Caracas;Vietnam|Hanoi;Yemen|Sanaa;Zambia|Lusaka;Zimbabwe|Harare"
    for country, capital in capitals:gmatch("([^|;]+)|([^;]+)") do
        setFact("capital of " .. country, capital)
        setFact(country .. " capital", capital)
        setFact("capital city of " .. country, capital)
    end
end

