-- Use an explicit reference timezone rather than an executor's local calendar.
function createRiddleCalendar(config, deps)
    deps = deps or {}
    return function()
        local timestamp = deps.timestamp and deps.timestamp() or workspace:GetServerTimeNow()
        local offset = tonumber(config.RiddleUtcOffsetHours) or 0
        if offset ~= offset then offset = 0 end
        offset = math.clamp(offset, -14, 14)
        -- With the default offset, use the player's local calendar so a riddle
        -- about "today" agrees with the date the player sees on their device.
        -- A nonzero offset deliberately selects a fixed UTC-relative calendar.
        if offset == 0 then
            local ok, localDate = pcall(os.date, "*t", timestamp)
            if ok and type(localDate) == "table" then
                return {day = localDate.day, month = localDate.month, year = localDate.year, wday = localDate.wday}
            end
        end
        local adjusted = math.floor(timestamp + offset * 3600)
        if deps.toDate then return deps.toDate(adjusted) end
        local current = DateTime.fromUnixTimestamp(adjusted):ToUniversalTime()
        return {day = current.Day, month = current.Month, year = current.Year, wday = current.Weekday}
    end
end

-- Riddle lookup and submission.
function createRiddleSolver(config, deps, saved)
    saved = saved or {}
    local options = saved.riddleSettings or {}
    local s = {
        alive = true, enabled = false, armed = false, entries = {}, answers = {}, questions = {},
        learned = saved.learnedFacts or {}, seenIds = {}, seenText = {}, attempts = {},
        currentBrainrotFactRevision = CurrentBrainrotFactRevision, riddleFactRevision = RiddleFactRevision,
        riddleRarityFactRevision = RiddleRarityFactRevision,
        riddleBirthDateFactRevision = RiddleBirthDateFactRevision,
        riddleLuckyBlockFactRevision = RiddleLuckyBlockFactRevision,
        riddleColorFactRevision = RiddleColorFactRevision,
        redeemed = deps.redeemed or saved.riddleRedeemed or {}, session = 0,
        pending = nil, timer = nil, responseTimer = nil, waitingForReady = false, revision = 0,
        learnedCount = 0, unknownCount = 0, duplicateCount = 0, retryAt = nil, transientRetries = {},
        status = "AI Riddle Solver Off", lastMatched = "", lastResponse = "",
        settings = {learnFacts = options.learnFacts == true, listenForClues = options.listenForClues == true,
            -- Do not submit random, unrelated answers by default. Fallback is opt-in.
            fallback = options.fallback == true,
            fallbackDelay = math.clamp(tonumber(options.fallbackDelay) or 0.35, 0, 1)},
    }
    -- Clear superseded facts once for this update, preserving unrelated facts
    -- and anything learned after the current revision was saved.
    if saved.currentBrainrotFactRevision ~= s.currentBrainrotFactRevision then
        for question in pairs(CurrentBrainrotFactKeys or {}) do s.learned[question] = nil end
    end
    if saved.riddleFactRevision ~= s.riddleFactRevision then
        for question in pairs(RiddleFactKeys) do s.learned[question] = nil end
    end
    if saved.riddleRarityFactRevision ~= s.riddleRarityFactRevision then
        for question in pairs(RiddleRarityFactKeys) do s.learned[question] = nil end
    end
    if saved.riddleBirthDateFactRevision ~= s.riddleBirthDateFactRevision then
        for question in pairs(RiddleBirthDateFactKeys) do s.learned[question] = nil end
    end
    if saved.riddleColorFactRevision ~= s.riddleColorFactRevision then
        for question in pairs(RiddleColorFactKeys) do s.learned[question] = nil end
        s.learned["dragon skeletonini"], s.learned["dragonskeletonini"] = nil, nil
    end
    if saved.riddleLuckyBlockFactRevision ~= s.riddleLuckyBlockFactRevision then
        for question in pairs(RiddleLuckyBlockFactKeys) do s.learned[question] = nil end
    end
    for code, at in pairs(saved.riddleRedeemed or {}) do
        if not s.redeemed[code] then s.redeemed[code] = type(at) == "number" and at or deps.now() end
    end
    for _ in pairs(s.learned) do s.learnedCount += 1 end
    local submit, schedule
    local nextEntryId, nextAnnouncementId = 0, 0
    local function clean(value)
        return (tostring(value or ""):gsub("<[^>]*>", ""):gsub("&apos;", "'")
            :gsub("&quot;", '"'):gsub("&amp;", "&"):gsub("&lt;", "<"):gsub("&gt;", ">"))
    end
    local function normalize(value)
        return (clean(value):lower():gsub("’", "'"):gsub("'", "")
            :gsub("[^%w]+", " "):gsub("%s+", " "):match("^%s*(.-)%s*$"))
    end
    -- Keeps operators (+ - * /) so "1+2" and "1-2" never share a cache or dedupe key.
    local function signature(value)
        return normalize(value) .. "\1" .. (clean(value):lower():gsub("%s+", " "))
    end
    local function payload(value)
        local q = clean(value):gsub("’", "'"):lower()
        q = q:gsub("^%s*sammy%s+asks%s*:%s*", ""):gsub("^%s*sammy%s+says%s*:%s*", "")
        q = q:gsub("^%s*the%s+riddle%s+is%s*[:%-]?%s*", "")
            :gsub("^%s*the%s+riddle%s*:%s*", "")
            :gsub("^%s*the%s+riddle%s*%-%s*", "")
            :gsub("^%s*the%s+riddle%s+", "")
            :gsub("^%s*riddle%s+is%s*[:%-]?%s*", ""):gsub("^%s*riddle%s*:%s*", "")
            :gsub("^%s*riddle%s*%-%s*", ""):gsub("^%s*riddle%s+", "")
            :gsub("^%s*question%s+is%s*[:%-]?%s*", ""):gsub("^%s*question%s*:%s*", "")
        q = q:gsub("^%s*and%s+", "")
        return q
    end
    local function key(value)
        local q = normalize(payload(value))
        -- Exact originals remain available before these harmless wrappers.
        q = q:gsub("^what%s+is%s+", ""):gsub("^whats%s+", "")
            :gsub("^tell%s+me%s+", ""):gsub("^the%s+answer%s+to%s+", "")
        q = q:gsub("^the%s+", "")
        return q
    end
    local function encoded(value)
        -- Riddle codes should omit a leading definite article: "the sun" -> "sun".
        -- Do this before removing spaces/punctuation so the article is not fused into the answer.
        local answer = tostring(value or ""):gsub("^%s*[Tt][Hh][Ee]%s+", "")
        return (answer:gsub("[^A-Za-z0-9]", ""))
    end
    local numberWordsRepeat = {one=1,two=2,three=3,four=4,five=5,six=6,seven=7,eight=8,nine=9,ten=10,
        eleven=11,twelve=12,thirteen=13,fourteen=14,fifteen=15,sixteen=16,seventeen=17,
        eighteen=18,nineteen=19,twenty=20}
    -- Detect "answer this N times" wrappers on any clue. Used before whole-string
    -- fuzzy matching so "my cats name 4 times" does not collapse to a single "nova".
    local function parseRepeatRequest(text)
        if type(text) ~= "string" then return nil end
        local raw = tostring(text):lower()
            :gsub("['’]", ""):gsub("[?!.,;:]+$", ""):gsub("%s+", " "):match("^%s*(.-)%s*$") or ""
        if raw == "" then return nil end
        local base, count
        base, count = raw:match("^(.-)%s+(%d+)%s+times?$")
        if not base then
            local b, w = raw:match("^(.-)%s+(%a+)%s+times?$")
            if b and numberWordsRepeat[w] then base, count = b, numberWordsRepeat[w] end
        end
        if not base then base, count = raw:match("^(.-)%s+(%d+)%s*x$") end
        if not base then count, base = raw:match("^(%d+)%s+times?%s+(.+)$") end
        if not base then
            local w, b = raw:match("^(%a+)%s+times?%s+(.+)$")
            if b and numberWordsRepeat[w] then base, count = b, numberWordsRepeat[w] end
        end
        if not base then base, count = raw:match("^repeat%s+(.+)%s+(%d+)%s+times?$") end
        if not base then base, count = raw:match("^say%s+(.+)%s+(%d+)%s+times?$") end
        if not base then base, count = raw:match("^type%s+(.+)%s+(%d+)%s+times?$") end
        if not base then base, count = raw:match("^repeat%s+(.+)%s+(%d+)%s*x$") end
        if not base then return nil end
        count = tonumber(count)
        base = (base or ""):gsub("^please%s+", ""):gsub("^tell%s+me%s+", "")
            :gsub("^what%s+is%s+", ""):gsub("^whats%s+", ""):gsub("^the%s+", "")
            :gsub("^repeat%s+", ""):gsub("^say%s+", ""):gsub("^type%s+", "")
            :match("^%s*(.-)%s*$") or ""
        if not count or count < 1 or count > 25 or base == "" then return nil end
        return base, count
    end
    local function emit(message)
        if message then s.status = message end
        deps.changed(s)
    end
    local function cancel(job)
        if job and deps.cancel then deps.cancel(job) end
    end
    local function refreshEntries()
        s.answers, s.questions = {}, {}
        for _, entry in ipairs(s.entries) do
            s.answers[#s.answers + 1] = entry.value or "?"
            s.questions[#s.questions + 1] = entry.question
        end
        s.revision += 1
    end
    local function reset(message)
        cancel(s.timer)
        -- Clearing clues cannot cancel the native game request. Keep its identity
        -- and deadline until its callback releases it, even while the solver is off.
        if not s.pending then cancel(s.responseTimer) s.responseTimer = nil end
        s.timer, s.waitingForReady, s.retryAt = nil, false, nil
        s.session += 1
        s.entries, s.attempts, s.transientRetries = {}, {}, {}
        s.completedQuestion, s.lastClueAt = nil, nil
        refreshEntries()
        emit(message or (s.enabled and "Waiting For A Riddle..." or "AI Riddle Solver Off"))
    end
    local function learnedValue(question)
        local record = s.learned[question]
        if type(record) == "string" then return record end
        if type(record) == "table" then return record.answer end
    end
    local fields = {month = true, year = true, day = true, date = true, weekday = true}
    local todayFields = {
        ["date of the month today"] = "day", ["day of the month today"] = "day",
        ["todays date"] = "date", ["todays day"] = "weekday", ["todays month"] = "month", ["todays year"] = "year",
        ["date today"] = "date", ["day today"] = "weekday", ["month today"] = "month", ["year today"] = "year",
        ["today date"] = "date", ["today day"] = "weekday", ["today month"] = "month", ["today year"] = "year",
        ["todays day of the month"] = "day", ["todays date of the month"] = "day",
        ["day of the month"] = "day", ["date of the month"] = "day",
        ["what day of the month is it"] = "day", ["what day of the month is it today"] = "day",
        ["what date is it"] = "date", ["what date is it today"] = "date", ["what is the date"] = "date",
        ["what is the date today"] = "date", ["what is todays date"] = "date", ["what is todays date today"] = "date",
        ["what month is it"] = "month", ["what month is it today"] = "month", ["what is the month"] = "month",
        ["what is the current month"] = "month", ["which month are we in"] = "month", ["what month are we in"] = "month",
        ["what year is it"] = "year", ["what year is it today"] = "year", ["what is the current year"] = "year",
        ["what day of the week is it"] = "weekday", ["what day of the week is it today"] = "weekday",
        ["what day is it"] = "weekday", ["what day is it today"] = "weekday", ["what day is today"] = "weekday",
        ["what weekday is it"] = "weekday", ["what weekday is it today"] = "weekday", ["what is the weekday"] = "weekday",
        ["day of the week"] = "weekday", ["day of week"] = "weekday",
        ["day of the week today"] = "weekday", ["day of week today"] = "weekday",
        ["todays weekday"] = "weekday", ["today weekday"] = "weekday",
        ["current day of the week"] = "weekday", ["current weekday"] = "weekday",
        ["what is today"] = "weekday", ["what day are we on"] = "weekday",
    }
    local months = {"january", "february", "march", "april", "may", "june",
        "july", "august", "september", "october", "november", "december"}
    local function todayQuery(question, requested, current)
        local q = key(question)
        local field = todayFields[q]
        if not field then
            local loose = q:gsub("^what%s+is%s+", ""):gsub("^what%s+", "")
                :gsub("^the%s+", ""):gsub("%s+today$", "")
            field = todayFields[loose]
            if not field then
                if loose == "month" or loose == "current month" then field = "month"
                elseif loose == "year" or loose == "current year" then field = "year"
                elseif loose == "weekday" or loose == "day of the week" or loose == "day of week" then field = "weekday"
                elseif loose == "day of the month" or loose == "date of the month" then field = "day"
                elseif loose == "date" or loose == "current date" then field = "date" end
            end
        end
        if not field then return nil end
        field = requested or field
        local calendar = {question = q, field = field}
        current = current or (deps.currentDate and deps.currentDate() or os.date("!*t"))
        local day, month, year = current.day, current.month, current.year
        local weekdayNames = {"sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"}
        local weekdayIndex = current.wday
        if not weekdayIndex then
            -- Gregorian weekday calculation avoids relying on machine-local timezone.
            local y, m = year, month
            if m < 3 then y, m = y - 1, m + 12 end
            local k, j = y % 100, math.floor(y / 100)
            local h = (day + math.floor(13 * (m + 1) / 5) + k + math.floor(k / 4) + math.floor(j / 4) + 5 * j) % 7
            weekdayIndex = ((h + 6) % 7) + 1 -- Zeller: Saturday=0; convert to os.date's Sunday=1.
        end
        local monthName = months[month] or "unknown month"
        local record = {date = monthName .. " " .. tostring(day) .. ", " .. tostring(year),
            day = tostring(day), month = monthName, year = tostring(year), weekday = weekdayNames[weekdayIndex] or "unknown"}
        return record[field], q .. " " .. field, calendar
    end
    local function dateQuery(question, requested, current)
        local today, todayKey, calendar = todayQuery(question, requested, current)
        if calendar then return today, todayKey, calendar end
        local q = key(question)
        local field = requested
        local askedField, subject = q:match("^what%s+(%a+)%s+was%s+(.+)$")
        if fields[askedField] then field, q = askedField, subject end
        local first, tail = q:match("^(%a+)%s+(.+)$")
        if fields[first] then field, q = first, tail end
        local base, last = q:match("^(.-)%s+(%a+)$")
        if fields[last] then field, q = last, base end
        -- Explicit components override a field mentioned in the base question.
        field = requested or field
        today, todayKey, calendar = todayQuery(q, field, current)
        if calendar then return today, todayKey, calendar end
        local dateIntent = requested ~= nil or field ~= nil
            or q:find("released", 1, true) ~= nil or q:find("release", 1, true) ~= nil
            or q:match("^when%s+") ~= nil
        if not dateIntent then return nil end
        q = q:gsub("^date%s+when%s+", ""):gsub("^when%s+was%s+", "")
            :gsub("^when%s+", ""):gsub("^date%s+of%s+", ""):gsub("^the%s+", "")
            :gsub("^of%s+", "")
            :gsub("%s+was%s+released$", ""):gsub("%s+released$", "")
            :gsub("%s+release%s+date$", ""):gsub("%s+release$", "")
        local record = RiddleDates and RiddleDates[q]
        local value = record and record[field or "date"]
        if value and value ~= "" then return value, q .. " " .. (field or "date") end
        return nil
    end
    local function dynamicValue(question, original)
        if type(deps.dynamicAnswer) ~= "function" then return nil, nil, false end
        local ok, answer, matched, handled = pcall(deps.dynamicAnswer, question, original)
        if not ok then return nil, nil, false end
        -- A live resolver can recognize a question but temporarily lack a safe
        -- value. Preserve that state so stale learned/database answers do not
        -- silently replace it.
        if handled == true then
            if answer ~= nil then
                answer = tostring(answer)
                if answer == "" then answer = nil end
            end
            return answer, matched, true
        end
        if answer == nil then return nil, nil, false end
        answer = tostring(answer)
        if answer == "" then return nil, nil, false end
        return answer, matched, true
    end
    -- Conservative edit-distance matching catches small typos without guessing wildly.
    local function editDistance(a, b, limit)
        if math.abs(#a - #b) > limit then return limit + 1 end
        local previous = {}
        for j = 0, #b do previous[j] = j end
        for i = 1, #a do
            local current, rowMin = {[0] = i}, i
            local ca = a:sub(i, i)
            for j = 1, #b do
                local cost = ca == b:sub(j, j) and 0 or 1
                local value = math.min(current[j - 1] + 1, previous[j] + 1, previous[j - 1] + cost)
                current[j] = value
                if value < rowMin then rowMin = value end
            end
            if rowMin > limit then return limit + 1 end
            previous = current
        end
        return previous[#b] or 0
    end
    local function fuzzyDatabaseLookup(q)
        -- Closest-match via token index only (no full-database scan).
        if type(q) ~= "string" or #q < 2 or #q > 90 then return nil end
        local tokenIndex = s.riddleFastTokenIndex
        local bagIndex = s.riddleBagIndex
        if type(tokenIndex) ~= "table" or type(bagIndex) ~= "table" then
            tokenIndex, bagIndex = {}, {}
            -- "for" / "or" / "do" cannot be bare table keys in Luau — quote them.
            local stop = {
                ["what"] = true, ["is"] = true, ["the"] = true, ["a"] = true, ["an"] = true,
                ["of"] = true, ["to"] = true, ["for"] = true, ["and"] = true, ["or"] = true,
                ["in"] = true, ["on"] = true, ["at"] = true, ["my"] = true, ["me"] = true,
                ["how"] = true, ["much"] = true, ["does"] = true, ["do"] = true,
                ["can"] = true, ["you"] = true, ["tell"] = true,
            }
            for candidate, answer in pairs(RiddleDatabase) do
                if type(candidate) == "string" and type(answer) ~= "table" then
                    local parts, seen = {}, {}
                    for token in candidate:gmatch("[%w]+") do
                        if #token >= 2 and not stop[token] and not seen[token] then
                            seen[token] = true
                            parts[#parts + 1] = token
                            local bucket = tokenIndex[token]
                            if not bucket then
                                bucket = {}
                                tokenIndex[token] = bucket
                            end
                            bucket[#bucket + 1] = {key = candidate, answer = answer}
                        end
                    end
                    if #parts > 0 then
                        table.sort(parts)
                        local bagKey = table.concat(parts, " ")
                        local existing = bagIndex[bagKey]
                        if existing == nil then
                            bagIndex[bagKey] = answer
                        elseif existing ~= answer then
                            bagIndex[bagKey] = false
                        end
                    end
                end
            end
            s.riddleFastTokenIndex = tokenIndex
            s.riddleBagIndex = bagIndex
            if type(s.riddlePartialTokenIndex) ~= "table" then
                s.riddlePartialTokenIndex = tokenIndex
            end
        end
        local qParts, qSeen = {}, {}
        for token in q:gmatch("[%w]+") do
            if #token >= 2 and not qSeen[token] then
                qSeen[token] = true
                qParts[#qParts + 1] = token
            end
        end
        if #qParts == 0 then return nil end
        table.sort(qParts)
        local bagAnswer = bagIndex[table.concat(qParts, " ")]
        if type(bagAnswer) == "string" then
            return bagAnswer, table.concat(qParts, " ")
        end
        local scores, keys, seenKeys = {}, {}, {}
        local scored = 0
        for _, token in ipairs(qParts) do
            local bucket = tokenIndex[token]
            if bucket then
                local limit = math.min(#bucket, 80)
                for i = 1, limit do
                    local entry = bucket[i]
                    if not seenKeys[entry.key] then
                        seenKeys[entry.key] = true
                        scored += 1
                        if scored > 220 then break end
                        local overlap, cCount = 0, 0
                        local cSeen = {}
                        for ct in entry.key:gmatch("[%w]+") do
                            if #ct >= 2 and not cSeen[ct] then
                                cSeen[ct] = true
                                cCount += 1
                                if qSeen[ct] then
                                    overlap += 1
                                end
                            end
                        end
                        if overlap > 0 then
                            local score = (overlap / math.max(#qParts, cCount)) + (overlap / #qParts) * 0.35
                            if entry.key:find(q, 1, true) then
                                score += 0.4
                            end
                            local prev = scores[entry.answer]
                            if not prev or score > prev then
                                scores[entry.answer] = score
                                keys[entry.answer] = entry.key
                            end
                        end
                    end
                end
            end
            if scored > 220 then break end
        end
        local bestScore, secondScore, bestAnswer, bestKey = 0, 0, nil, nil
        for answer, score in pairs(scores) do
            if score > bestScore then
                if bestAnswer and bestAnswer ~= answer then
                    secondScore = bestScore
                end
                bestScore = score
                bestAnswer = answer
                bestKey = keys[answer]
            elseif answer ~= bestAnswer and score > secondScore then
                secondScore = score
            end
        end
        if bestAnswer and bestScore >= 0.25 and (bestScore - secondScore >= 0.03 or bestScore >= 0.45) then
            return bestAnswer, bestKey
        end
        return nil
    end

    -- Last-resort partial-question matcher: tolerates reordered words, filler words,
    -- and clues that contain only the distinctive part of a stored question. It only
    -- returns a result when the best candidate is clearly stronger than alternatives.
    local function partialDatabaseLookup(q)
        if #q < 3 or #q > 110 then return nil end
        local stop = {what=true, is=true, the=true, a=true, an=true, does=true,
            ["do"]=true, how=true, much=true, money=true, cash=true, per=true,
            second=true, of=true, ["for"]=true, me=true, tell=true, please=true,
            can=true, you=true, give=true, whats=true, which=true, ["and"]=true,
            to=true, ["in"]=true, on=true, at=true, it=true, make=true, makes=true,
            made=true, get=true, gets=true, earn=true, earns=true, generate=true,
            generates=true, generating=true, income=true, rarity=true, price=true,
            cost=true, buy=true, value=true, from=true}
        local tokens, seen = {}, {}
        -- Semantic groups let natural phrasing match stored facts without making
        -- unrelated answers eligible. Only generic question words are expanded;
        -- named Brainrots and distinctive clue words must still match.
        local meaningGroups = {
            income={income=true, earn=true, earns=true, earning=true, generate=true, generates=true,
                generating=true, make=true, makes=true, made=true, produce=true, produces=true,
                producing=true, pay=true, pays=true, paying=true, yield=true, yields=true,
                profit=true, worth=true, cash=true, money=true, revenue=true, rate=true},
            count={count=true, counts=true, number=true, total=true, exist=true, exists=true,
                existing=true, alive=true, remaining=true, amount=true, howmany=true},
            rarity={rarity=true, rare=true, rarer=true, common=true, uncommon=true, legendary=true,
                mythical=true, secret=true, brainrotgod=true},
            cost={cost=true, costs=true, price=true, priced=true, buy=true, purchase=true,
                purchasable=true, expensive=true, cheap=true, value=true},
            mutation={mutation=true, mutations=true, mutated=true, mutates=true, multiplier=true,
                multipliers=true, boost=true, boosted=true, variant=true, variants=true},
        }
        local function sameMeaning(a, b)
            if a == b then return true end
            for _, group in pairs(meaningGroups) do
                if group[a] and group[b] then return true end
            end
            return false
        end
        for token in q:gmatch("[%w]+") do
            if #token >= 2 and not stop[token] and not seen[token] then
                seen[token] = true
                tokens[#tokens + 1] = token
            end
        end
        if #tokens == 0 then return nil end
        local intent = nil
        if q:find("income",1,true) or q:find("earn",1,true) or q:find("generat",1,true)
            or q:find("make",1,true) or q:find("money",1,true) or q:find("cash",1,true)
            or q:find("per second",1,true) or q:find("produce",1,true)
            or q:find("pay",1,true) or q:find("yield",1,true) or q:find("profit",1,true)
            or q:find("revenue",1,true) or q:find("rate",1,true) then
            intent = "income"
        elseif q:find("rarity",1,true) or q:find("rare",1,true) then
            intent = "rarity"
        elseif q:find("cost",1,true) or q:find("price",1,true) or q:find("buy",1,true) then
            intent = "cost"
        elseif q:find("how many",1,true) or q:find("count",1,true) or q:find("number",1,true)
            or q:find("exist",1,true) or q:find("total",1,true) or q:find("remaining",1,true)
            or q:find("alive",1,true) or q:find("still around",1,true) then
            intent = "count"
        elseif q:find("chance",1,true) or q:find("odds",1,true) or q:find("drop rate",1,true) then
            intent = "chance"
        end
        -- Build the token index once. A query examines only candidates sharing at
        -- least one meaningful word, instead of retokenizing the entire database.
        local index = s.riddlePartialTokenIndex or s.riddleFastTokenIndex
        if type(index) ~= "table" then
            index = {}
            for candidate, answer in pairs(RiddleDatabase) do
                if type(candidate) == "string" and type(answer) ~= "table" then
                    local cTokens, cSeen = {}, {}
                    for token in candidate:gmatch("[%w]+") do
                        if #token >= 2 and not stop[token] and not cSeen[token] then
                            cSeen[token] = true
                            cTokens[#cTokens + 1] = token
                        end
                    end
                    if #cTokens > 0 then
                        local entry = {key=candidate, answer=answer, tokens=cTokens}
                        for _, token in ipairs(cTokens) do
                            local bucket = index[token]
                            if not bucket then bucket = {}; index[token] = bucket end
                            bucket[#bucket + 1] = entry
                        end
                    end
                end
            end
            s.riddlePartialTokenIndex = index
        end
        local candidates, candidateSeen = {}, {}
        local function addBucket(bucket)
            if not bucket then return end
            for _, entry in ipairs(bucket) do
                if not candidateSeen[entry.key] then
                    candidateSeen[entry.key] = true
                    candidates[#candidates + 1] = entry
                end
            end
        end
        for _, token in ipairs(tokens) do
            addBucket(index[token])
            for alias in pairs(meaningGroups.income) do if sameMeaning(token, alias) then addBucket(index[alias]) end end
            for alias in pairs(meaningGroups.count) do if sameMeaning(token, alias) then addBucket(index[alias]) end end
            for alias in pairs(meaningGroups.rarity) do if sameMeaning(token, alias) then addBucket(index[alias]) end end
            for alias in pairs(meaningGroups.cost) do if sameMeaning(token, alias) then addBucket(index[alias]) end end
            for alias in pairs(meaningGroups.mutation) do if sameMeaning(token, alias) then addBucket(index[alias]) end end
        end
        -- If the user/game announcement uses a typo, plural, or slightly different
        -- spelling, bring in candidates whose meaningful words are close too.
        -- Keep this token-level (rather than comparing whole sentences) so extra
        -- wording like "can you tell me" does not ruin an otherwise strong match.
        -- Only run expensive token typo expansion when exact token hits are sparse.
        if #candidates < 12 then
            local fuzzyTokenHits = 0
            for indexedToken, bucket in pairs(index) do
                if indexedToken ~= "" then
                    for _, token in ipairs(tokens) do
                        if indexedToken ~= token and #indexedToken >= 4 and #token >= 4 then
                            local maxWordDistance = 1
                            if math.abs(#indexedToken - #token) <= maxWordDistance
                                and editDistance(indexedToken, token, maxWordDistance) <= maxWordDistance then
                                addBucket(bucket)
                                fuzzyTokenHits += 1
                                break
                            end
                        end
                    end
                end
                if fuzzyTokenHits >= 40 then break end
            end
        end
        -- Cap candidates scored so a popular token cannot score thousands of rows.
        if #candidates > 180 then
            local trimmed = {}
            for i = 1, 180 do trimmed[i] = candidates[i] end
            candidates = trimmed
        end
        local bestScore, secondScore, bestValue, bestKey = 0, 0, nil, nil
        for _, entry in ipairs(candidates) do
            local candidateIntentOK = true
            if intent == "income" then
                candidateIntentOK = entry.key:find("income",1,true) or entry.key:find("earn",1,true)
                    or entry.key:find("generat",1,true) or entry.key:find("make",1,true)
                    or entry.key:find("per second",1,true) or entry.key:find("cash per second",1,true)
                    or entry.key:find("money per second",1,true) or entry.key:match("%f[%a]pay%f[%A]")
                    or entry.key:match("%f[%a]yield%f[%A]") or entry.key:match("%f[%a]profit%f[%A]")
                    or entry.key:find("revenue",1,true) or entry.key:match("%f[%a]rate%f[%A]")
            elseif intent == "rarity" then
                candidateIntentOK = entry.key:find("rarity",1,true) ~= nil
            elseif intent == "cost" then
                candidateIntentOK = entry.key:find("cost",1,true) or entry.key:find("price",1,true)
                    or entry.key:find("buy price",1,true)
            elseif intent == "count" then
                candidateIntentOK = entry.key:find("how many",1,true) or entry.key:find("count",1,true)
                    or entry.key:find("total",1,true) or entry.key:find("number",1,true)
                    or entry.key:find("exist",1,true) or entry.key:find("tracker",1,true)
                    or entry.key:find("remaining",1,true) or entry.key:find("alive",1,true)
            elseif intent == "mutation" then
                candidateIntentOK = entry.key:find("mutation",1,true) or entry.key:find("multiplier",1,true)
                    or entry.key:find("boost",1,true) or entry.key:find("variant",1,true)
            elseif intent == "chance" then
                candidateIntentOK = entry.key:find("chance",1,true) or entry.key:find("odds",1,true)
                    or entry.key:find("drop rate",1,true)
            end
            if candidateIntentOK then
            local matched = 0
            for _, token in ipairs(tokens) do
                local hit = false
                for _, ct in ipairs(entry.tokens) do
                    if ct == token or sameMeaning(ct, token) then
                        hit = true; break
                    elseif #token >= 4 and #ct >= 4 and
                        (ct:find(token,1,true) or token:find(ct,1,true)) then
                        hit = true; break
                    end
                end
                -- Typo compare only if no exact/substring hit (keeps common cases cheap).
                if not hit then
                    for _, ct in ipairs(entry.tokens) do
                        if #token >= 4 and #ct >= 4 and math.abs(#token - #ct) <= 1
                            and editDistance(token, ct, 1) <= 1 then
                            hit = true; break
                        end
                    end
                end
                if hit then matched += 1 end
            end
            if matched > 0 then
                local score = matched / math.max(#tokens, #entry.tokens)
                local queryCoverage = matched / #tokens
                score += queryCoverage * 0.22
                if matched >= math.min(2, #tokens) then score += 0.18 end
                if entry.key:find(q,1,true) then score += 0.35 end
                if score > bestScore then
                    if bestValue ~= nil and entry.answer ~= bestValue then secondScore = bestScore end
                    bestScore, bestValue, bestKey = score, entry.answer, entry.key
                elseif entry.answer ~= bestValue and score > secondScore then
                    secondScore = score
                end
            end
            end
        end
        -- Closest-match policy: return the best unique candidate whenever score is usable.
        if bestValue ~= nil and bestScore >= 0.22 and bestScore - secondScore >= 0.02 then
            return bestValue, bestKey
        end
        if bestValue ~= nil and bestScore >= 0.35 then
            return bestValue, bestKey
        end
        if bestValue ~= nil and #tokens >= 1 and bestScore >= 0.18 and bestScore - secondScore >= 0.05 then
            return bestValue, bestKey
        end
        return nil
    end
    local function arithmeticAnswer(question)
        -- Math solver: normalize wording, tokenize, parse with operator precedence, evaluate.
        -- Also solves one-variable equations (linear, quadratic, and numeric root scanning).
        local NumberWords = {zero = 0, one = 1, two = 2, three = 3, four = 4, five = 5, six = 6, seven = 7,
            eight = 8, nine = 9, ten = 10, eleven = 11, twelve = 12, thirteen = 13, fourteen = 14,
            fifteen = 15, sixteen = 16, seventeen = 17, eighteen = 18, nineteen = 19, twenty = 20,
            thirty = 30, forty = 40, fifty = 50, sixty = 60, seventy = 70, eighty = 80, ninety = 90,
            hundred = 100}
        local Functions = {sqrt = true, cbrt = true, abs = true, sin = true, cos = true, tan = true,
            asin = true, acos = true, atan = true, log = true, ln = true, exp = true, floor = true,
            ceil = true, round = true, fact = true}
        local Constants = {pi = math.pi, e = math.exp(1), tau = 2 * math.pi}

        local function finite(x) return x ~= nil and x == x and x > -math.huge and x < math.huge end

        local s = clean(question):lower()
        if #s == 0 or #s > 200 then return nil end
        s = s:gsub("×", "*"):gsub("÷", "/"):gsub("−", "-"):gsub("'", "")
        s = s:gsub("%?", " "):gsub(":", " ")

        -- Strip leading filler such as "what is", "calculate", "solve for x".
        local fillers = {"what is ", "whats ", "what equals ", "what does ", "how much is ", "calculate ",
            "compute ", "evaluate ", "simplify ", "solve ", "find ", "answer ", "result of ", "the "}
        local changed = true
        while changed do
            changed = false
            s = s:match("^%s*(.-)%s*$")
            for _, filler in ipairs(fillers) do
                if s:sub(1, #filler) == filler then
                    s = s:sub(#filler + 1)
                    changed = true
                end
            end
            local stripped = s:gsub("^for%s+%a%s+", "")
            if stripped ~= s then s = stripped changed = true end
        end

        -- Sentence forms that rearrange operands.
        s = s:gsub("^divide%s+(.-)%s+by%s+(.-)$", "%1 / %2")
        s = s:gsub("^subtract%s+(.-)%s+from%s+(.-)$", "%2 - %1")
        s = s:gsub("^add%s+(.-)%s+to%s+(.-)$", "%1 + %2")
        s = s:gsub("^sum%s+of%s+(.-)%s+and%s+(.-)$", "%1 + %2")
        s = s:gsub("^product%s+of%s+(.-)%s+and%s+(.-)$", "%1 * %2")
        s = s:gsub("^difference%s+between%s+(.-)%s+and%s+(.-)$", "%1 - %2")
        s = s:gsub("%s+equals%s+", " = "):gsub("%s+equal%s+to%s+", " = ")

        -- Word operators and functions. Each pattern must match whole words.
        local replacements = {
            {"raised%s+to%s+the%s+power%s+of", "^"}, {"raised%s+to%s+the%s+power", "^"},
            {"to%s+the%s+power%s+of", "^"}, {"to%s+the%s+power", "^"}, {"raised%s+to", "^"},
            {"multiplied%s+by", "*"}, {"multiplied", "*"}, {"times", "*"},
            {"divided%s+by", "/"}, {"divide%s+by", "/"}, {"divided", "/"}, {"over", "/"},
            {"plus", "+"}, {"minus", "-"},
            {"squared", "^2"}, {"cubed", "^3"},
            {"square%s+root%s+of", "sqrt "}, {"square%s+root", "sqrt "},
            {"cube%s+root%s+of", "cbrt "}, {"cube%s+root", "cbrt "},
            {"absolute%s+value%s+of", "abs "}, {"absolute%s+value", "abs "},
            {"natural%s+log%s+of", "ln "}, {"natural%s+log", "ln "}, {"ln%s+of", "ln "},
            {"logarithm%s+of", "log "}, {"log%s+of", "log "},
            {"factorial%s+of", "fact "},
            {"sine%s+of", "sin "}, {"cosine%s+of", "cos "}, {"tangent%s+of", "tan "},
            {"half%s+of", "0.5*"}, {"triple%s+", "3*"}, {"double%s+", "2*"},
            {"percent%s+of", "%% of"}, {"percent", "%%"},
            {"modulo", "%%"}, {"mod", "%%"},
            {"%*%*", "^"},
        }
        for _, pair in ipairs(replacements) do
            local pattern = pair[1]
            if pattern:match("^%a") then pattern = "%f[%a]" .. pattern end
            if pattern:match("%a$") then pattern = pattern .. "%f[%A]" end
            s = s:gsub(pattern, pair[2])
        end
        s = s:gsub("remainder%s+of%s+(.-)%s*/%s*(.-)$", "%1 %% %2")
        -- "5 factorial" -> "5!" and "(12) factorial" stays as a factorial call.
        s = s:gsub("(%d+%.?%d*)%s*factorial", "%1!")

        -- Number words become digits ("seven times eight", "twenty one").
        s = s:gsub("%a+", function(word)
            if NumberWords[word] then return tostring(NumberWords[word]) end
            return word
        end)
        s = s:gsub("(%d0)%s+(%d)", "%1+%2")

        -- Tokenize.
        local list = {}
        local i, n = 1, #s
        local function isValueEnd(tok)
            if not tok then return false end
            if tok.t == "num" or tok.t == ")" or tok.t == "!" then return true end
            if tok.t == "id" then return Constants[tok.v] ~= nil or #tok.v == 1 end
            return false
        end
        while i <= n do
            local c = s:sub(i, i)
            if c:match("%s") then
                i = i + 1
            elseif c:match("%d") or (c == "." and s:sub(i + 1, i + 1):match("%d")) then
                local number = s:match("^%d+%.?%d*e[%+%-]?%d+", i) or s:match("^%d+%.?%d*", i) or s:match("^%.%d+", i)
                list[#list + 1] = {t = "num", v = tonumber(number)}
                i = i + #number
            elseif c:match("%a") then
                local word = s:match("^%a+", i)
                i = i + #word
                local nextChar = s:match("^%s*(.)", i) or ""
                if word == "x" and isValueEnd(list[#list]) and nextChar:match("[%d%(%.]") then
                    -- "3x5" or "3 x (2)" means multiplication.
                    list[#list + 1] = {t = "*"}
                elseif #word > 1 and not Functions[word] and not Constants[word] and word ~= "of" then
                    return nil
                else
                    list[#list + 1] = {t = "id", v = word}
                end
            elseif c:match("[%+%-%*/%^%%!%(%),=]") then
                list[#list + 1] = {t = c}
                i = i + 1
            else
                return nil
            end
        end
        if #list == 0 then return nil end

        local tokens, pos = list, 1
        local vars = {}
        local parseExpr, parseTerm, parseUnary, parsePower, parsePostfix

        local function startsPrimary(tok)
            if not tok then return false end
            if tok.t == "num" or tok.t == "(" then return true end
            if tok.t == "id" then return tok.v ~= "of" end
            return false
        end

        local function parsePrimary()
            local tok = tokens[pos]
            if not tok then return nil end
            if tok.t == "num" then
                pos = pos + 1
                return {k = "num", v = tok.v}
            end
            if tok.t == "(" then
                pos = pos + 1
                local inner = parseExpr()
                if not inner or not tokens[pos] or tokens[pos].t ~= ")" then return nil end
                pos = pos + 1
                return inner
            end
            if tok.t == "id" then
                local name = tok.v
                if Functions[name] then
                    pos = pos + 1
                    local argument
                    if tokens[pos] and tokens[pos].t == "(" then
                        pos = pos + 1
                        argument = parseExpr()
                        if not argument or not tokens[pos] or tokens[pos].t ~= ")" then return nil end
                        pos = pos + 1
                    else
                        argument = parsePower()
                    end
                    if not argument then return nil end
                    return {k = "fn", name = name, a = argument}
                end
                if Constants[name] then
                    pos = pos + 1
                    return {k = "num", v = Constants[name]}
                end
                if #name == 1 then
                    pos = pos + 1
                    vars[name] = true
                    return {k = "var", name = name}
                end
            end
            return nil
        end

        function parsePostfix()
            local node = parsePrimary()
            if not node then return nil end
            while true do
                local tok = tokens[pos]
                if tok and tok.t == "!" then
                    pos = pos + 1
                    node = {k = "fact", a = node}
                elseif tok and tok.t == "%" and not startsPrimary(tokens[pos + 1]) then
                    pos = pos + 1
                    local nextTok = tokens[pos]
                    if nextTok and nextTok.t == "id" and nextTok.v == "of" then
                        pos = pos + 1
                        local rhs = parseUnary()
                        if not rhs then return nil end
                        node = {k = "bin", op = "*", a = {k = "bin", op = "/", a = node, b = {k = "num", v = 100}}, b = rhs}
                    else
                        node = {k = "bin", op = "/", a = node, b = {k = "num", v = 100}}
                    end
                else
                    break
                end
            end
            return node
        end

        function parsePower()
            local base = parsePostfix()
            if not base then return nil end
            if tokens[pos] and tokens[pos].t == "^" then
                pos = pos + 1
                local exponent = parseUnary()
                if not exponent then return nil end
                return {k = "bin", op = "^", a = base, b = exponent}
            end
            return base
        end

        function parseUnary()
            local tok = tokens[pos]
            if tok and (tok.t == "-" or tok.t == "+") then
                pos = pos + 1
                local inner = parseUnary()
                if not inner then return nil end
                if tok.t == "-" then return {k = "neg", a = inner} end
                return inner
            end
            return parsePower()
        end

        function parseTerm()
            local left = parseUnary()
            if not left then return nil end
            while true do
                local tok = tokens[pos]
                if not tok then break end
                if tok.t == "*" or tok.t == "/" or (tok.t == "%" and startsPrimary(tokens[pos + 1])) then
                    pos = pos + 1
                    local right = parseUnary()
                    if not right then return nil end
                    left = {k = "bin", op = tok.t, a = left, b = right}
                elseif startsPrimary(tok) then
                    -- Implicit multiplication: 2pi, 3(4), 2sqrt 9.
                    local right = parseUnary()
                    if not right then return nil end
                    left = {k = "bin", op = "*", a = left, b = right}
                else
                    break
                end
            end
            return left
        end

        function parseExpr()
            local left = parseTerm()
            if not left then return nil end
            while tokens[pos] and (tokens[pos].t == "+" or tokens[pos].t == "-") do
                local op = tokens[pos].t
                pos = pos + 1
                local right = parseTerm()
                if not right then return nil end
                left = {k = "bin", op = op, a = left, b = right}
            end
            return left
        end

        local function parseWhole(list2)
            tokens, pos = list2, 1
            if #list2 == 0 then return nil end
            local node = parseExpr()
            if not node or pos <= #tokens then return nil end
            return node
        end

        local function evaluate(node, env)
            if node.k == "num" then return node.v end
            if node.k == "var" then return env[node.name] end
            if node.k == "neg" then
                local a = evaluate(node.a, env)
                return a and -a or nil
            end
            if node.k == "fact" then
                local a = evaluate(node.a, env)
                if not a or a < 0 or a > 170 or a ~= math.floor(a) then return nil end
                local product = 1
                for j = 2, a do product = product * j end
                return product
            end
            if node.k == "fn" then
                local a = evaluate(node.a, env)
                if not a then return nil end
                local f, r = node.name, nil
                if f == "sqrt" then
                    if a < 0 then return nil end
                    r = math.sqrt(a)
                elseif f == "cbrt" then
                    r = a < 0 and -((-a) ^ (1 / 3)) or a ^ (1 / 3)
                elseif f == "abs" then r = math.abs(a)
                elseif f == "sin" then r = math.sin(a)
                elseif f == "cos" then r = math.cos(a)
                elseif f == "tan" then r = math.tan(a)
                elseif f == "asin" then r = math.asin(a)
                elseif f == "acos" then r = math.acos(a)
                elseif f == "atan" then r = math.atan(a)
                elseif f == "log" then
                    if a <= 0 then return nil end
                    r = math.log(a, 10)
                elseif f == "ln" then
                    if a <= 0 then return nil end
                    r = math.log(a)
                elseif f == "exp" then r = math.exp(a)
                elseif f == "floor" then r = math.floor(a)
                elseif f == "ceil" then r = math.ceil(a)
                elseif f == "round" then r = math.floor(a + 0.5)
                elseif f == "fact" then return evaluate({k = "fact", a = {k = "num", v = a}}, env)
                end
                if not finite(r) then return nil end
                return r
            end
            local a = evaluate(node.a, env)
            local b = evaluate(node.b, env)
            if not a or not b then return nil end
            local op, r = node.op, nil
            if op == "+" then r = a + b
            elseif op == "-" then r = a - b
            elseif op == "*" then r = a * b
            elseif op == "/" then
                if b == 0 then return nil end
                r = a / b
            elseif op == "%" then
                if b == 0 then return nil end
                r = a - b * math.floor(a / b)
            elseif op == "^" then r = a ^ b
            end
            if not finite(r) then return nil end
            return r
        end

        local function format(x)
            if not finite(x) then return "undefined" end
            if math.abs(x) >= 1e15 then return string.format("%g", x) end
            local rounded = math.floor(x + 0.5)
            if math.abs(x - rounded) < 1e-9 then
                if rounded == 0 then return "0" end
                return string.format("%.0f", rounded)
            end
            local text = string.format("%.6f", x):gsub("0+$", ""):gsub("%.$", "")
            return text
        end

        local function solveFor(name, diff)
            local function f(value) return evaluate(diff, {[name] = value}) end
            local f0, f1, fm1, f2 = f(0), f(1), f(-1), f(2)
            if f0 and f1 and fm1 and f2 then
                -- Fit a*x^2 + b*x + c through three points and check it against a fourth.
                local c = f0
                local a = (f1 + fm1) / 2 - c
                local b = (f1 - fm1) / 2
                if math.abs(4 * a + 2 * b + c - f2) <= 1e-7 * (1 + math.abs(f2)) then
                    local eps = 1e-10
                    if math.abs(a) < eps then
                        if math.abs(b) < eps then
                            if math.abs(c) < eps then return name .. " can be any number" end
                            return "no solution"
                        end
                        return name .. " = " .. format(-c / b)
                    end
                    local disc = b * b - 4 * a * c
                    if disc < -eps then return "no real solution" end
                    if math.abs(disc) <= eps then return name .. " = " .. format(-b / (2 * a)) end
                    local root = math.sqrt(disc)
                    local r1 = (-b - root) / (2 * a)
                    local r2 = (-b + root) / (2 * a)
                    if r1 > r2 then r1, r2 = r2, r1 end
                    return name .. " = " .. format(r1) .. ", " .. format(r2)
                end
            end
            -- Other equations: scan for sign changes and refine each one by bisection.
            local roots = {}
            local function addRoot(r)
                for _, existing in ipairs(roots) do
                    if math.abs(existing - r) < 1e-7 then return end
                end
                roots[#roots + 1] = r
            end
            local lo, hi, steps = -1000, 1000, 40000
            local dx = (hi - lo) / steps
            local xPrev, yPrev = lo, f(lo)
            for k = 1, steps do
                local xNow = lo + k * dx
                local yNow = f(xNow)
                if yNow ~= nil and yNow == 0 then
                    addRoot(xNow)
                elseif yPrev ~= nil and yNow ~= nil and yPrev * yNow < 0 then
                    local a, b, fa = xPrev, xNow, yPrev
                    for _ = 1, 80 do
                        local mid = (a + b) / 2
                        local fm = f(mid)
                        if fm == nil then break end
                        if fm == 0 then
                            a, b = mid, mid
                            break
                        end
                        if (fa < 0) == (fm < 0) then
                            a, fa = mid, fm
                        else
                            b = mid
                        end
                    end
                    addRoot((a + b) / 2)
                end
                xPrev, yPrev = xNow, yNow
                if #roots >= 4 then break end
            end
            if #roots == 0 then return "no real solution found" end
            table.sort(roots)
            local parts = {}
            for _, r in ipairs(roots) do parts[#parts + 1] = format(r) end
            return name .. " = " .. table.concat(parts, ", ")
        end

        -- Split on a single "=" and parse each side.
        local eq = nil
        for idx, tok in ipairs(list) do
            if tok.t == "=" then
                if eq then return nil end
                eq = idx
            end
        end
        local left, right
        if eq then
            local leftList, rightList = {}, {}
            for idx = 1, eq - 1 do leftList[#leftList + 1] = list[idx] end
            for idx = eq + 1, #list do rightList[#rightList + 1] = list[idx] end
            left = parseWhole(leftList)
            if not left then return nil end
            if #rightList > 0 then
                right = parseWhole(rightList)
                if not right then return nil end
            end
        else
            left = parseWhole(list)
            if not left then return nil end
        end

        local varName = nil
        for name in pairs(vars) do
            if varName then return nil end
            varName = name
        end

        if varName == nil then
            return format(evaluate(left, {}))
        end
        if not eq then return nil end
        local diff = right and {k = "bin", op = "-", a = left, b = right} or left
        return solveFor(varName, diff)
    end
    -- Weighted best-match finder. Distinctive words (rare across the database) count
    -- more than common ones like "capital" or "country", every candidate gets scored
    -- (rare words first, no 80-entry cutoff), and unknown words are typo-corrected
    -- against the vocabulary. Returns a result only when one answer clearly wins.
    local weightedLookup = (function()
    local WeightedStop = {
        what = true, is = true, the = true, a = true, an = true, of = true, to = true,
        ["for"] = true, ["and"] = true, ["or"] = true, ["in"] = true, on = true, at = true,
        my = true, me = true, how = true, does = true, ["do"] = true, can = true, you = true,
        tell = true, which = true, who = true, where = true, when = true, was = true,
        are = true, it = true, its = true, that = true, this = true, with = true, by = true,
        from = true, please = true, i = true, quick = true, question = true, name = false,
    }
    local function buildWeightedIndex()
        local rows, df, seenKeys = {}, {}, {}
        for candidate, answer in pairs(RiddleDatabase) do
            if type(candidate) == "string" and type(answer) ~= "table" and not seenKeys[candidate] then
                seenKeys[candidate] = true
                local lowered = string.lower(candidate)
                local tokens, seen = {}, {}
                for token in lowered:gmatch("%w+") do
                    if #token >= 2 and not WeightedStop[token] and not seen[token] then
                        seen[token] = true
                        tokens[#tokens + 1] = token
                    end
                end
                if #tokens > 0 then
                    rows[#rows + 1] = {key = lowered, answer = tostring(answer), tokens = tokens}
                    for _, token in ipairs(tokens) do
                        df[token] = (df[token] or 0) + 1
                    end
                end
            end
        end
        local total, idf, vocab = #rows, {}, {}
        for token, count in pairs(df) do
            idf[token] = math.log(1 + total / count)
            vocab[#vocab + 1] = token
        end
        local tokenIndex = {}
        for rowIndex, row in ipairs(rows) do
            local weight = 0
            for _, token in ipairs(row.tokens) do
                weight += idf[token]
                local bucket = tokenIndex[token]
                if not bucket then
                    bucket = {}
                    tokenIndex[token] = bucket
                end
                bucket[#bucket + 1] = rowIndex
            end
            row.weight = weight
        end
        return {rows = rows, tokenIndex = tokenIndex, idf = idf, vocab = vocab}
    end
    local function weightedLookup(q)
        if type(q) ~= "string" or #q < 3 or #q > 140 then return nil end
        local index = s.riddleWeightedIndex
        if type(index) ~= "table" then
            index = buildWeightedIndex()
            s.riddleWeightedIndex = index
        end
        local idf = index.idf
        local qTokens, qSeen = {}, {}
        for token in q:gmatch("%w+") do
            if #token >= 2 and not WeightedStop[token] and not qSeen[token] then
                qSeen[token] = true
                qTokens[#qTokens + 1] = token
            end
        end
        if #qTokens == 0 then return nil end
        -- Typo correction: an unknown word maps to the nearest known word.
        -- One edit for 4-6 letter words, two edits for longer words.
        local qSet, corrected, qWeight = {}, {}, 0
        for _, token in ipairs(qTokens) do
            local word = token
            if not idf[token] and #token >= 4 then
                local maxDist = #token >= 7 and 2 or 1
                local bestWord, bestDist = nil, maxDist + 1
                for _, candidate in ipairs(index.vocab) do
                    if math.abs(#candidate - #token) <= maxDist and #candidate >= 2 then
                        local d = editDistance(token, candidate, maxDist)
                        if d < bestDist then
                            bestWord, bestDist = candidate, d
                        end
                    end
                end
                if bestWord then word = bestWord end
            end
            if idf[word] and not qSet[word] then
                qSet[word] = true
                corrected[#corrected + 1] = word
                qWeight += idf[word]
            end
        end
        if #corrected == 0 or qWeight <= 0 then return nil end
        -- Rarest words first, so distinctive words always get their candidates scored.
        table.sort(corrected, function(a, b)
            return #index.tokenIndex[a] < #index.tokenIndex[b]
        end)
        local scores, keys, visited, budget = {}, {}, {}, 6000
        for _, word in ipairs(corrected) do
            for _, rowIndex in ipairs(index.tokenIndex[word]) do
                if not visited[rowIndex] then
                    visited[rowIndex] = true
                    budget -= 1
                    local row = index.rows[rowIndex]
                    local matched = 0
                    for _, token in ipairs(row.tokens) do
                        if qSet[token] then matched += idf[token] end
                    end
                    if matched > 0 then
                        -- Dice similarity: rewards covering the clue's words and penalizes
                        -- stored questions that contain lots of unrelated content.
                        local dice = (2 * matched) / (qWeight + row.weight)
                        if (scores[row.answer] or 0) < dice then
                            scores[row.answer] = dice
                            keys[row.answer] = row.key
                        end
                    end
                end
            end
            if budget <= 0 then break end
        end
        local best, second, bestAnswer = 0, 0, nil
        for answer, score in pairs(scores) do
            if score > best then
                second, best, bestAnswer = best, score, answer
            elseif score > second then
                second = score
            end
        end
        if bestAnswer and best >= 0.45 and (best - second >= 0.04 or best >= 0.7) then
            return bestAnswer, keys[bestAnswer]
        end
        return nil
    end
    return weightedLookup
    end)()

    -- Personal answers you saved (my car color, my cats name, my real life name, my favorite brainrot).
    -- Checked before live game lookups, since a live resolver can claim a question and return nothing.
    local PersonalMarkers = {" my ", " sammy ", " real name ", " real life name "}
    local function personalDatabaseLookup(question)
        local text = " " .. normalize(question) .. " "
        text = (text:gsub(" fav ", " favorite "))
        text = (text:gsub(" fave ", " favorite "))
        text = (text:gsub(" irl ", " real life "))
        text = (text:gsub("^ the ", " "))
        text = (text:gsub("^ what is ", " "))
        text = (text:gsub("^ whats ", " "))
        text = (text:gsub("^ tell me ", " "))
        text = text:match("^%s*(.-)%s*$") or ""
        if text == "" then return nil end
        -- Live game data (mutations, traits, current or counted things) keeps priority.
        local padded = " " .. text .. " "
        for _, word in ipairs({" mutation", " trait", " exist", " count", " how many", " current", " now ",
            " today", " best", " new ", " latest", " income", " rarity", " cost", " chance", " released"}) do
            if padded:find(word, 1, true) then return nil end
        end
        local personal = false
        for _, marker in ipairs(PersonalMarkers) do
            if (" " .. text .. " "):find(marker, 1, true) then personal = true break end
        end
        if not personal then return nil end
        local candidates = {text}
        local withoutMy = (" " .. text .. " "):gsub(" my ", " ")
        withoutMy = withoutMy:match("^%s*(.-)%s*$") or ""
        if withoutMy ~= text then candidates[#candidates + 1] = withoutMy end
        for _, candidate in ipairs(candidates) do
            local value = RiddleDatabase[candidate]
            if type(value) == "string" and value ~= "" then return value, candidate end
        end
        return nil
    end
    local function exact(question, current)
        local arithmetic = arithmeticAnswer(question)
        if arithmetic then return arithmetic, normalize(question), "Math" end
        local original, q = normalize(question), key(question)
        -- Resolve "today" at the time of the clue, before saved facts can go stale.
        local today, todayKey, calendar = todayQuery(q, nil, current)
        if calendar then return today, todayKey, "Current Date", calendar end
        local dated, datedKey, datedCalendar = dateQuery(q, nil, current)
        if datedCalendar then return dated, datedKey, "Current Date", datedCalendar end
        -- Live mutation, trait, and existence data must outrank saved answers.
        -- Pass the raw clue so punctuation/compound boundaries remain visible
        -- to the live adapter; it performs its own normalization.
        local personal, personalKey = personalDatabaseLookup(question)
        if personal then return personal, personalKey, "Database" end
        local live, liveKey, liveHandled = dynamicValue(question, question)
        if liveHandled then return live, liveKey or q, "Live" end
        local value = learnedValue(q) or learnedValue(original)
        if value then return value, q, "Learned" end
        if dated then return dated, datedKey, "Database" end
        value = RiddleDatabase[original] or RiddleDatabase[q]
        if value then return value, q, "Database" end
        -- Memoize stable database search results across announcements. This avoids
        -- repeating expensive typo/partial matching for the same normalized clue.
        local searchCache = s.riddleStableSearchCache
        if type(searchCache) ~= "table" then searchCache = {}; s.riddleStableSearchCache = searchCache end
        local cachedSearch = searchCache[q]
        if cachedSearch then
            if cachedSearch.value ~= false then
                return cachedSearch.value, cachedSearch.matched, cachedSearch.source
            end
            return nil
        end
        local mathish = q:find("%d") and (q:find("plus", 1, true) or q:find("minus", 1, true)
            or q:find("times", 1, true) or q:find("divid", 1, true) or q:find("multipl", 1, true)
            or q:find("squared", 1, true) or q:find("cubed", 1, true) or q:find("root", 1, true)
            or q:find("percent", 1, true) or q:find("factorial", 1, true) or q:find("power", 1, true))
        if mathish then return nil end
        local weightedValue, weightedKey = weightedLookup(q)
        if weightedValue then
            searchCache[q] = {value=weightedValue, matched=weightedKey, source="Fuzzy Database"}
            return weightedValue, weightedKey, "Fuzzy Database"
        end
        local fuzzyValue, fuzzyKey = fuzzyDatabaseLookup(q)
        if fuzzyValue then
            searchCache[q] = {value=fuzzyValue, matched=fuzzyKey, source="Fuzzy Database"}
            return fuzzyValue, fuzzyKey, "Fuzzy Database"
        end
        local partialValue, partialKey = partialDatabaseLookup(q)
        if partialValue then
            searchCache[q] = {value=partialValue, matched=partialKey, source="Partial Match"}
            return partialValue, partialKey, "Partial Match"
        end
        searchCache[q] = {value=false}
        -- Bound memory if many unique clues are received in one session.
        local count = 0
        for _ in pairs(searchCache) do count += 1 end
        if count > 500 then s.riddleStableSearchCache = {[q] = {value=false}} end
    end
    local function resolve(value)
        local raw = payload(value)
        -- All date components in this announcement use one calendar snapshot.
        -- The answer stays attached to its clue through midnight and cooldowns.
        local current = deps.currentDate and deps.currentDate() or os.date("!*t")
        -- Reuse stable lookups during this one announcement. Splitting and
        -- partitioning can ask the same clue several times; caching these
        -- deterministic results avoids repeating fuzzy/database scans without
        -- caching live game state or changing answer priority.
        local exactCache = {}
        local function cachedExact(question, snapshot)
            local cacheKey = signature(question)
            local cached = exactCache[cacheKey]
            if cached then return cached.answer, cached.matched, cached.source, cached.calendar end
            local answer, matched, source, calendar = exact(question, snapshot)
            if answer ~= nil and source ~= "Live" and source ~= "Current Date" and not calendar then
                exactCache[cacheKey] = {answer=answer, matched=matched, source=source, calendar=calendar}
            end
            return answer, matched, source, calendar
        end
        local clauses = {}
        -- Split explicit punctuation first, but do NOT split every "and" or "or":
        -- many SAB names contain conjunctions (Garama and Madundung, Chipso and Queso, etc.).
        raw = raw:gsub("[\r\n;]+", ","):gsub("%s*&%s*", ",")
        -- Math such as 1+1, 25+5, 10/2 or 5 - 3 is one clue. Only other segments
        -- get split on plus, slash, hyphen, "plus", or ampersand separators.
        local function splitSegment(segment)
            if arithmeticAnswer(segment) ~= nil then return segment end
            local part = segment:gsub("%s+[Pp][Ll][Uu][Ss]%s+", ",")
            part = part:gsub("/", ","):gsub("%s+%-%s+", ","):gsub("—", ","):gsub("–", ",")
            part = part:gsub("%s*&%s*", ","):gsub("%s*%+%s*", ",")
            return part
        end
        local pieces = {}
        for segment in (raw .. ","):gmatch("(.-),") do
            pieces[#pieces + 1] = splitSegment(segment)
        end
        raw = table.concat(pieces, ",")
        local function startsNewQuestion(text)
            local first = (text:match("^%s*(%a+)") or ""):lower()
            if first == "what" or first == "whats" or first == "who" or first == "how"
                or first == "where" or first == "when" or first == "why" or first == "which"
                or first == "my" or first == "tell" or first == "sammy" then return true end
            local two = (text:match("^%s*(%a+%s+%a+)") or ""):lower()
            -- Some announcements join independent clues with phrases such as
            -- "and that means ..." instead of repeating a question word.
            if two == "that means" or two == "clue is" or two == "next clue"
                or two == "my cat" or two == "my cats" or two == "my name"
                or two == "cat name" or two == "cats name" then return true end
            return two == "name of" or two == "color of" or two == "colour of"
        end
        local function splitQuestionAndOr(segment, output)
            local startAt, searchAt = 1, 1
            while searchAt <= #segment do
                local andFirst, andLast = segment:find("%s+[Aa][Nn][Dd]%s+", searchAt)
                local orFirst, orLast = segment:find("%s+[Oo][Rr]%s+", searchAt)
                local first, last = andFirst, andLast
                if orFirst and (not first or orFirst < first) then first, last = orFirst, orLast end
                if not first then
                    local tail = segment:sub(startAt):match("^%s*(.-)%s*$") or ""
                    if tail ~= "" then output[#output + 1] = tail end
                    return
                end
                local tail = segment:sub(last + 1)
                if startsNewQuestion(tail) then
                    local head = segment:sub(startAt, first - 1):match("^%s*(.-)%s*$")
                    if head ~= "" then output[#output + 1] = head end
                    startAt, searchAt = last + 1, last + 1
                else
                    -- Keep the original segment start; this conjunction may be part of a name.
                    searchAt = last + 1
                end
            end
            local tail = segment:sub(startAt):match("^%s*(.-)%s*$") or ""
            if tail ~= "" then output[#output + 1] = tail end
        end
        -- Split compact announcements that omit punctuation between clues, e.g.
        -- "what is X where is Y". Only accept a boundary when the text before
        -- it already resolves to a known answer; this avoids splitting names that
        -- happen to contain words such as "where" or "what".
        local function splitImplicitQuestionBoundaries(segment, depth)
            depth = depth or 0
            if depth >= 8 then
                splitQuestionAndOr(segment, clauses)
                return
            end
            local starters = {
                "what", "whats", "who", "how", "where", "when", "why", "which",
                "my", "tell", "sammy", "name of", "color of", "colour of",
                "current mutation", "current trait", "date of", "day of"
            }
            local bestPos
            for _, starter in ipairs(starters) do
                local search = 2
                while search <= #segment do
                    local first, last = segment:find("%s+" .. starter:gsub(" ", "%%s+") .. "%s+", search)
                    if not first then break end
                    local left = segment:sub(1, first - 1):match("^%s*(.-)%s*$") or ""
                    local answer, _, source, calendar = cachedExact(left, current)
                    if left ~= "" and (answer ~= nil or calendar ~= nil or source == "Live") then
                        if not bestPos or first < bestPos then bestPos = first end
                        break
                    end
                    search = last + 1
                end
            end
            if bestPos then
                local left = segment:sub(1, bestPos - 1):match("^%s*(.-)%s*$") or ""
                local right = segment:sub(bestPos + 1):match("^%s*(.-)%s*$") or ""
                if left ~= "" then splitQuestionAndOr(left, clauses) end
                if right ~= "" then splitImplicitQuestionBoundaries(right, depth + 1) end
            else
                splitQuestionAndOr(segment, clauses)
            end
        end
        for segment in raw:gmatch("[^,]+") do
            -- A conjunction often remains at the beginning of the next chunk
            -- after punctuation splitting: "my name, and my cat's name".
            -- Handle each prefix explicitly (Lua patterns do not support alternation).
            segment = segment:gsub("^%s*and%s+", ""):gsub("^%s*then%s+", "")
                :gsub("^%s*plus%s+", ""):gsub("^%s*also%s+", "")
            segment = segment:match("^%s*(.-)%s*$") or ""
            if segment ~= "" then splitImplicitQuestionBoundaries(segment) end
        end
        local function qualifierFields(value)
            local result = {}
            for field in normalize(value):gmatch("%S+") do
                if field ~= "and" then
                    if not fields[field] then return nil end
                    result[#result + 1] = field
                end
            end
            return #result > 0 and result or nil
        end
        -- Also accept an unpunctuated date tail: "released month and year".
        if #clauses == 1 then
            local base, tail = raw:match("^(.-)%s+(%a+%s+and%s+.+)$")
            if base and qualifierFields(tail) then clauses = {base, tail} end
        end
        if #clauses > 1 then
            local requested, qualifiers = {}, true
            for i = 2, #clauses do
                local components = qualifierFields(clauses[i])
                if not components then qualifiers = false break end
                for _, field in ipairs(components) do requested[#requested + 1] = field end
            end
            if qualifiers then
                local entries = {}
                for _, field in ipairs(requested) do
                    local answer, found, datedCalendar = dateQuery(clauses[1], field, current)
                    entries[#entries + 1] = {question = key(clauses[1]) .. " " .. field,
                        value = answer and encoded(answer), source = datedCalendar and "Current Date" or "Database",
                        matched = found, calendar = datedCalendar}
                end
                return entries
            end
        end
        -- Repeat requests must be handled before whole-string fuzzy match.
        -- Otherwise "my cats name 4 times" matches the cat-name fact and returns
        -- only "nova" instead of "novanovanovanova".
        do
            local repBase, repCount = parseRepeatRequest(raw)
            if not repBase then repBase, repCount = parseRepeatRequest(normalize(raw)) end
            if not repBase then repBase, repCount = parseRepeatRequest(key(raw)) end
            if repBase and #clauses <= 1 then
                local repAnswer, repMatched, repSource, repCalendar = cachedExact(repBase, current)
                if not repAnswer and not repCalendar then
                    local compact = normalize(repBase):gsub("^please%s+", ""):gsub("^tell%s+me%s+", "")
                        :gsub("^what%s+is%s+", ""):gsub("^whats%s+", ""):gsub("^the%s+", "")
                    if compact ~= "" then
                        repAnswer, repMatched, repSource, repCalendar = cachedExact(compact, current)
                    end
                end
                if not repAnswer and not repCalendar then
                    repAnswer, repMatched, repSource, repCalendar = cachedExact(key(repBase), current)
                end
                if repAnswer and not repCalendar then
                    local unit = encoded(tostring(repAnswer):gsub("^%s*[Tt][Hh][Ee]%s+", ""))
                    if unit ~= "" then
                        return {{question = key(raw), value = unit:rep(repCount),
                            matched = repMatched or key(repBase), source = "Repeated Answer"}}
                    end
                end
            end
        end
        local whole, matched, source, calendar = cachedExact(raw, current)
        -- If the announcement was split into multiple clue parts, resolve each
        -- part against its own learned alias. Never let a fuzzy match for the
        -- entire combined sentence (for example, "... and what device am I on")
        -- override the individually remembered location/device answers.
        if #clauses <= 1 and (whole or calendar) and source ~= "Live" then
            return {{question = key(raw), value = whole and encoded(whole), matched = matched,
                source = source, calendar = calendar}}
        end
        local entries = {}
        local function adjacent(clause)
            local words = {}
            for word in clause:gmatch("%S+") do words[#words + 1] = word end
            if #words < 2 or #words > 48 then return nil end
            local memo, lookups, budget = {}, {}, 128
            local function questionStart(index)
                local first = normalize(words[index])
                local starters = {my = true, what = true, whats = true, which = true, when = true,
                    who = true, how = true, where = true, why = true, sammy = true, sammys = true}
                if starters[first] then return true end
                local pair = first .. " " .. normalize(words[index + 1])
                return pair == "color of" or pair == "colour of" or pair == "name of"
                    or pair == "best brainrot" or pair == "op brainrot" or pair == "rarest brainrot"
                    or pair == "current mutation" or pair == "current trait" or pair == "date of" or pair == "day of"
            end
            local function lookup(first, last)
                local id = first .. ":" .. last
                if lookups[id] ~= nil then return lookups[id] or nil end
                if budget <= 0 then return nil end
                budget -= 1
                local text = table.concat(words, " ", first, last)
                local answer, found, from, datedCalendar = cachedExact(text, current)
                local entry
                if answer or datedCalendar or from == "Live" then
                    entry = {question = key(text), value = answer and encoded(answer),
                        matched = found, source = from, calendar = datedCalendar}
                end
                lookups[id] = entry or false
                return entry
            end
            local function partition(first)
                if first > #words then return {count = 0} end
                if memo[first] ~= nil then return memo[first] or nil end
                -- Longest complete aliases win; every word must belong to a clue.
                for last = #words, first, -1 do
                    if not (first == 1 and last == #words) and (last == #words or questionStart(last + 1)) then
                        local entry = lookup(first, last)
                        if entry then
                            local tail = partition(last + 1)
                            if tail then
                                local result = {entry = entry, tail = tail, count = tail.count + 1}
                                memo[first] = result
                                return result
                            end
                        end
                    end
                end
                memo[first] = false
                return nil
            end
            local result = partition(1)
            if not result or result.count < 2 then return nil end
            return result
        end
        local function append(clause)
            -- Support repetition for ANY resolvable clue (uses shared parseRepeatRequest).
            local repeatBase, repeatCount = parseRepeatRequest(clause)
            if not repeatBase then repeatBase, repeatCount = parseRepeatRequest(normalize(clause)) end
            if not repeatBase then repeatBase, repeatCount = parseRepeatRequest(key(clause)) end
            if repeatBase then
                local repeatedAnswer, repeatedMatch, repeatedSource, repeatedCalendar = cachedExact(repeatBase, current)
                if not repeatedAnswer and not repeatedCalendar then
                    local compactBase = normalize(repeatBase)
                        :gsub("^please%s+", ""):gsub("^tell%s+me%s+", "")
                        :gsub("^what%s+is%s+", ""):gsub("^whats%s+", ""):gsub("^the%s+", "")
                    if compactBase ~= "" and compactBase ~= normalize(repeatBase) then
                        repeatedAnswer, repeatedMatch, repeatedSource, repeatedCalendar = cachedExact(compactBase, current)
                    end
                    if not repeatedAnswer and not repeatedCalendar then
                        repeatedAnswer, repeatedMatch, repeatedSource, repeatedCalendar = cachedExact(key(repeatBase), current)
                    end
                end
                if repeatedAnswer and not repeatedCalendar then
                    local unit = encoded(tostring(repeatedAnswer):gsub("^%s*[Tt][Hh][Ee]%s+", ""))
                    if unit ~= "" then
                        local repeated = unit:rep(repeatCount)
                        -- Respect native textbox limit; still submit the repeated form when it fits.
                        if #repeated <= (Config.MaxCodeLength or 50) or repeatCount <= 10 then
                            entries[#entries + 1] = {question = key(clause), value = repeated,
                                matched = repeatedMatch or key(repeatBase), source = "Repeated Answer"}
                            return
                        end
                    end
                end
            end
            local answer, found, from, datedCalendar = cachedExact(clause, current)
            if (answer or datedCalendar) and from ~= "Live" then
                entries[#entries + 1] = {question = key(clause), value = answer and encoded(answer),
                    matched = found, source = from, calendar = datedCalendar}
                return
            end
            local partition = adjacent(clause)
            if partition then
                while partition.entry do
                    entries[#entries + 1] = partition.entry
                    partition = partition.tail
                end
                return
            end
            if answer or datedCalendar or from == "Live" then
                entries[#entries + 1] = {question = key(clause), value = answer and encoded(answer),
                    matched = found, source = from, calendar = datedCalendar}
                return
            end
            -- Preserve exact names containing "and" before splitting questions.
            local separators, position = {}, 1
            while true do
                local first, last = clause:find("%s+and%s+", position)
                local ofirst, olast = clause:find("%s+or%s+", position)
                if ofirst and (not first or ofirst < first) then first, last = ofirst, olast end
                if not first then break end
                separators[#separators + 1] = {first, last}
                position = last + 1
            end
            -- Prefer the longest known prefix so a name such as "chipso and
            -- queso" remains one answer when followed by another question.
            for i = #separators, 1, -1 do
                local split = separators[i]
                local left, right = clause:sub(1, split[1] - 1), clause:sub(split[2] + 1)
                local known, _, knownSource, knownCalendar = cachedExact(left, current)
                if known or knownCalendar or knownSource == "Live" then append(left) append(right) return end
            end
            -- Only split an unknown conjunction if the right side clearly starts a
            -- second question. Otherwise keep the full clue intact; it may be a SAB name.
            for _, split in ipairs(separators) do
                local right = clause:sub(split[2] + 1)
                local firstWord = (right:match("^%s*(%a+)") or ""):lower()
                local twoWords = (right:match("^%s*(%a+%s+%a+)") or ""):lower()
                local startsQuestion = firstWord == "what" or firstWord == "whats" or firstWord == "who"
                    or firstWord == "how" or firstWord == "where" or firstWord == "when" or firstWord == "why"
                    or firstWord == "which" or firstWord == "my" or firstWord == "tell" or firstWord == "sammy"
                    or twoWords == "that means" or twoWords == "clue is" or twoWords == "next clue"
                    or twoWords == "name of" or twoWords == "color of" or twoWords == "colour of"
                if startsQuestion then
                    append(clause:sub(1, split[1] - 1))
                    append(right)
                    return
                end
            end
            entries[#entries + 1] = {question = key(clause)}
        end
        for _, clause in ipairs(clauses) do append(clause) end
        return entries
    end
    local function releaseSubmitted(request)
        local corrected = false
        for _, entry in ipairs(s.entries) do
            if request.entryIds[entry.id] then
                entry.submitted = false
                local answer = not entry.calendar and entry.source ~= "Live" and learnedValue(entry.question)
                if answer and entry.value ~= encoded(answer) then
                    entry.value, entry.source = encoded(answer), "Learned"
                    corrected = true
                end
            end
        end
        if corrected then refreshEntries() end
        return corrected
    end
    local function removeSubmitted(request)
        local rest = {}
        for _, entry in ipairs(s.entries) do
            if not request.entryIds[entry.id] then rest[#rest + 1] = entry end
        end
        s.entries = rest
        refreshEntries()
    end
    local function cooldownSeconds(message)
        local seconds = tonumber(message:lower():match("wait%s+(%d+%.?%d*)%s*seconds?"))
        return math.max(0.1, tonumber(config.RiddleRateRetryDelay) or 1, seconds or 0)
    end
    local function retryTransient(request, message)
        releaseSubmitted(request)
        local tries = s.transientRetries[request.attemptKey] or 0
        local limit = math.max(0, math.floor(tonumber(config.RiddleTransientRetryLimit) or 2))
        if tries >= limit then
            emit("Retry Limit Reached · Waiting For Next Clue Or Clear")
            return
        end
        s.transientRetries[request.attemptKey] = tries + 1
        s.attempts[request.attemptKey] = nil
        s.retryAt = deps.now() + cooldownSeconds(message)
        emit("Retrying Riddle Submission After A Delay")
        schedule()
    end
    local guessPool, guessSeen = {}, {}
    for _, answer in pairs(RiddleDatabase) do
        local code = encoded(answer)
        if #code >= config.MinPartLength and #code <= config.MaxCodeLength and not guessSeen[code] then
            guessSeen[code] = true
            guessPool[#guessPool + 1] = code
        end
    end
    table.sort(guessPool)
    local function guess(maxLength)
        local choices = {}
        for _, code in ipairs(guessPool) do
            if #code <= maxLength then choices[#choices + 1] = code end
        end
        if #choices == 0 then return nil end
        return choices[(deps.random or math.random)(1, #choices)]
    end
    local function unresolved()
        for _, entry in ipairs(s.entries) do if not entry.value or entry.value == "" then return true end end
        return false
    end
    schedule = function()
        cancel(s.timer) s.timer = nil
        s.waitingForReady = false
        if not s.alive or not s.enabled or not s.armed or s.pending or #s.entries == 0 then return end
        for _, entry in ipairs(s.entries) do
            if entry.source == "Live" and (not entry.value or entry.value == "") then
                emit("Live Riddle Data Unavailable · Submission Paused")
                return
            end
        end
        -- Strict unknown-answer policy: never invent a random code for an unresolved part.
        -- Wait for more clue data or a real resolver answer instead.
        if unresolved() then
            emit("Unknown Riddle Part · Submission Paused")
            return
        end
        local wait = config.RiddleAnswerDebounce or 0.12
        -- Queued clues may already have waited while the game finished another
        -- request. Only wait for the remaining quiet period after the last clue.
        local elapsed = s.lastClueAt and math.max(0, deps.now() - s.lastClueAt) or 0
        local delay = math.max(0, wait - elapsed, (s.retryAt or 0) - deps.now())
        local function run()
            s.timer = nil
            if not s.alive or s.pending or not s.enabled or not s.armed then return end
            -- Recheck at execution time too: clues may still be unresolved.
            -- Never fill missing parts from the random fallback pool.
            if unresolved() then
                emit("Unknown Riddle Part · Submission Paused")
                return
            end
            submit()
        end
        if delay == 0 and deps.defer then s.timer = deps.defer(run)
        else s.timer = deps.after(delay, run) end
    end
    submit = function()
        if not s.alive or not s.enabled or not s.armed or s.pending or #s.entries == 0 then return end
        if s.retryAt and deps.now() < s.retryAt then schedule() return end
        s.retryAt = nil
        if unresolved() then return end
        local values, identities, guessed = {}, {}, false
        local announcement = s.entries[1].announcement
        local question = s.entries[1].announcementQuestion
        for _, entry in ipairs(s.entries) do
            values[#values + 1] = entry.value guessed = guessed or entry.source == "Guess"
            identities[#identities + 1] = tostring(entry.id)
            if entry.announcement ~= announcement then question = nil end
        end
        local code = table.concat(values)
        if #code < config.MinPartLength or #code > config.MaxCodeLength then
            emit("Answer Exceeds The Game's Code Limit") return
        end
        if s.redeemed[code] then
            emit("Riddle Code Already Redeemed · Waiting For Next Clue")
            return
        end
        if deps.skipReplayCode and deps.skipReplayCode(code) then
            s.waitingForReady = false
            emit("Already Checked · Waiting For A New Clue")
            return
        end
        local attemptKey = code .. ":" .. table.concat(identities, ",")
        if s.attempts[attemptKey] then emit("Waiting For The Next Riddle Clue...") return end
        local ready, reason = deps.ready()
        if not ready then
            s.waitingForReady = true
            emit(reason or "Waiting For The Code Box")
            s.timer = deps.after(config.RiddleRetryInterval or 0.05, function()
                s.timer, s.waitingForReady = nil, false
                submit()
            end)
            return
        end
        s.waitingForReady = false
        local request = {code = code, count = #s.entries, revision = s.revision, guessed = guessed,
            session = s.session, question = question, attemptKey = attemptKey, entryIds = {}}
        for _, entry in ipairs(s.entries) do request.entryIds[entry.id] = true end
        s.pending, s.lastSubmitted = request, code
        s.attempts[attemptKey] = true
        for _, entry in ipairs(s.entries) do entry.submitted = true end
        emit(guessed and "Submitting Fallback Guess..." or "Submitting Riddle Answer...")
        s.responseTimer = deps.after(config.ResponseTimeout or 18, function()
            if s.pending ~= request then return end
            -- Never leave the solver permanently locked if the game UI fails to
            -- deliver a response callback. Release this request and retry after a
            -- short cooldown; any late callback is ignored by the identity guard.
            s.responseTimer = nil
            s.pending = nil
            retryTransient(request, "Game Response Timeout")
        end)
        local ok = pcall(deps.submit, code, function(success, message)
            if s.pending ~= request then return end
            cancel(s.responseTimer) s.responseTimer = nil s.pending = nil
            s.lastResponse = clean(message)
            local lower, result = s.lastResponse:lower(), "unclear"
            if success then result = "success"
            elseif lower:find("please wait", 1, true) or lower:find("cooldown", 1, true)
                or lower:find("too fast", 1, true) or lower:find("try again later", 1, true) then result = "rate"
            elseif lower:find("sold out", 1, true) or lower:find("expired", 1, true) then result = "unavailable"
            elseif lower:find("already", 1, true) and (lower:find("redeem", 1, true) or lower:find("used", 1, true)) then result = "used"
            elseif lower:find("invalid", 1, true) or lower:find("incorrect", 1, true) then result = "invalid"
            elseif lower == "confirm button could not be activated" or lower == "textbox rejected the code" then result = "adapter" end
            if result == "success" or result == "used" then s.redeemed[request.code] = deps.now() end
            -- A cooldown belongs to the game even if the old riddle was cleared.
            if result == "rate" then s.retryAt = deps.now() + cooldownSeconds(s.lastResponse) end
            if request.session ~= s.session then
                -- A reset/new riddle may have replaced every old entry. Consume
                -- only the request's IDs, never a prefix of the replacement queue.
                removeSubmitted(request)
                emit(s.enabled and (#s.entries > 0 and "New Riddle Part Collected" or "Waiting For Riddle Questions...")
                    or "AI Riddle Solver Off")
                if #s.entries > 0 then schedule() end
                return
            end
            if result == "rate" or result == "adapter" then retryTransient(request, s.lastResponse) return end
            local corrected = releaseSubmitted(request)
            if result == "unclear" then
                emit(s.lastResponse ~= "" and "Riddle Not Confirmed · " .. s.lastResponse
                    or "Riddle Not Confirmed · Answer Kept")
                return
            end
            if #s.entries == request.count then s.completedQuestion = request.question end
            if result == "invalid" then
                -- Keep a rejected prefix for later clues, and allow a fact learned
                -- during its flight to correct it without replaying the old code.
                emit(#s.entries > request.count and "New Riddle Part Collected" or "Game Rejected Riddle Code · Waiting For Next Clue")
                if corrected or #s.entries > request.count then schedule() end
            else
                removeSubmitted(request)
                local status = result == "success" and "Riddle Code Redeemed"
                    or result == "unavailable" and "Riddle Code Sold Out Or Expired"
                    or "Riddle Code Already Redeemed"
                emit(status)
                if deps.finished then deps.finished(result, s.lastResponse) end
                if #s.entries > 0 then schedule() end
            end
        end)
        if not ok and s.pending == request then
            cancel(s.responseTimer) s.responseTimer = nil s.pending = nil
            retryTransient(request, "Submit Adapter Failed")
        end
    end
    local function trusted(message, location, sender, remove)
        return s.alive and not remove and location == "Top" and type(message) == "string"
            and tonumber(sender) == config.SammyUserId
    end
    local function identity(message, sender, id)
        return id ~= nil and tostring(id) ~= "" and (tostring(sender) .. ":" .. tostring(id) .. ":" .. signature(message)) or nil
    end
    local function duplicate(message, sender, id)
        local now, idKey = deps.now(), identity(message, sender, id)
        if idKey then
            local at = s.seenIds[idKey]
            return at ~= nil and now - at <= (config.MessageIdTTL or 600)
        end
        local at = s.seenText[signature(message)]
        return at ~= nil and now - at < (config.RiddleDuplicateWindow or 0.35)
    end
    local function remember(message, sender, id)
        local now, identity = deps.now(), id ~= nil and tostring(id) or ""
        local idKey = identity ~= "" and (tostring(sender) .. ":" .. identity .. ":" .. signature(message)) or nil
        local textKey = signature(message)
        if duplicate(message, sender, id) then s.duplicateCount += 1 return false end
        if idKey then s.seenIds[idKey] = now else s.seenText[textKey] = now end
        local count = 0
        for cacheKey, at in pairs(s.seenIds) do
            count += 1
            if now - at > (config.MessageIdTTL or 600) then s.seenIds[cacheKey] = nil end
        end
        if count > (config.CacheLimit or 256) then
            local oldestKey, oldest
            for cacheKey, at in pairs(s.seenIds) do
                if not oldest or at < oldest then oldestKey, oldest = cacheKey, at end
            end
            if oldestKey then s.seenIds[oldestKey] = nil end
        end
        for cacheKey, at in pairs(s.seenText) do if now - at > 2 then s.seenText[cacheKey] = nil end end
        return true
    end
    function s:observe(message, duration, sound, location, sender, id, remove)
        if not trusted(message, location, sender, remove) then return false end
        local q = normalize(message):gsub("^the%s+riddle", "riddle")
        local body = q:match("^riddle%s+is%s*(.*)$") or q:match("^riddle%s+(.+)$")
        local control = q == "riddle" or q == "riddle is" or q == "making a riddle"
            or q == "im going to make a riddle" or q == "i am going to make a riddle"
            or q == "im gonna make a riddle" or q == "i will make a riddle"
            or q == "okay im going to make a riddle" or q == "okay im gonna make a riddle"
        if body then
            local setup = body:match("^%s*(.-)%s*$")
            if setup == "hard" or setup == "easy" or setup == "very hard" or setup == "soon"
                or setup == "ready" or setup == "later" or setup == "tonight" or setup == "tomorrow"
                or setup == "next" or setup == "next up" or setup == "starting" or setup == "coming"
                or setup:match("^coming%s+soon") or setup:match("^starting%s+soon")
                or setup:match("^going%s+to") or setup:match("^gonna%s+be") or setup:match("^about%s+to") then
                control = true
            end
        end
        if not control and not body then
            if q:find("%f[%w_]riddle%f[^%w_]") then control = true else return false end
        end
        if duplicate(message, sender, id) then return true, true, false end
        if control and not remember(message, sender, id) then return true, true, false end
        -- A fresh explicit marker starts a new riddle, including inline clues.
        -- Old native requests remain tracked while the new queue waits.
        if self.enabled then reset("Waiting For Riddle Questions...") end
        if self.enabled then self.armed = true end
        return true, control, true
    end
    function s:receive(message, duration, sound, location, sender, id, remove)
        if not self.enabled or not trusted(message, location, sender, remove) then return false end
        local q = normalize(message):gsub("^the%s+riddle", "riddle")
        local explicit = q:match("^riddle%s+is%s+") ~= nil or q:match("^riddle%s+") ~= nil
        if not self.armed and not explicit then return false end
        local entries = resolve(message)
        if #entries == 0 or key(message) == "" then return false end
        local questionKey = key(message)
        local questionText = normalize(payload(message))
        local resolved = false
        for _, entry in ipairs(entries) do
            if entry.value or entry.calendar or entry.source == "Live" then resolved = true break end
        end
        local looksLikeQuestion = explicit or resolved
            or clean(message):find("?", 1, true) ~= nil
            or questionText:match("^my%s") or questionText:match("^what%s") or questionText:match("^when%s")
            or questionText:match("^whats%s") or questionText:match("^who%s") or questionText:match("^how%s")
            or questionText:match("^where%s") or questionText:match("^why%s")
            or questionText:match("^which%s") or questionText:match("^name%s+of%s")
            or questionText:match("^color%s+of%s") or questionText:find("released", 1, true)
        if not looksLikeQuestion then return false end
        if not remember(message, sender, id) then return true end
        if not self.pending and #self.entries > 0 and self.lastClueAt
            and deps.now() - self.lastClueAt > (config.RiddleClueGap or 8) then
            reset("Waiting For Riddle Questions...")
        end
        -- A completed standalone question can be announced again with a fresh
        -- identity. Rejected answers must not turn that repeat into redred/33.
        if not self.pending and self.completedQuestion == questionKey then
            reset("Waiting For Riddle Questions...")
        end
        if #self.entries + #entries > (config.MaxParts or 12) then
            cancel(self.timer) self.timer = nil
            self.waitingForReady = false
            emit("Too Many Riddle Parts · Press Clear")
            return true
        end
        self.completedQuestion = nil
        self.lastClueAt = deps.now()
        nextAnnouncementId += 1
        for _, entry in ipairs(entries) do
            nextEntryId += 1
            entry.id, entry.announcement, entry.announcementQuestion = nextEntryId, nextAnnouncementId, questionKey
            self.entries[#self.entries + 1] = entry
            if not entry.value or entry.value == "" then self.unknownCount += 1 end
            self.lastMatched = entry.matched or entry.question
        end
        refreshEntries()
        emit(self.pending and "Riddle Part Queued During Submission" or "Riddle Answer " .. #self.entries .. " Collected")
        schedule()
        return true
    end
    function s:learn(message, duration, sound, location, sender, id, remove)
        if not trusted(message, location, sender, remove) then return false end
        local plain, q = clean(message), normalize(message)
        -- Optional listening mode remembers Sammy's latest stated location so a later
        -- "where am I?" riddle can use the contextual clue rather than a static fact.
        if self.settings.listenForClues then
            local statement = plain:lower():gsub("’", "'")
            statement = statement:gsub("^%s*sammy%s+says%s*:%s*", "")
                :gsub("^%s*sammy%s*:%s*", ""):gsub("^%s*hey%s*,?%s*", "")
            -- Extract independent facts from one sentence instead of treating the
            -- entire sentence as one answer. Keep this block scoped to avoid adding
            -- permanent locals to the large Luau chunk.
            do
                local function rememberContext(answer, context, aliases)
                    answer = tostring(answer or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    answer = answer:gsub("^my%s+", "")
                    answer = answer:gsub("[%.!,?]+$", "")
                    if #answer > 0 and #answer <= 50 and answer:match("^[%w%s%-']+$") then
                        local record = {answer = answer, source = plain, learnedAt = deps.now(), context = context}
                        for _, alias in ipairs(aliases) do
                            if not self.learned[alias] then self.learnedCount += 1 end
                            self.learned[alias] = record
                        end
                        if deps.factsChanged then deps.factsChanged(self.learned) end
                        emit("Listening: Remembered " .. context .. " " .. answer)
                    end
                end
                -- Capture the actual device noun, not the article in phrases like
                -- "I'm on a computer" / "I am using a phone". Articles are consumed
                -- by the pattern and never become the remembered answer.
                -- Match device clauses even when they occur after a location clause,
                -- e.g. "I'm at the beach and I'm on my laptop". Keep these specific
                -- conjunction patterns ahead of the broad game/location patterns.
                local device = statement:match("and%s+i'm%s+on%s+my%s+([%w%-]+)")
                    or statement:match("and%s+i am%s+on%s+my%s+([%w%-]+)")
                    or statement:match("and%s+im%s+on%s+my%s+([%w%-]+)")
                    or statement:match("and%s+i'm%s+on%s+the%s+([%w%-]+)")
                    or statement:match("and%s+i am%s+on%s+the%s+([%w%-]+)")
                    or statement:match("and%s+im%s+on%s+the%s+([%w%-]+)")
                    or statement:match("and%s+i'm%s+on%s+a%s+([%w%-]+)")
                    or statement:match("and%s+i am%s+on%s+a%s+([%w%-]+)")
                    or statement:match("and%s+im%s+on%s+a%s+([%w%-]+)")
                    or statement:match("^%s*i'm%s+on%s+a%s+([%w%-]+)")
                    or statement:match("^%s*i am%s+on%s+a%s+([%w%-]+)")
                    or statement:match("^%s*im%s+on%s+a%s+([%w%-]+)")
                    or statement:match("^%s*i'm%s+on%s+an%s+([%w%-]+)")
                    or statement:match("^%s*i am%s+on%s+an%s+([%w%-]+)")
                    or statement:match("^%s*im%s+on%s+an%s+([%w%-]+)")
                    or statement:match("^%s*i'm%s+on%s+the%s+([%w%-]+)")
                    or statement:match("^%s*i am%s+on%s+the%s+([%w%-]+)")
                    or statement:match("^%s*im%s+on%s+the%s+([%w%-]+)")
                    or statement:match("^%s*i'm%s+on%s+my%s+([%w%-]+)")
                    or statement:match("^%s*i am%s+on%s+my%s+([%w%-]+)")
                    or statement:match("^%s*im%s+on%s+my%s+([%w%-]+)")
                    or statement:match("and%s+i'?m%s+playing%s+on%s+my%s+([%w%-]+)")
                    or statement:match("and%s+i%s+am%s+playing%s+on%s+my%s+([%w%-]+)")
                    or statement:match("playing%s+on%s+my%s+([%w%-]+)")
                    or statement:match("playing%s+on%s+the%s+([%w%-]+)")
                    or statement:match("playing%s+on%s+a%s+([%w%-]+)")
                    or statement:match("playing%s+on%s+([%w%-]+)")
                    or statement:match("using%s+my%s+([%w%-]+)")
                    or statement:match("using%s+the%s+([%w%-]+)")
                    or statement:match("using%s+a%s+([%w%-]+)")
                    or statement:match("using%s+an%s+([%w%-]+)")
                    or statement:match("using%s+([%w%-]+)")
                if device then
                    device = device:gsub("[%.!,?;:]+$", "")
                    device = device:gsub("%s+and%s+.*$", ""):gsub("%s+but%s+.*$", "")
                    device = device:gsub("^a%s+", ""):gsub("^an%s+", ""):gsub("^the%s+", ""):lower()
                    -- Only accept real devices. "I'm on the beach" is a location, not a device.
                    local deviceWords = {
                        phone=true, mobile=true, iphone=true, android=true, ipad=true, tablet=true,
                        laptop=true, computer=true, pc=true, desktop=true, mac=true, macbook=true,
                        chromebook=true, console=true, xbox=true, playstation=true, ps5=true, ps4=true,
                        switch=true, nintendo=true, steamdeck=true, deck=true, monitor=true,
                        keyboard=true, controller=true, vr=true, headset=true,
                    }
                    local placeWords = {
                        beach=true, park=true, school=true, home=true, house=true, mall=true, store=true,
                        work=true, office=true, gym=true, pool=true, hospital=true, hotel=true,
                        airport=true, restaurant=true, cafe=true, library=true, city=true, town=true,
                        island=true, mountain=true, forest=true, lake=true, river=true, sea=true,
                        ocean=true, street=true, road=true, church=true, museum=true, zoo=true,
                        stadium=true, theater=true, theatre=true, cinema=true, market=true, farm=true,
                        garden=true, backyard=true, basement=true, kitchen=true, bathroom=true,
                        bedroom=true, garage=true, porch=true, balcony=true, roof=true, rooftop=true,
                        subway=true, train=true, bus=true, plane=true, car=true, boat=true, ship=true,
                        resort=true, camp=true, campsite=true, desert=true, jungle=true,
                        carnival=true, fair=true, concert=true, party=true, wedding=true,
                    }
                    if deviceWords[device] then
                        rememberContext(device, "device", {"what am i playing on", "what am i playing on right now",
                            "what am i playing on today", "what am i playing on rn",
                            "what is sammy playing on", "what device am i playing on",
                            "what device am i on", "what device am i using", "what am i using",
                            "what am i playing with", "what platform am i on", "which device am i using",
                            "which device am i playing on", "what is my device", "my device", "device i am on"})
                    elseif placeWords[device] then
                        rememberContext(device, "location", {"where am i", "where am i right now", "where is sammy",
                            "where is sammy right now", "sammy location", "my current location", "where am i at"})
                    end
                end
                local game = statement:match("playing%s+([%w%-]+)%s+on%s+")
                    or statement:match("playing%s+([%w%-]+)%s*$")
                if game and game ~= "on" then
                    rememberContext(game, "game", {"what am i playing", "what game am i playing", "what is sammy playing",
                        "which game am i playing"})
                end
                local name = statement:match("my%s+name%s+is%s+([%w%-']+)")
                    or statement:match("i am%s+([%w%-']+)")
                    or statement:match("i'm%s+([%w%-']+)")
                    or statement:match("im%s+([%w%-']+)")
                if name and name ~= "at" and name ~= "in" and name ~= "on" and name ~= "playing" then
                    if statement:find("my%s+name%s+is", 1) then
                        rememberContext(name, "name", {"what is my name", "whats my name", "what is sammy's name", "who am i", "my name"})
                    end
                end
                local age = statement:match("my%s+age%s+is%s+(%d%d?)")
                    or statement:match("i am%s+(%d%d?)%s+years%s+old")
                    or statement:match("i'm%s+(%d%d?)%s+years%s+old")
                    or statement:match("im%s+(%d%d?)%s+years%s+old")
                if age and tonumber(age) and tonumber(age) >= 1 and tonumber(age) <= 120 then
                    rememberContext(age, "age", {"my age", "what is my age", "whats my age", "how old am i", "what is my age right now", "my age today"})
                end
            end
            local place = statement:match("^%s*i'm%s+at%s+(.+)$")
                or statement:match("^%s*i am%s+at%s+(.+)$")
                or statement:match("^%s*im%s+at%s+(.+)$")
                or statement:match("^%s*i'm%s+in%s+(.+)$")
                or statement:match("^%s*i am%s+in%s+(.+)$")
                or statement:match("^%s*im%s+in%s+(.+)$")
                or statement:match("^%s*i'm%s+by%s+(.+)$")
                or statement:match("^%s*i am%s+by%s+(.+)$")
                or statement:match("^%s*im%s+by%s+(.+)$")
                or statement:match("^%s*i'm%s+near%s+(.+)$")
                or statement:match("^%s*i am%s+near%s+(.+)$")
                or statement:match("^%s*im%s+near%s+(.+)$")
                -- Place-like "on the X" when X is not a device (devices handled above).
                or statement:match("^%s*i'm%s+on%s+the%s+([%w%-]+)%s*$")
                or statement:match("^%s*i am%s+on%s+the%s+([%w%-]+)%s*$")
                or statement:match("^%s*im%s+on%s+the%s+([%w%-]+)%s*$")
                or statement:match("^%s*i'm%s+on%s+a%s+([%w%-]+)%s*$")
                or statement:match("^%s*i am%s+on%s+a%s+([%w%-]+)%s*$")
                or statement:match("^%s*im%s+on%s+a%s+([%w%-]+)%s*$")
            if place then
                -- Stop the location at the next action/clause: "at the beach playing
                -- on my laptop" means location=beach, device=laptop.
                place = place:gsub("%s+then%s+.*$", ""):gsub("%s+and%s+then%s+.*$", "")
                    :gsub("%s+and%s+i'?m%s+.*$", ""):gsub("%s+and%s+i%s+am%s+.*$", "")
                    :gsub("%s+playing%s+.*$", ""):gsub("%s+using%s+.*$", "")
                    :gsub("%s+on%s+my%s+[%w%-]+.*$", ""):gsub("%s+on%s+the%s+[%w%-]+.*$", "")
                    :gsub("%s+on%s+a%s+[%w%-]+.*$", ""):gsub("%s+on%s+an%s+[%w%-]+.*$", "")
                    :gsub("%s+and%s+playing%s+.*$", ""):gsub("[%.!?,]+$", "")
                    :gsub("^a%s+", ""):gsub("^an%s+", ""):gsub("^the%s+", "")
                place = place:match("^%s*(.-)%s*$")
                local deviceOnly = {
                    phone=true, mobile=true, iphone=true, android=true, ipad=true, tablet=true,
                    laptop=true, computer=true, pc=true, desktop=true, mac=true, macbook=true,
                    chromebook=true, console=true, xbox=true, playstation=true, ps5=true, ps4=true,
                    switch=true, nintendo=true, steamdeck=true,
                }
                local placeKey = (place:match("^([%w%-]+)") or ""):lower()
                if deviceOnly[placeKey] then place = nil end
                if place and #place > 0 and #place <= 50 and place:match("^[%w%s%-']+$") then
                    local record = {answer = place, source = plain, learnedAt = deps.now(), context = "location"}
                    for _, alias in ipairs({"where am i", "where am i right now", "where is sammy", "where is sammy right now", "sammy location", "my current location"}) do
                        if not self.learned[alias] then self.learnedCount += 1 end
                        self.learned[alias] = record
                    end
                    emit("Listening: Remembered Location " .. place)
                    if deps.factsChanged then deps.factsChanged(self.learned) end
                    return true
                end
            end
            -- SAB live-announcement memory: learn a newly named Brainrot, its income,
            -- and explicitly stated exist counts from trusted Sammy messages. This is
            -- deliberately phrase-based; it never invents missing values.
            do
                local questionLike = plain:find("?", 1, true) ~= nil
                    or q:match("^what%s") or q:match("^whats%s") or q:match("^which%s")
                    or q:match("^who%s") or q:match("^how%s") or q:match("^where%s")
                    or q:match("^why%s") or q:match("^riddle%s")
                local function storeLiveFact(aliases, answer, context)
                    answer = tostring(answer or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    answer = answer:gsub("[%.!,?;]+$", "")
                    local validAnswer = answer:match("^[%w%s%-']+$") ~= nil
                    if context == "brainrot-income" then
                        validAnswer = answer:match("^%$[%d%.]+[kmbt]?/s$") ~= nil
                    elseif context == "brainrot-exist-count" then
                        answer = answer:gsub(",", "")
                        validAnswer = answer:match("^%d+$") ~= nil
                    end
                    if answer == "" or #answer > 80 or not validAnswer then return nil end
                    local record = {answer = answer, source = plain, learnedAt = deps.now(), context = context or "sab-live"}
                    for _, alias in ipairs(aliases) do
                        local normalizedAlias = key(alias)
                        if normalizedAlias ~= "" then
                            if not self.learned[normalizedAlias] then self.learnedCount += 1 end
                            self.learned[normalizedAlias] = record
                        end
                    end
                    if deps.factsChanged then deps.factsChanged(self.learned) end
                    return record
                end
                if not questionLike then
                    local newName = statement:match("new%s+brainrot%s+is%s+(.+)$")
                        or statement:match("the%s+new%s+brainrot%s+is%s+(.+)$")
                        or statement:match("new%s+brainrot%s*:%s*(.+)$")
                        or statement:match("new%s+brainrot%s+called%s+(.+)$")
                        or statement:match("new%s+brainrot%s+named%s+(.+)$")
                        or statement:match("new%s+brainrot%s*%-+%s*(.+)$")
                        or statement:match("(.+)%s+is%s+the%s+new%s+brainrot%s*$")
                        or statement:match("(.+)%s+is%s+our%s+new%s+brainrot%s*$")
                        or statement:match("(.+)%s+is%s+a%s+new%s+brainrot%s*$")
                        or statement:match("added%s+a%s+new%s+brainrot%s+called%s+(.+)$")
                        or statement:match("added%s+new%s+brainrot%s+(.+)$")
                        or statement:match("just%s+added%s+(.+)%s+brainrot%s*$")
                        or statement:match("just%s+added%s+(.-)%s*$")
                        or statement:match("new%s+brainrot%s+(.+)$")
                        or statement:match("newest%s+brainrot%s+is%s+(.+)$")
                        or statement:match("latest%s+brainrot%s+is%s+(.+)$")
                        or statement:match("brainrot%s+just%s+added%s*:%s*(.+)$")
                        or statement:match("brainrot%s+just%s+added%s+is%s+(.+)$")
                    if newName then
                        newName = newName:gsub("%s+and%s+it%s+.*$", "")
                            :gsub("%s+which%s+.*$", ""):gsub("%s+that%s+.*$", "")
                            :gsub("%s+with%s+income%s+.*$", ""):gsub("%s+earning%s+.*$", "")
                            :gsub("%s+at%s+%$.*$", ""):gsub("%s+for%s+%$.*$", "")
                            :gsub("[%.!,?;]+$", ""):gsub("^the%s+", ""):gsub("^a%s+", ""):gsub("^an%s+", "")
                            :gsub("^brainrot%s+", ""):gsub("%s+brainrot%s*$", "")
                        newName = newName:match("^%s*(.-)%s*$")
                        -- Reject pure filler so "just added something" noise is not stored.
                        local reject = {is=true, a=true, the=true, new=true, our=true, this=true, that=true, it=true}
                        if newName and not reject[newName:lower()] and #newName > 0 and #newName <= 60 and newName:match("^[%w%s%-']+$") then
                            storeLiveFact({"new brainrot", "what is the new brainrot", "what is new brainrot", "whats the new brainrot", "whats new brainrot",
                                "what is the newest brainrot", "whats the newest brainrot", "latest brainrot",
                                "what is the latest brainrot", "name of the new brainrot", "what brainrot was just added",
                                "which brainrot is new", "newest brainrot name", "what brainrot is new",
                                "whats the latest brainrot", "new brainrot name"}, newName, "latest-brainrot")
                            -- Also answer color/income style follow-ups by storing under the name itself as a known unit.
                            storeLiveFact({key(newName), "what is " .. key(newName)}, newName, "latest-brainrot")
                            emit("Listening: Learned New Brainrot " .. newName)
                        end
                    end

                    -- Capture income only when the message states an explicit rate.
                    local incomeName, incomeValue = statement:match("new%s+brainrot%s+is%s+(.+)%s+and%s+it%s+makes%s+(%$[%d%.]+[kmbt]?%s*/%s*s)")
                    if not incomeName then incomeName, incomeValue = statement:match("new%s+brainrot%s*:%s*(.+)%s+%-?%s*(%$[%d%.]+[kmbt]?%s*/%s*s)") end
                    if not incomeName then incomeName, incomeValue = statement:match("^%s*(.-)%s+makes%s+(%$[%d%.]+[kmbt]?%s*/%s*s)") end
                    if not incomeName then incomeName, incomeValue = statement:match("^%s*(.-)%s+earns%s+(%$[%d%.]+[kmbt]?%s*/%s*s)") end
                    if not incomeName then incomeName, incomeValue = statement:match("^%s*(.-)%s+generates%s+(%$[%d%.]+[kmbt]?%s*/%s*s)") end
                    if not incomeName then incomeName, incomeValue = statement:match("income%s+of%s+(.+)%s+is%s+(%$[%d%.]+[kmbt]?%s*/%s*s)") end
                    if incomeName and incomeValue then
                        incomeName = incomeName:gsub("^the%s+", ""):gsub("^a%s+", ""):gsub("[%.!,;]+$", "")
                        incomeName = incomeName:match("^%s*(.-)%s*$")
                        if #incomeName > 0 and #incomeName <= 60 then
                            local nameKey = key(incomeName)
                            storeLiveFact({nameKey .. " income", "income of " .. nameKey,
                                "how much does " .. nameKey .. " make", "how much money does " .. nameKey .. " make",
                                nameKey .. " money per second", nameKey .. " per second", "how much does " .. nameKey .. " generate"},
                                incomeValue:gsub("%s+", ""), "brainrot-income")
                            emit("Listening: Learned Income For " .. incomeName)
                        end
                    end

                    -- Exist counts are stored only when Sammy explicitly states a number.
                    local existName, existCount = statement:match("^%s*(.-)%s+has%s+(%d[%d,]*)%s+exists?%s*$")
                    if not existName then existName, existCount = statement:match("exist%s+count%s+of%s+(.+)%s+is%s+(%d[%d,]*)") end
                    if not existName then existName, existCount = statement:match("^%s*(.-)%s+exist%s+count%s+is%s+(%d[%d,]*)%s*$") end
                    if existName and existCount then
                        existName = existName:gsub("^the%s+", ""):gsub("[%.!,;]+$", "")
                        existName = existName:match("^%s*(.-)%s*$")
                        if #existName > 0 and #existName <= 60 then
                            local nameKey = key(existName)
                            storeLiveFact({"exist count of " .. nameKey, "how many " .. nameKey .. " exist",
                                "how many " .. nameKey .. " exists", nameKey .. " exist count", nameKey .. " exists"},
                                existCount, "brainrot-exist-count")
                            emit("Listening: Learned Exist Count For " .. existName)
                        end
                    end
                end
            end
        end
        if not self.settings.learnFacts then return false end
        if plain:find("?", 1, true) or q:match("^riddle") or q:match("^the%s+riddle") or q:match("^question") or q:match("^code%s")
            or q:match("^what%s") or q:match("^whats%s") or q:match("^when%s") or q:match("^which%s")
            or q:match("^who%s") or q:match("^how%s") or q:match("^where%s") or q:match("^why%s") then return false end
        local subject, answer = plain:match("^%s*(.-)%s+[Ii][Ss]%s+(.+)%s*$")
        if not subject or not answer then return false end
        local subjectKey = key(subject)
        local allowed = subjectKey:match("^my%s+.+%s+name$") or subjectKey:match("^my%s+.+%s+color$")
            or subjectKey:match("^name%s+of%s+my%s+.+$") or subjectKey:match("^color%s+of%s+my%s+.+$")
            or RiddleDatabase[subjectKey] ~= nil or learnedValue(subjectKey) ~= nil
        if not allowed then return false end
        answer = answer:match("^%s*(.-)%s*$"):gsub("[%.!]$", "")
        local answerLower = answer:lower()
        if #answer == 0 or #answer > 50 or answer:find("[,;:+&]") or answerLower:find(" or ", 1, true)
            or answerLower:match("%s+and%s+.-%s+is%s+") or answerLower:match("%s+is%s+") then return false end
        if encoded(answer) == "" then return false end
        if not answer:match("^[%w%s%-']+$") then return false end
        local aliases = {subjectKey}
        local person = subjectKey:match("^my%s+(.+)%s+name$")
        if person then
            person = person:gsub("s$", "")
        else person = subjectKey:match("^name%s+of%s+my%s+(.+)$") end
        if person then
            aliases[#aliases + 1] = "name of my " .. person
            aliases[#aliases + 1] = "my " .. person .. "s name"
            aliases[#aliases + 1] = "my " .. person .. " name"
        end
        local colored = subjectKey:match("^my%s+(.+)%s+color$") or subjectKey:match("^color%s+of%s+my%s+(.+)$")
        if colored then
            aliases[#aliases + 1] = "color of my " .. colored
            aliases[#aliases + 1] = "my " .. colored .. " color"
            aliases[#aliases + 1] = "my color of my " .. colored
        end
        local record = {answer = answer, source = plain, learnedAt = deps.now()}
        for _, alias in ipairs(aliases) do
            if not self.learned[alias] then self.learnedCount += 1 end
            self.learned[alias] = record
        end
        local corrected = false
        for _, entry in ipairs(self.entries) do
            if not entry.calendar and entry.source ~= "Live" and not entry.submitted and self.learned[entry.question] == record then
                entry.value, entry.source = encoded(answer), "Learned"
                corrected = true
            end
        end
        refreshEntries()
        emit("Learned Sammy Fact: " .. subjectKey)
        if deps.factsChanged then deps.factsChanged(self.learned) end
        if corrected then schedule() end
        return true
    end
    function s:setEnabled(value, arm)
        self.enabled = value == true self.armed = self.enabled and arm ~= false
        reset(self.enabled and (self.armed and "Waiting For A Riddle..." or "Waiting For Sammy's Riddle Announcement")
            or "AI Riddle Solver Off")
    end
    function s:setArmed(value)
        self.armed = self.enabled and value == true
        if not self.armed then
            cancel(self.timer) self.timer = nil self.waitingForReady = false
        elseif #self.entries > 0 then schedule() end
    end
    function s:wake()
        if not self.waitingForReady or not self.enabled or self.pending then return end
        cancel(self.timer)
        self.timer, self.waitingForReady = nil, false
        submit()
    end
    function s:setSettings(settings)
        if settings.learnFacts ~= nil then self.settings.learnFacts = settings.learnFacts == true end
        if settings.listenForClues ~= nil then self.settings.listenForClues = settings.listenForClues == true end
        -- Random fallback guessing is intentionally disabled. Unknown answers
        -- remain blank until a reliable answer is resolved.
        self.settings.fallback = false
        local cleared = false
        for _, entry in ipairs(self.entries) do
            if entry.source == "Guess" and not entry.submitted then
                entry.value, entry.source = nil, nil
                cleared = true
            end
        end
        if cleared then refreshEntries() end
        if settings.fallbackDelay ~= nil then self.settings.fallbackDelay = math.clamp(tonumber(settings.fallbackDelay) or 0.55, 0, 1) end
        emit() schedule()
        return true
    end
    function s:clear() reset() end
    function s:unconfuse()
        -- Drop temporary personal/context clues and stale clue caches, but preserve
        -- the built-in riddle database, settings, and non-context learned facts.
        local removed = 0
        for alias, record in pairs(self.learned) do
            if type(record) == "table" and (record.context == "device" or record.context == "location"
                or record.context == "name" or record.context == "age" or record.context == "game") then
                self.learned[alias] = nil
                removed += 1
            end
        end
        for _, alias in ipairs({"my age", "what is my age", "whats my age", "how old am i", "what is my age right now", "my age today",
            "what am i playing on", "what am i playing on right now", "what device am i on", "what device am i playing on",
            "what device am i using", "what is my device", "my device", "device i am on",
            "where am i", "where am i right now", "where is sammy", "where is sammy right now", "sammy location", "my current location"}) do
            if self.learned[alias] ~= nil then self.learned[alias] = nil removed += 1 end
        end
        self.seenIds, self.seenText = {}, {}
        self.lastMatched, self.lastResponse = "", ""
        reset("AI Unconfused · Temporary Memory Cleared")
        if deps.factsChanged then deps.factsChanged(self.learned) end
        return removed
    end
    function s:prepareRetype()
        if self.pending then return false end
        local attempted = self.attempts
        reset("Retyping Recent Announcements...")
        self.attempts = attempted
        return true
    end
    function s:stop()
        self.alive, self.enabled, self.waitingForReady = false, false, false
        cancel(self.timer) cancel(self.responseTimer) self.pending = nil
    end
    function s:snapshot()
        return {learnedFacts = self.learned, riddleSettings = self.settings, riddleRedeemed = self.redeemed,
            currentBrainrotFactRevision = self.currentBrainrotFactRevision, riddleFactRevision = self.riddleFactRevision,
            riddleRarityFactRevision = self.riddleRarityFactRevision,
            riddleBirthDateFactRevision = self.riddleBirthDateFactRevision,
            riddleLuckyBlockFactRevision = self.riddleLuckyBlockFactRevision,
            riddleColorFactRevision = self.riddleColorFactRevision,
            riddleArmed = self.armed, riddleLastMatched = self.lastMatched, riddleEnabled = self.enabled}
    end
    return s
end

-- FPS boost.
function createFPSController(onChanged)
    local Lighting = game:GetService("Lighting")
    local MaterialService = game:GetService("MaterialService")
    local f = {enabled = false, busy = false, changedProperties = 0, textures = 0, stoppedTracks = 0}
    local records, touched, connections, watchedAnimators = {}, {}, {}, {}
    local watchedProperties, stoppedTracks = {}, {}
    local worker, generation = nil, 0
    local function notify() if onChanged then onChanged(f) end end
    local function change(object, property, value)
        local ok, old = pcall(function() return object[property] end)
        if not ok or old == value then return false end
        local keys = touched[object]
        if not keys then keys = {} touched[object] = keys end
        local success = pcall(function() object[property] = value end)
        if not success then return false end
        local record = keys[property]
        if not record then
            record = {object = object, property = property, old = old, applied = value}
            keys[property] = record
            records[#records + 1] = record
            f.changedProperties += 1
        else
            -- Keep the latest game-assigned appearance when an asset finishes loading.
            -- Our own writes do not reach this branch because old already equals value.
            record.old, record.applied = old, value
        end
        return true
    end
    local function enforceProperty(object, property, value, isTexture)
        local properties = watchedProperties[object]
        if not properties then properties = {} watchedProperties[object] = properties end
        if not properties[property] then
            local version, writing = generation, false
            local ok, connection = pcall(function()
                return object:GetPropertyChangedSignal(property):Connect(function()
                    if not f.enabled or generation ~= version or writing then return end
                    writing = true
                    if change(object, property, value) and isTexture then f.textures += 1 end
                    writing = false
                end)
            end)
            if ok then
                properties[property] = connection
                connections[#connections + 1] = connection
            end
        end
        if change(object, property, value) and isTexture then f.textures += 1 end
    end
    local function disconnectAll()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        connections = {}
    end
    local function stopTrack(track, animator)
        if not f.enabled then return end
        local ok, snapshot = pcall(function()
            if not track.IsPlaying then return nil end
            return {track = track, animator = animator, position = track.TimePosition,
                speed = track.Speed, weight = track.WeightTarget}
        end)
        if ok and snapshot and pcall(track.Stop, track, 0) then
            stoppedTracks[track] = snapshot
            f.stoppedTracks += 1
        end
    end
    local function apply(object)
        if not f.enabled then return end
        if object:IsA("BasePart") and not object:IsA("Terrain") then
            -- Changing visual materials must not change the original physical properties.
            if object.Material ~= Enum.Material.SmoothPlastic then
                change(object, "CustomPhysicalProperties", object.CurrentPhysicalProperties)
                change(object, "Material", Enum.Material.SmoothPlastic)
            end
            enforceProperty(object, "MaterialVariant", "")
            change(object, "Reflectance", 0)
            change(object, "CastShadow", false)
            if object:IsA("MeshPart") then enforceProperty(object, "TextureID", "", true) end
            if object:IsA("UnionOperation") then change(object, "UsePartColor", true) end
        elseif object:IsA("SurfaceAppearance") then
            -- PBR maps override MeshPart.TextureID and most maps cannot be changed at runtime.
            if change(object, "Parent", nil) then f.textures += 1 end
        elseif object:IsA("Decal") or object:IsA("Texture") then
            if change(object, "Parent", nil) then f.textures += 1 end
        elseif object:IsA("FileMesh") then
            enforceProperty(object, "TextureId", "", true)
        elseif object:IsA("Shirt") then
            enforceProperty(object, "ShirtTemplate", "", true)
        elseif object:IsA("Pants") then
            enforceProperty(object, "PantsTemplate", "", true)
        elseif object:IsA("ShirtGraphic") then
            enforceProperty(object, "Graphic", "", true)
        elseif object:IsA("ParticleEmitter") or object:IsA("Trail") or object:IsA("Beam")
            or object:IsA("Smoke") or object:IsA("Fire") or object:IsA("Sparkles")
            or object:IsA("Light") or object:IsA("PostEffect") or object:IsA("Highlight") then
            enforceProperty(object, "Enabled", false)
            if object:IsA("ParticleEmitter") then pcall(object.Clear, object) end
        elseif object:IsA("Explosion") then
            enforceProperty(object, "Visible", false)
        elseif object:IsA("Sky") or object:IsA("Atmosphere") or object:IsA("Clouds") then
            change(object, "Parent", nil)
        elseif object:IsA("Animator") and not watchedAnimators[object] then
            watchedAnimators[object] = true
            local version = generation
            -- Listen before taking the snapshot so playback started during setup is caught.
            connections[#connections + 1] = object.AnimationPlayed:Connect(function(track)
                if generation == version then stopTrack(track, object) end
            end)
            local ok, tracks = pcall(object.GetPlayingAnimationTracks, object)
            if ok then
                for _, track in ipairs(tracks) do stopTrack(track, object) end
            end
        end
    end
    local selector = "BasePart, SurfaceAppearance, Decal, Texture, FileMesh, Shirt, Pants, ShirtGraphic, "
        .. "ParticleEmitter, Trail, Beam, Smoke, Fire, Sparkles, Light, PostEffect, Highlight, "
        .. "Explosion, Sky, Atmosphere, Clouds, Animator"
    function f:setEnabled(value)
        value = value == true
        if value == self.enabled then return end
        generation += 1
        local version = generation
        self.enabled, self.busy = value, false
        if worker then pcall(task.cancel, worker) worker = nil end
        disconnectAll()
        if not value then
            -- Restore detached appearance objects only if their original parent still exists.
            for i = #records, 1, -1 do
                local record = records[i]
                pcall(function()
                    if record.property == "Parent" and record.old and record.old.Parent == nil then return end
                    if record.object[record.property] == record.applied then
                        record.object[record.property] = record.old
                    end
                end)
            end
            for _, snapshot in pairs(stoppedTracks) do
                pcall(function()
                    if not snapshot.animator:IsDescendantOf(workspace) or snapshot.track.IsPlaying then return end
                    snapshot.track:Play(0, snapshot.weight, snapshot.speed)
                    snapshot.track.TimePosition = snapshot.position
                end)
            end
            records, touched, watchedAnimators, watchedProperties, stoppedTracks = {}, {}, {}, {}, {}
            if self.renderSettings and self.previousQuality then
                pcall(function()
                    if self.renderSettings.QualityLevel == Enum.QualityLevel.Level01 then
                        self.renderSettings.QualityLevel = self.previousQuality
                    end
                end)
            end
            self.renderSettings, self.previousQuality = nil, nil
            if self.materialOverride ~= nil then
                pcall(function()
                    if MaterialService:GetBaseMaterialOverride(Enum.Material.SmoothPlastic) == "" then
                        MaterialService:SetBaseMaterialOverride(Enum.Material.SmoothPlastic, self.materialOverride)
                    end
                end)
                self.materialOverride = nil
            end
            notify()
            return
        end
        self.changedProperties, self.textures, self.stoppedTracks = 0, 0, 0
        self.busy = true
        change(Lighting, "GlobalShadows", false)
        change(Lighting, "EnvironmentDiffuseScale", 0)
        change(Lighting, "EnvironmentSpecularScale", 0)
        change(workspace.Terrain, "WaterWaveSize", 0)
        change(workspace.Terrain, "WaterWaveSpeed", 0)
        change(workspace.Terrain, "WaterReflectance", 0)
        change(workspace.Terrain, "Decoration", false)
        local qualityOk, rendering = pcall(function() return settings().Rendering end)
        if qualityOk then
            local setOk = pcall(function()
                self.previousQuality = rendering.QualityLevel
                rendering.QualityLevel = Enum.QualityLevel.Level01
            end)
            if setOk then self.renderSettings = rendering end
        end
        local overrideOk, materialOverride = pcall(MaterialService.GetBaseMaterialOverride, MaterialService, Enum.Material.SmoothPlastic)
        if overrideOk then
            self.materialOverride = materialOverride
            pcall(MaterialService.SetBaseMaterialOverride, MaterialService, Enum.Material.SmoothPlastic, "")
        end
        connections[#connections + 1] = workspace.DescendantAdded:Connect(apply)
        connections[#connections + 1] = Lighting.DescendantAdded:Connect(apply)
        notify()
        worker = task.defer(function()
            local objects = workspace:QueryDescendants(selector)
            local lightingObjects = Lighting:QueryDescendants(selector)
            for _, object in ipairs(lightingObjects) do objects[#objects + 1] = object end
            for i, object in ipairs(objects) do
                if not self.enabled or generation ~= version then return end
                apply(object)
                if i % 180 == 0 then task.wait() end
            end
            if self.enabled and generation == version then
                self.busy, worker = false, nil
                notify()
            end
        end)
    end
    function f:stop() self:setEnabled(false) end
    return f
end

-- Admin Abuse Helper.
function createAdminHelper(player, runService, saved, changed, deps)
    saved = saved or {}
    deps = deps or {}
    local promptService = game:GetService("ProximityPromptService")
    local h = {
        alive = true, autoBuy = saved.autoBuy == true, antiRagdoll = saved.antiRagdoll == true,
        lockPosition = saved.lockPosition == true, worker = nil, heartbeat = nil,
        characterConnection = nil, humanoidConnection = nil, lockedCFrame = nil,
        status = "Trait Farm Off",
    }
    local connections, characterConnections, antiConnections = {}, {}, {}
    local visiblePrompts, visibleCount = {}, 0
    local character, humanoid, root, antiRecord, lockRecord
    local activePrompt, elapsed = nil, 0
    local updateHeartbeat, attemptPurchase
    local controls, camera = deps.controls, deps.camera
    local function serverAuthority()
        if type(deps.serverAuthority) ~= "function" then return false end
        local ok, value = pcall(deps.serverAuthority)
        return ok and value == true
    end
    local function ragdollActive()
        local ok, value = pcall(function() return player:GetAttribute("RagdollEndTime") end)
        local clockOk, now = pcall(function() return workspace:GetServerTimeNow() end)
        return ok and clockOk and type(value) == "number" and value > now
    end
    local skeletalJoints = {Root = true, RootJoint = true, Waist = true, Neck = true,
        LeftShoulder = true, RightShoulder = true, LeftElbow = true, RightElbow = true,
        LeftWrist = true, RightWrist = true, LeftHip = true, RightHip = true,
        LeftKnee = true, RightKnee = true, LeftAnkle = true, RightAnkle = true}
    local protectedStates = {
        Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.FallingDown,
        Enum.HumanoidStateType.Physics, Enum.HumanoidStateType.PlatformStanding,
    }
    local function emit(message)
        if message then h.status = message end
        if changed then pcall(changed, h) end
    end
    local function disconnect(list)
        for _, connection in ipairs(list) do pcall(connection.Disconnect, connection) end
        table.clear(list)
    end
    local function connect(list, signal, callback)
        local connection = signal:Connect(callback)
        list[#list + 1] = connection
        return connection
    end
    local function cancelPurchase()
        local worker = h.worker
        h.worker, activePrompt = nil, nil
        if worker then pcall(task.cancel, worker) end
    end
    local function isBadState(state)
        for _, protected in ipairs(protectedStates) do
            if protected == state then return true end
        end
        return false
    end
    local function restoreAntiRagdoll()
        disconnect(antiConnections)
        h.humanoidConnection = nil
        local record = antiRecord
        antiRecord = nil
        if not record then return end
        for object, values in pairs(record.rig or {}) do
            pcall(function()
                if object.Enabled == values.applied then
                    local restored = values.applied
                    if ragdollActive() then restored = values.original end
                    object.Enabled = restored
                end
            end)
        end
        if controls and record.controlsChanged and not h.lockPosition then
            pcall(function() if controls.controlsEnabled == true and record.controlsEnabled == false and ragdollActive() then controls:Disable() end end)
        end
        if camera and record.cameraChanged and ragdollActive() then
            pcall(function() if camera.CameraSubject == record.humanoid then camera.CameraSubject = record.cameraSubject end end)
        end
        for state, enabled in pairs(record.states) do
            pcall(function()
                -- Restore only our applied false value; preserve game changes made
                -- while the toggle was active.
                if record.humanoid:GetStateEnabled(state) == false then
                    record.humanoid:SetStateEnabled(state, enabled)
                end
            end)
        end
        if record.platformChanged then
            pcall(function()
                if record.humanoid.PlatformStand == false then
                    record.humanoid.PlatformStand = record.platformStand and ragdollActive()
                end
            end)
        end
    end
    local function applyAntiRagdoll()
        restoreAntiRagdoll()
        if not h.alive or not h.antiRagdoll or not humanoid then return end
        local current = humanoid
        local clock = deps.now or os.clock
        local record = {humanoid = current, states = {}, platformStand = current.PlatformStand,
            platformChanged = false, rig = {}, controlsEnabled = controls and controls.controlsEnabled,
            cameraSubject = camera and camera.CameraSubject}
        antiRecord = record
        if not serverAuthority() then
            for _, state in ipairs(protectedStates) do
                local ok, enabled = pcall(current.GetStateEnabled, current, state)
                if ok then
                    record.states[state] = enabled
                    pcall(current.SetStateEnabled, current, state, false)
                end
            end
        end
        local writing, lastRecovery = false, -math.huge
        local impactUntil, ragdollUntil = 0, 0
        local safeVelocity, safeTime, safeRoot = Vector3.zero, clock(), nil
        local upwardSpeed, upwardTime, airborne = 0, clock(), false
        local jumpGeneration, safeJumpGeneration, jumpQueued = 0, 0, false
        local recover
        local function hitRoot()
            if not character or player.Character ~= character or current ~= humanoid or current.Health <= 0
                or not character:IsDescendantOf(workspace) then return nil end
            local part = root and root.Parent == character and root or character:FindFirstChild("HumanoidRootPart")
            if not part or not part:IsA("BasePart") or not part:IsDescendantOf(character) then return nil end
            return part
        end
        local function locallyControlled(part)
            return not serverAuthority() and not part.Anchored and not part:GetAttribute("NetworkOwnerSet")
        end
        local function jumpSpeed()
            if current.UseJumpPower then return math.max(0, current.JumpPower) end
            return math.sqrt(2 * math.max(0, workspace.Gravity) * math.max(0, current.JumpHeight))
        end
        local function startJump(fromState)
            if h.lockPosition or current.Health <= 0 then return end
            local now = clock()
            if fromState and jumpQueued and now - upwardTime <= 0.25 then
                jumpQueued = false
                return -- The state transition belongs to the already recorded input.
            end
            if not fromState and (current.FloorMaterial == Enum.Material.Air
                or current:GetState() == Enum.HumanoidStateType.Jumping) then return end
            upwardSpeed, upwardTime, airborne = jumpSpeed(), clock(), true
            jumpGeneration += 1
            jumpQueued = not fromState
        end
        local function markImpact()
            if writing or not h.alive or not h.antiRagdoll or current ~= humanoid or current.Health <= 0 then return end
            local now = clock()
            if now >= impactUntil and now >= ragdollUntil then
                -- Use the last clean sample, not velocity already contaminated by a hit.
                local part = hitRoot()
                local clean = part and part == safeRoot and now - safeTime <= 0.25
                local pendingJump = jumpQueued and now - upwardTime <= 0.25
                if not pendingJump and (not clean or jumpGeneration <= safeJumpGeneration) then
                    upwardSpeed = clean and math.max(0, safeVelocity.Y - math.max(0, workspace.Gravity) * (now - safeTime)) or 0
                    upwardTime = now
                    airborne = current.FloorMaterial == Enum.Material.Air
                    if current.Jump then startJump()
                    elseif not clean and current:GetState() == Enum.HumanoidStateType.Jumping then startJump(true) end
                end
            end
            -- CombatController can delay its impulse for up to one second.
            impactUntil = math.max(impactUntil, now + 1.1)
        end
        local function refreshRagdollWindow()
            local ok, endTime = pcall(function() return player:GetAttribute("RagdollEndTime") end)
            local clockOk, serverNow = pcall(function() return workspace:GetServerTimeNow() end)
            if ok and clockOk and type(endTime) == "number" and endTime > serverNow then
                markImpact()
                ragdollUntil = clock() + endTime - serverNow
            else ragdollUntil = 0 end
        end
        local function correctMotion(sample)
            if not h.alive or not h.antiRagdoll then return end
            local part = hitRoot()
            if not part then return end
            local now = clock()
            if now >= impactUntil and now >= ragdollUntil then
                if sample ~= false then
                    safeVelocity, safeTime, safeRoot = part.AssemblyLinearVelocity, now, part
                    safeJumpGeneration = jumpGeneration
                end
                return
            end
            if not locallyControlled(part) then return end
            if recover then recover() end
            local velocity = part.AssemblyLinearVelocity
            local walkSpeed = math.max(0, current.WalkSpeed)
            local planarSpeed = math.sqrt(velocity.X * velocity.X + velocity.Z * velocity.Z)
            local cleanSpeed = safeRoot == part and math.sqrt(safeVelocity.X * safeVelocity.X + safeVelocity.Z * safeVelocity.Z) or 0
            local planarLimit = math.max(walkSpeed, math.min(cleanSpeed, walkSpeed * 1.5))
            -- Allow normal walking/sprinting. Large hit impulses follow the player's input.
            local x, y, z = velocity.X, velocity.Y, velocity.Z
            if planarSpeed > planarLimit + 1 then
                local direction = current.MoveDirection
                local magnitude = math.sqrt(direction.X * direction.X + direction.Z * direction.Z)
                local scale = magnitude > 1 and 1 / magnitude or 1
                if h.lockPosition then scale = 0 end
                x, z = direction.X * scale * walkSpeed, direction.Z * scale * walkSpeed
            end
            local grounded = current.FloorMaterial ~= Enum.Material.Air
            if not grounded then airborne = true end
            if grounded and airborne and velocity.Y <= 0 and current:GetState() ~= Enum.HumanoidStateType.Jumping
                and not (jumpQueued and now - upwardTime <= 0.25) then
                upwardSpeed, upwardTime, airborne = 0, now, false
            end
            local ceiling = math.max(0, upwardSpeed - math.max(0, workspace.Gravity) * (now - upwardTime))
            if y > ceiling then y = ceiling end
            -- Leave downward velocity alone: stopping a fall here would suspend the avatar.
            if x ~= velocity.X or y ~= velocity.Y or z ~= velocity.Z then
                part.AssemblyLinearVelocity = Vector3.new(x, y, z)
            end
            if part.AssemblyAngularVelocity.Magnitude > 0.01 then part.AssemblyAngularVelocity = Vector3.zero end
        end
        local function watchJoint(object)
            if record.rig[object] or serverAuthority() then return end
            local constraint = object:IsA("BallSocketConstraint")
            if not (constraint or object:IsA("AnimationConstraint") or object:IsA("Motor6D")) then return end
            local name = constraint and object.Name:gsub("BallSocket$", "") or object.Name
            if not skeletalJoints[name] then return end
            local values = {original = object.Enabled, applied = not constraint, writing = false}
            record.rig[object] = values
            local function keepJoint()
                if values.writing or not h.alive or not h.antiRagdoll or current ~= humanoid
                    or current.Health <= 0 or serverAuthority() then return end
                if object.Enabled == values.applied then return end
                markImpact()
                values.original = object.Enabled values.writing = true
                pcall(function() object.Enabled = values.applied end)
                values.writing = false
            end
            connect(antiConnections, object:GetPropertyChangedSignal("Enabled"), keepJoint)
            keepJoint()
        end
        recover = function(state)
            if writing or not h.alive or not h.antiRagdoll or current ~= humanoid or current.Health <= 0 then return end
            if clock() >= impactUntil and clock() >= ragdollUntil and not isBadState(state or current:GetState()) then return end
            writing = true
            pcall(function()
                if not serverAuthority() and current.PlatformStand then
                    record.platformStand, record.platformChanged = true, true
                    current.PlatformStand = false
                end
                if controls and not h.lockPosition and controls.controlsEnabled == false then
                    record.controlsEnabled, record.controlsChanged = false, true
                    controls:Enable()
                end
                if camera and camera.CameraSubject ~= current and camera.CameraSubject and character
                    and camera.CameraSubject:IsDescendantOf(character) then
                    record.cameraSubject, record.cameraChanged = camera.CameraSubject, true
                    camera.CameraSubject = current
                end
                if not serverAuthority() and isBadState(state or current:GetState()) and clock() - lastRecovery > 0.1 then
                    lastRecovery = clock()
                    -- GettingUp can add a stand-up kick while the rig is still being restored.
                    local nextState = current.FloorMaterial == Enum.Material.Air
                        and Enum.HumanoidStateType.Freefall or Enum.HumanoidStateType.Running
                    current:ChangeState(nextState)
                end
            end)
            writing = false
        end
        refreshRagdollWindow()
        pcall(function()
            for _, object in ipairs(character:QueryDescendants("AnimationConstraint, Motor6D, BallSocketConstraint")) do watchJoint(object) end
            connect(antiConnections, character.DescendantAdded, watchJoint)
        end)
        h.humanoidConnection = connect(antiConnections, current.StateChanged, function(previous, state)
            if writing then return end
            if state == Enum.HumanoidStateType.Jumping and previous ~= state then
                startJump(true)
            elseif isBadState(state) then
                markImpact()
                recover(state)
            end
        end)
        connect(antiConnections, current:GetPropertyChangedSignal("Jump"), function()
            if current.Jump then startJump() end
        end)
        connect(antiConnections, current:GetPropertyChangedSignal("PlatformStand"), function()
            if not writing and current.PlatformStand then markImpact() recover() end
        end)
        connect(antiConnections, current.Died, function()
            if antiRecord == record then restoreAntiRagdoll() end
        end)
        pcall(function()
            connect(antiConnections, player:GetAttributeChangedSignal("RagdollEndTime"), function()
                refreshRagdollWindow()
                task.defer(function() if antiRecord == record then recover() end end)
            end)
        end)
        if deps.impactSignal then
            connect(antiConnections, deps.impactSignal, function() markImpact() end)
        end
        if camera then connect(antiConnections, camera:GetPropertyChangedSignal("CameraSubject"), function() recover() end) end
        -- Remove impulses both before integration and after collision responses.
        if runService.PreSimulation then connect(antiConnections, runService.PreSimulation, function() correctMotion(false) end) end
        connect(antiConnections, runService.PostSimulation or runService.Heartbeat, correctMotion)
        recover()
    end

    local function releasePosition()
        local record = lockRecord
        lockRecord, h.lockedCFrame = nil, nil
        if not record then return end
        if controls and record.controlsEnabled == true then
            pcall(function() if controls.controlsEnabled == false and (h.antiRagdoll or not ragdollActive()) then controls:Enable() end end)
        end
    end
    local function capturePosition()
        releasePosition()
        if not h.alive or not h.lockPosition or not root then return end
        local ok, record = pcall(function()
            return {root = root, cframe = root.CFrame, humanoid = humanoid,
                controlsEnabled = controls and controls.controlsEnabled}
        end)
        if not ok then return end
        lockRecord, h.lockedCFrame = record, record.cframe
        pcall(function()
            if controls then controls:Disable() end
            if humanoid then
                humanoid.Jump = false humanoid:Move(Vector3.zero, false)
            end
        end)
    end
    local function currentRoot()
        if not root or not character or player.Character ~= character then return nil end
        if not root:IsDescendantOf(character) or not character:IsDescendantOf(workspace) then return nil end
        if not humanoid or humanoid.Health <= 0 then return nil end
        return root
    end
    local function brainrotPurchase(prompt)
        if not prompt:IsA("ProximityPrompt") or not prompt:IsDescendantOf(workspace)
            or not prompt:HasTag("AnimalPurchasePrompt") then return false end
        if tostring(prompt.ActionText):lower():match("^%s*(.-)%s*$") ~= "purchase" then return false end
        local model = prompt:FindFirstAncestorOfClass("Model")
        local uid = prompt:GetAttribute("UID")
        return model ~= nil and model:HasTag("Animal") and type(uid) == "string" and uid ~= ""
            and uid == model.Name and type(model:GetAttribute("Index")) == "string"
    end
    local function promptPosition(prompt)
        local parent = prompt.Parent
        if not parent then return nil end
        if parent:IsA("Attachment") then return parent.WorldPosition end
        if parent:IsA("BasePart") then return parent.Position end
        if parent:IsA("Model") then return parent:GetPivot().Position end
        return nil
    end
    local function nearbyVisible(prompt, record)
        if not h.alive or not h.autoBuy or visiblePrompts[prompt] ~= record
            or record.attempted then return nil end
        local current = currentRoot()
        if not current or not brainrotPurchase(prompt) or not prompt.Enabled
            or prompt:GetAttribute("Disabled") == true
            or prompt:GetAttribute("TargetPlayer") == player.UserId then return nil end
        local position = promptPosition(prompt)
        if not position or prompt.MaxActivationDistance <= 0 then return nil end
        local distance = (current.Position - position).Magnitude
        if distance > prompt.MaxActivationDistance then return nil end
        return distance
    end
    local function removePrompt(prompt)
        if visiblePrompts[prompt] then
            visiblePrompts[prompt] = nil
            visibleCount -= 1
        end
        if activePrompt == prompt then cancelPurchase() end
        updateHeartbeat()
    end
    local function cleanupTracked()
        local changedSet = false
        for prompt in pairs(visiblePrompts) do
            local ok, alive = pcall(function()
                return prompt:IsDescendantOf(workspace) and prompt.Enabled
            end)
            if not ok or not alive then
                visiblePrompts[prompt] = nil
                visibleCount -= 1
                changedSet = true
                if activePrompt == prompt then cancelPurchase() end
            end
        end
        return changedSet
    end
    attemptPurchase = function()
        if h.worker or not h.alive or not h.autoBuy or type(fireproximityprompt) ~= "function" then return end
        local nearest, record, best = nil, nil, math.huge
        for prompt, entry in pairs(visiblePrompts) do
            local ok, distance = pcall(nearbyVisible, prompt, entry)
            if ok and distance and distance < best then nearest, record, best = prompt, entry, distance end
        end
        if not nearest then return end
        local job
        job = task.defer(function()
            if h.worker ~= job then return end
            local ok, distance = pcall(nearbyVisible, nearest, record)
            if ok and distance then
                record.attempted = true
                emit("Purchasing Nearby Brainrot...")
                -- Activate once, after visibility and distance are revalidated.
                -- The executor prompt helper completes activation immediately.
                pcall(fireproximityprompt, nearest)
            end
            if h.worker == job then
                h.worker, activePrompt = nil, nil
                if h.alive and h.autoBuy then emit("Auto Buy Active") end
            end
        end)
        h.worker, activePrompt = job, nearest
    end
    updateHeartbeat = function()
        local needed = h.alive and (h.lockPosition or (h.autoBuy and visibleCount > 0))
        if not needed then
            if h.heartbeat then h.heartbeat:Disconnect() h.heartbeat = nil end
            return
        end
        if h.heartbeat then return end
        h.heartbeat = runService.Heartbeat:Connect(function(dt)
            if not h.alive then return end
            cleanupTracked()
            if h.lockPosition and lockRecord and currentRoot() == lockRecord.root then
                pcall(function()
                    if controls and controls.controlsEnabled then controls:Disable() end
                    if humanoid then humanoid.Jump = false humanoid:Move(Vector3.zero, false) end
                end)
            end
            if h.autoBuy and visibleCount > 0 then
                elapsed += dt
                if elapsed >= 0.1 then elapsed = 0 attemptPurchase() end
            end
            if visibleCount == 0 and not h.lockPosition then updateHeartbeat() end
        end)
    end
    local function refreshCharacterParts()
        if not h.alive or not character or player.Character ~= character then return end
        local nextHumanoid = character:FindFirstChildOfClass("Humanoid")
        local nextRoot = character:FindFirstChild("HumanoidRootPart")
        if nextRoot and not nextRoot:IsA("BasePart") then nextRoot = nil end
        local humanoidChanged = nextHumanoid ~= humanoid
        if humanoidChanged then
            restoreAntiRagdoll()
            humanoid = nextHumanoid
            applyAntiRagdoll()
            if humanoid then
                pcall(function() connect(characterConnections, humanoid.Died, function() releasePosition() end) end)
            end
        end
        if nextRoot ~= root then
            releasePosition()
            root = nextRoot
            capturePosition()
        elseif humanoidChanged and h.lockPosition then
            capturePosition()
        end
        updateHeartbeat()
    end
    local function bindCharacter(nextCharacter)
        cancelPurchase()
        disconnect(characterConnections)
        restoreAntiRagdoll()
        releasePosition()
        character, humanoid, root = nextCharacter, nil, nil
        if nextCharacter then
            connect(characterConnections, nextCharacter.ChildAdded, refreshCharacterParts)
            connect(characterConnections, nextCharacter.ChildRemoved, refreshCharacterParts)
            refreshCharacterParts()
        end
        updateHeartbeat()
    end
    function h:setAutoBuy(value)
        if not self.alive then return end
        self.autoBuy = value == true
        cancelPurchase()
        elapsed = 0
        updateHeartbeat()
        if self.autoBuy and type(fireproximityprompt) ~= "function" then
            emit("Auto Buy Needs Fireproximityprompt")
        else
            emit(self.autoBuy and "Auto Buy Active" or "Auto Buy Off")
            if self.autoBuy then attemptPurchase() end
        end
    end
    function h:setRuntime(nextControls, nextAuthority, nextImpactSignal)
        if nextControls then controls = nextControls end
        if type(nextAuthority) == "function" then deps.serverAuthority = nextAuthority end
        if nextImpactSignal then deps.impactSignal = nextImpactSignal end
        if self.antiRagdoll then applyAntiRagdoll() end
    end
    function h:setAntiRagdoll(value)
        if not self.alive then return end
        self.antiRagdoll = value == true
        applyAntiRagdoll()
        emit(self.antiRagdoll and "Anti-Ragdoll Active" or "Anti-Ragdoll Off")
    end
    function h:setLockPosition(value)
        if not self.alive then return end
        local nextValue = value == true
        if nextValue == self.lockPosition and (not nextValue or lockRecord) then return end
        self.lockPosition = nextValue
        if self.lockPosition then capturePosition() else releasePosition() end
        updateHeartbeat()
        emit(self.lockPosition and "Movement Input Locked" or "Position Lock Off")
    end
    function h:stop()
        if not self.alive then return end
        self.alive, self.autoBuy, self.antiRagdoll, self.lockPosition = false, false, false, false
        cancelPurchase()
        if self.heartbeat then self.heartbeat:Disconnect() self.heartbeat = nil end
        disconnect(connections)
        disconnect(characterConnections)
        restoreAntiRagdoll()
        releasePosition()
        table.clear(visiblePrompts)
        visibleCount = 0
        character, humanoid, root, self.characterConnection = nil, nil, nil, nil
    end
    function h:snapshot()
        return {autoBuy = self.autoBuy, antiRagdoll = self.antiRagdoll, lockPosition = self.lockPosition}
    end
    connect(connections, promptService.PromptShown, function(prompt)
        if not h.alive or visiblePrompts[prompt] or visibleCount >= 32 then return end
        local ok, purchase = pcall(brainrotPurchase, prompt)
        if not ok or not purchase then return end
        visiblePrompts[prompt] = {attempted = false}
        visibleCount += 1
        updateHeartbeat()
        if h.autoBuy then attemptPurchase() end
    end)
    connect(connections, promptService.PromptHidden, removePrompt)
    h.characterConnection = connect(connections, player.CharacterAdded, function(nextCharacter)
        if h.alive then bindCharacter(nextCharacter) end
    end)
    connect(connections, player.CharacterRemoving, function(oldCharacter)
        if oldCharacter == character then bindCharacter(nil) end
    end)
    bindCharacter(player.Character)
    if h.autoBuy then h:setAutoBuy(true)
    elseif h.lockPosition then emit("Movement Input Locked")
    elseif h.antiRagdoll then emit("Anti-Ragdoll Active") end
    return h
end

-- Send confirmed redemptions to the configured webhook once.
function createWebhookRewardRecognizer(animals)
    local names = {}
    if type(animals) == "table" then
        for name in pairs(animals) do
            if type(name) == "string" and name ~= "" and #name <= 512 then
                names[#names + 1] = {name = name, text = name:lower():gsub("%s+", " ")}
            end
        end
    end
    table.sort(names, function(a, b) return #a.text == #b.text and a.text < b.text or #a.text > #b.text end)
    local function wordByte(value) return value ~= "" and value:match("[%w_\128-\255]") ~= nil end
    local function listGap(value)
        if value:find("[%.!?;:]") then return false end
        value = value:gsub("%f[%a]and%f[%A]", ""):gsub("[%s,'\"&]", "")
        return value == ""
    end
    return function(message)
        if type(message) ~= "string" then return nil end
        local text = message:gsub("&amp;", "&"):gsub("&apos;", "'"):gsub("&quot;", '"')
            :gsub("<[^>]*>", ""):lower():gsub("%s+", " ")
        if not text:match("%f[%a]spawned%f[%A]") and not text:match("%f[%a]received%f[%A]") then return nil end
        -- Negative/uncertain wording is deliberately left as the native message.
        for _, negative in ipairs({"not", "failed", "cannot", "invalid", "unable", "error"}) do
            if text:match("%f[%a]" .. negative .. "%f[%A]") then return nil end
        end
        if text:find("can't", 1, true) or text:find("couldn't", 1, true) or text:find("wasn't", 1, true) then return nil end
        local matches = {}
        -- Longest names claim their span first, so a shorter catalog name inside
        -- another animal cannot create a second, invented reward.
        for _, entry in ipairs(names) do
            local from = 1
            while true do
                local first, last = text:find(entry.text, from, true)
                if not first then break end
                from = last + 1
                if not wordByte(text:sub(first - 1, first - 1)) and not wordByte(text:sub(last + 1, last + 1)) then
                    local overlap = false
                    for _, existing in ipairs(matches) do
                        if first <= existing.last and last >= existing.first then overlap = true break end
                    end
                    if not overlap then matches[#matches + 1] = {first = first, last = last, name = entry.name} end
                end
            end
        end
        table.sort(matches, function(a, b) return a.first < b.first end)
        for _, entry in ipairs(matches) do
            local before = text:sub(1, entry.first - 1):gsub("['\"]", "")
            local after = text:sub(entry.last + 1):gsub("^['\"]", "")
            for _, verb in ipairs({"spawned", "received"}) do
                for _, article in ipairs({"", "a", "an", "the"}) do
                    local ending = article == "" and (verb .. "%s+$") or (verb .. "%s+" .. article .. "%s+$")
                    if before:match("%f[%a]" .. ending) then entry.reliable = true end
                end
            end
            for _, prefix in ipairs({"has%s+been", "have%s+been", "was", "were"}) do
                if after:match("^%s+" .. prefix .. "%s+spawned%f[%A]")
                    or after:match("^%s+" .. prefix .. "%s+successfully%s+spawned%f[%A]") then entry.reliable = true end
            end
            if after:match("^%s+spawned%f[%A]") then entry.reliable = true end
        end
        for index = 2, #matches do
            local previous, current = matches[index - 1], matches[index]
            if previous.reliable and listGap(text:sub(previous.last + 1, current.first - 1)) then current.reliable = true end
        end
        for index = #matches - 1, 1, -1 do
            local current, following = matches[index], matches[index + 1]
            if following.reliable and listGap(text:sub(current.last + 1, following.first - 1)) then current.reliable = true end
        end
        local result, seen = {}, {}
        for _, entry in ipairs(matches) do
            if entry.reliable and not seen[entry.name] then result[#result + 1], seen[entry.name] = entry.name, true end
        end
        return #result > 0 and table.concat(result, ", ") or nil
    end
end

function createRedemptionWebhook(config, deps, saved)
    config, deps, saved = config or {}, deps or {}, saved or {}
    local w = {alive = true, status = "Webhook Off", postedCount = 0, failedCount = 0, pendingCount = 0}
    local history, jobs, active = {}, {}, {}
    local count, sequence = 0, 0
    local configuredLimit = tonumber(config.WebhookCacheLimit) or 256
    if configuredLimit ~= configuredLimit then configuredLimit = 256 end
    local limit = math.clamp(math.floor(configuredLimit), 1, 2048)
    local function emit(status)
        if status then w.status = status end
        if type(deps.changed) == "function" then pcall(deps.changed, w) end
    end
    local function now()
        if type(deps.now) == "function" then
            local ok, value = pcall(deps.now)
            if ok and type(value) == "number" and value == value and math.abs(value) < math.huge then return value end
        end
        return os.time()
    end
    local function codeValue(value)
        if type(value) ~= "string" then return nil end
        local code = value:match("^%s*(.-)%s*$")
        if #code == 0 or #code > 50 or not code:match("^[A-Za-z0-9]+$") then return nil end
        return code, code:lower()
    end
    local function endpoint()
        if config.WebhookEnabled ~= true then return nil, "disabled" end
        local value = config.WebhookUrl
        if type(value) ~= "string" or #value > 4096 then return nil, "invalid_url" end
        value = value:match("^%s*(.-)%s*$")
        if not value:match("^https://discord%.com/api/webhooks/%d+/[A-Za-z0-9_%.%-]+$") then
            return nil, "invalid_url"
        end
        return value
    end
    local function truncate(value, maxCharacters)
        local length = utf8.len(value)
        if not length then value = value:gsub("[\128-\255]", "") length = #value end
        if length <= maxCharacters then return value end
        local nextByte = utf8.offset(value, maxCharacters - 2)
        return value:sub(1, nextByte - 1) .. "..."
    end
    local function lowercasePlain(value)
        value = tostring(value or ""):gsub("&amp;", "&"):gsub("&apos;", "'")
            :gsub("&quot;", '"'):gsub("&lt;", "<"):gsub("&gt;", ">")
            :gsub("<[^>]*>", ""):gsub("[%z\1-\31\127]", " ")
            :gsub("[`*_~|\\]", ""):gsub("@", "(at)")
        local ok, result = pcall(function()
            local characters = {}
            for _, point in utf8.codes(value) do
                local emoji = (point >= 0x1F000 and point <= 0x1FAFF)
                    or (point >= 0x2600 and point <= 0x27BF)
                    or (point >= 0x2300 and point <= 0x23FF)
                    or (point >= 0x2190 and point <= 0x21FF)
                    or (point >= 0x2B00 and point <= 0x2BFF)
                    or point == 0xA9 or point == 0xAE or point == 0x203C or point == 0x2049
                    or point == 0x2122 or point == 0x2139 or point == 0x2934 or point == 0x2935
                    or point == 0x3030 or point == 0x303D or point == 0x3297 or point == 0x3299
                    or point == 0xFE0F or point == 0xFE0E or point == 0x200D or point == 0x20E3
                if not emoji then
                    if (point >= 0x41 and point <= 0x5A) or (point >= 0xC0 and point <= 0xD6)
                        or (point >= 0xD8 and point <= 0xDE) or (point >= 0x410 and point <= 0x42F)
                        or (point >= 0x391 and point <= 0x3A1) or (point >= 0x3A3 and point <= 0x3AB) then
                        point += 0x20
                    elseif point >= 0x400 and point <= 0x40F then point += 0x50
                    elseif point == 0x130 then point = 0x69
                    elseif point == 0x178 then point = 0xFF
                    elseif point == 0x1E9E then point = 0xDF
                    elseif ((point >= 0x100 and point <= 0x12F)
                        or (point >= 0x132 and point <= 0x137)
                        or (point >= 0x14A and point <= 0x177)) and point % 2 == 0 then point += 1
                    elseif ((point >= 0x139 and point <= 0x148)
                        or (point >= 0x179 and point <= 0x17E)) and point % 2 == 1 then point += 1 end
                    characters[#characters + 1] = utf8.char(point)
                end
            end
            return table.concat(characters)
        end)
        if not ok then result = value:gsub("[\128-\255]", ""):lower() end
        return result:lower():gsub("%s+", " "):match("^%s*(.-)%s*$")
    end
    local function rewardName(message)
        -- Some game responses pass nil/non-string payloads; normalize before any :match calls.
        if type(message) ~= "string" then message = tostring(message or "") end
        if type(deps.recognizeReward) == "function" then
            local ok, reward = pcall(deps.recognizeReward, message)
            if ok and type(reward) == "string" then
                reward = lowercasePlain(reward)
                if reward ~= "" then return truncate(reward, 256) end
            end
        end
        -- Only an explicit brainrot label is sufficient without a known-name
        -- catalog adapter. Generic "you received ..." can describe currency.
        local reward = message:match("%f[%a]brainrot%f[%A]%s*[:%-]%s*(.+)")
            or message:match("^you%s+received%s+a?%s*brainrot%s+(.+)$")
            or message:match("^spawned%s+brainrot%s*[:%-]?%s*(.+)$")
            or message:match("^brainrot%s+spawned%s*[:%-]?%s*(.+)$")
            or message:match("^successfully%s+redeemed%s+brainrot%s*[:%-]?%s*(.+)$")
            or message:match("^you%s+spawned%s+(.+)%s+brainrot[.!]?$" )
        if not reward then return nil end
        reward = reward:match("^([^!;]+)") or ""
        reward = reward:gsub("%s+has%s+been%s+spawned.*$", ""):gsub("[%.%s]+$", "")
        if reward == "" then return nil end
        return truncate(reward, 256)
    end
    local function payloadFor(code, message)
        local messageText = truncate(lowercasePlain(message), 4000)
        local reward = rewardName(messageText)
        local lines = {reward and ("brainrot: " .. reward) or "code redeemed"}
        if config.WebhookDetail ~= "reward_only" then lines[#lines + 1] = "code: " .. code:lower() end
        if not reward then lines[#lines + 1] = "game message: " .. (messageText ~= "" and messageText or "empty response") end
        return {content = truncate(table.concat(lines, "\n"), 2000), allowed_mentions = {parse = {}}}
    end
    local function oldestRemovable()
        local oldestKey, oldest
        for key, record in pairs(history) do
            if not active[record] and (not oldest or record.order < oldest.order
                or (record.order == oldest.order and key < oldestKey)) then
                oldestKey, oldest = key, record
            end
        end
        return oldestKey
    end
    local function makeRoom()
        while count >= limit do
            local oldest = oldestRemovable()
            if not oldest then return false end
            history[oldest], count = nil, count - 1
        end
        return true
    end
    local function import(records, state)
        if type(records) ~= "table" then return end
        for key, source in pairs(records) do
            local _, normalized
            if type(codeValue) == "function" then
                local ok, parsedCode, parsedKey = pcall(codeValue, key)
                if ok then _, normalized = parsedCode, parsedKey end
            end
            if normalized and not history[normalized] then
                local actual = type(source) == "table" and source.code or key
                local code, actualKey
                if type(codeValue) == "function" then
                    local ok, parsedCode, parsedKey = pcall(codeValue, actual)
                    if ok then code, actualKey = parsedCode, parsedKey end
                end
                if actualKey ~= normalized or code == nil then code = key end
                local order = type(source) == "table" and tonumber(source.order) or nil
                if not order or order ~= order or math.abs(order) == math.huge then order = sequence + 1 end
                sequence = math.max(sequence, order)
                local timestamp = type(source) == "table" and tonumber(source.at) or tonumber(source)
                if timestamp and (timestamp ~= timestamp or math.abs(timestamp) == math.huge) then timestamp = nil end
                history[normalized] = {code = code, at = timestamp or now(), order = order, state = state}
                count += 1
                if state == "posted" then w.postedCount += 1 end
            end
        end
    end
    import(saved.posted, "posted")
    import(saved.reserved, "reserved")
    while count > limit do
        local oldest = oldestRemovable()
        if not oldest then break end
        history[oldest], count = nil, count - 1
    end
    local function finish(record, successful, status)
        jobs[record], active[record] = nil, nil
        record.state = successful and "posted" or "failed"
        w.pendingCount = math.max(0, w.pendingCount - 1)
        if successful then w.postedCount += 1 else w.failedCount += 1 end
        if w.alive then emit(status) end
    end
    function w:successful(value, message)
        if not self.alive then return false, "stopped" end
        local url, reason = endpoint()
        if not url then
            emit(reason == "disabled" and "Webhook Off" or "Webhook URL Not Configured")
            return false, reason
        end
        local code, key = codeValue(value)
        if not code then return false, "invalid_code" end
        if history[key] then return false, "duplicate" end
        if type(deps.request) ~= "function" or type(deps.encode) ~= "function" or type(deps.defer) ~= "function" then
            emit("Webhook Transport Unavailable")
            return false, "unavailable"
        end
        if not makeRoom() then emit("Webhook Queue Full") return false, "queue_full" end
        sequence += 1
        local record = {code = code, at = now(), order = sequence, state = "reserved"}
        history[key], count, active[record] = record, count + 1, true
        self.pendingCount += 1
        local started = false
        local ok, job = pcall(deps.defer, function()
            started = true
            if not self.alive or record.state ~= "reserved" then return end
            -- Configuration may have been switched off while this job was queued.
            local currentUrl = endpoint()
            if currentUrl ~= url then finish(record, false, "Webhook Cancelled") return end
            local encoded, body = pcall(function() return deps.encode(payloadFor(code, message)) end)
            if not encoded or type(body) ~= "string" then
                finish(record, false, "Webhook Encoding Failed") return
            end
            record.state = "sending"
            local sent, response = pcall(deps.request, {
                Url = url .. "?wait=true", Method = "POST",
                Headers = {["Content-Type"] = "application/json"}, Body = body,
            })
            if not sent then finish(record, false, "Webhook Request Failed") return end
            local status = type(response) == "table" and tonumber(response.StatusCode or response.status_code or response.status) or nil
            if status and (status ~= status or status < 100 or status > 599 or status % 1 ~= 0) then status = nil end
            if status and status >= 200 and status < 300 then
                finish(record, true, "Webhook Posted")
            elseif status == 429 then
                finish(record, false, "Webhook Rate Limited")
            elseif status then
                finish(record, false, "Webhook HTTP " .. tostring(math.floor(status)))
            else finish(record, false, "Webhook Response Unclear") end
        end)
        if not ok or (job == nil and not started) then
            if active[record] then finish(record, false, "Webhook Scheduling Failed") end
            return false, "schedule_failed"
        end
        if active[record] then jobs[record] = job end
        if not started then emit("Webhook Queued") end
        return true
    end
    function w:stop()
        if not self.alive then return end
        self.alive = false
        for record, job in pairs(jobs) do
            if type(deps.cancel) == "function" then pcall(deps.cancel, job) end
            jobs[record], active[record] = nil, nil
        end
        self.pendingCount = 0
        self.status = "Webhook Stopped"
    end
    function w:snapshot()
        local snapshot = {posted = {}, reserved = {}}
        for key, record in pairs(history) do
            local target = record.state == "posted" and snapshot.posted or snapshot.reserved
            target[key] = {code = record.code, at = record.at, order = record.order}
        end
        return snapshot
    end
    local initialUrl, reason = endpoint()
    w.status = initialUrl and "Webhook Ready" or (reason == "disabled" and "Webhook Off" or "Webhook URL Not Configured")
    return w
end

Players = game:GetService("Players")
ReplicatedStorage = game:GetService("ReplicatedStorage")
Input = game:GetService("UserInputService")
Tween = game:GetService("TweenService")
RunService = game:GetService("RunService")
player = Players.LocalPlayer
if not player then warn("Vexora Auto Code Redeemer: run in a client") return end
playerGui = player:WaitForChild("PlayerGui", 20)
if not playerGui then warn("Vexora Auto Code Redeemer: PlayerGui not ready") return end
env = getgenv and getgenv() or _G
KEY, GUI_NAME = "__vexora_auto_code_redeemer", "vexoraAutoCodeRedeemer"
previous = env[KEY] or env.__private_auto_code_redeemer
env.__vexora_settings_store = createSettingsStore(Config, {
    encode = function(value) return game:GetService("HttpService"):JSONEncode(value) end,
    decode = function(value) return game:GetService("HttpService"):JSONDecode(value) end,
    read = type(readfile) == "function" and readfile or nil,
    write = type(writefile) == "function" and writefile or nil,
})
saved = env.__vexora_settings_store:load() or {}
if previous and previous.alive ~= false and not previous.closing and type(previous.snapshot) == "function" then
    local ok, snapshot = pcall(previous.snapshot)
    if ok and type(snapshot) == "table" then saved = snapshot end
end
stopped = previous and type(previous.stop) == "function" and pcall(previous.stop)
if previous and not stopped and type(previous) == "table" then
    previous.alive = false
    for _, connection in ipairs(previous.connections or {}) do pcall(connection.Disconnect, connection) end
    for _, undo in ipairs(previous.restore or {}) do pcall(undo) end
    for thread in pairs(previous.jobs or {}) do pcall(task.cancel, thread) end
    for _, tween in pairs(previous.tweens or {}) do pcall(tween.Cancel, tween) end
end
