effectLayer = make("Frame", panel, {Name = "bg_effect_layer", Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 2, ClipsDescendants = true})
effectLayer.Active = false

function clearEffectLayer()
    for _, child in ipairs(effectLayer:GetChildren()) do child:Destroy() end
end

function spawnBgEffect(kind)
    clearEffectLayer()
    currentBgEffect = kind or "None"
    if currentBgEffect == "None" then return end
    local rng = Random.new()
    if currentBgEffect == "Rain" then
        for i = 1, 28 do
            local drop = make("Frame", effectLayer, {
                Position = UDim2.fromScale(rng:NextNumber(0, 1), rng:NextNumber(-0.2, 1)),
                Size = UDim2.fromOffset(2, rng:NextInteger(10, 22)),
                BackgroundColor3 = Color3.fromRGB(160, 190, 255),
                BackgroundTransparency = rng:NextNumber(0.25, 0.55), BorderSizePixel = 0, ZIndex = 2})
            task.spawn(function()
                while drop.Parent and state.alive do
                    local y = drop.Position.Y.Scale + 0.04
                    if y > 1.1 then y = -0.1 end
                    drop.Position = UDim2.fromScale(drop.Position.X.Scale, y)
                    task.wait(0.04)
                end
            end)
        end
    elseif currentBgEffect == "Matrix" then
        for i = 1, 36 do
            local glyph = make("TextLabel", effectLayer, {
                Position = UDim2.fromScale(rng:NextNumber(0, 1), rng:NextNumber(-0.2, 1)),
                Size = UDim2.fromOffset(12, 14), BackgroundTransparency = 1,
                Text = string.char(rng:NextInteger(48, 90)), TextSize = 11,
                TextColor3 = Color3.fromRGB(40, 255, 90), Font = Enum.Font.Code,
                TextTransparency = rng:NextNumber(0.15, 0.5), ZIndex = 2})
            task.spawn(function()
                while glyph.Parent and state.alive do
                    local y = glyph.Position.Y.Scale + 0.03
                    if y > 1.1 then
                        y = -0.1
                        glyph.Text = string.char(rng:NextInteger(48, 90))
                    end
                    glyph.Position = UDim2.fromScale(glyph.Position.X.Scale, y)
                    task.wait(0.05)
                end
            end)
        end
    elseif currentBgEffect == "Snow" then
        for i = 1, 30 do
            local flake = make("Frame", effectLayer, {
                Position = UDim2.fromScale(rng:NextNumber(0, 1), rng:NextNumber(-0.2, 1)),
                Size = UDim2.fromOffset(rng:NextInteger(3, 6), rng:NextInteger(3, 6)),
                BackgroundColor3 = Color3.fromRGB(240, 245, 255),
                BackgroundTransparency = rng:NextNumber(0.1, 0.4), BorderSizePixel = 0, ZIndex = 2})
            round(flake, 8)
            task.spawn(function()
                while flake.Parent and state.alive do
                    local y = flake.Position.Y.Scale + 0.015
                    local x = flake.Position.X.Scale + math.sin(os.clock() + i) * 0.002
                    if y > 1.1 then y = -0.05 end
                    flake.Position = UDim2.fromScale(math.clamp(x, 0, 1), y)
                    task.wait(0.05)
                end
            end)
        end
    elseif currentBgEffect == "Pumpkins" then
        for i = 1, 10 do
            local p = make("TextLabel", effectLayer, {
                Position = UDim2.fromScale(rng:NextNumber(0, 1), rng:NextNumber(0, 1)),
                Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 1,
                Text = "🎃", TextSize = 16, ZIndex = 2})
            task.spawn(function()
                local t0 = os.clock()
                while p.Parent and state.alive do
                    local bob = math.sin((os.clock() - t0) * 1.4 + i) * 0.02
                    p.Position = UDim2.fromScale(p.Position.X.Scale, math.clamp(p.Position.Y.Scale + bob * 0.02, 0, 0.95))
                    task.wait(0.08)
                end
            end)
        end
    end
end

-- Repaints already-built GUI objects that still use the previous theme's colors,
-- so cards, fields and text in the center console change with the theme.
function recolorThemeTree(previousColors, root)
    if not root then return end
    local swaps = {}
    for key, old in pairs(previousColors) do
        local new = Halloween[key]
        if typeof(new) == "Color3" and new ~= old then swaps[#swaps + 1] = {old, new} end
    end
    if #swaps == 0 then return end
    local function swap(color)
        for _, pair in ipairs(swaps) do
            if color == pair[1] then return pair[2] end
        end
        return nil
    end
    local objects = root:GetDescendants()
    table.insert(objects, root)
    for _, obj in ipairs(objects) do
        if obj:IsA("GuiObject") then
            local bg = swap(obj.BackgroundColor3)
            if bg then obj.BackgroundColor3 = bg end
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                local tc = swap(obj.TextColor3)
                if tc then obj.TextColor3 = tc end
            end
        elseif obj:IsA("UIStroke") then
            local c = swap(obj.Color)
            if c then obj.Color = c end
        end
    end
end

function applyTheme(theme)
    if type(theme) ~= "table" then return end
    currentThemeName = theme.name or currentThemeName
    local previousColors = {}
    for k, v in pairs(Halloween) do
        if typeof(v) == "Color3" then previousColors[k] = v end
    end
    for k, v in pairs(theme) do
        if k ~= "name" and typeof(v) == "Color3" then Halloween[k] = v end
    end
    recolorThemeTree(previousColors, panel)
    if senderWindow then recolorThemeTree(previousColors, senderWindow) end
    accent, highlight, muted = Halloween.accent, Halloween.highlight, Halloween.muted
    white, cardColor, fieldColor = Halloween.white, Halloween.card, Halloween.field
    panel.BackgroundColor3 = Halloween.background
    if surface and surface.Parent then
        local g = surface:FindFirstChildOfClass("UIGradient")
        if g then
            g.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Halloween.surfaceTop),
                ColorSequenceKeypoint.new(1, Halloween.surfaceBottom),
            })
        end
    end
    if panelStroke then panelStroke.Color = accent end
    if title then title.TextColor3 = white end
    mainTabBtn.BackgroundColor3 = activeTab == "main" and Halloween.field or Halloween.off
    settingsTabBtn.BackgroundColor3 = activeTab == "settings" and Halloween.field or Halloween.off
    mainTabBtn.TextColor3 = activeTab == "main" and white or muted
    settingsTabBtn.TextColor3 = activeTab == "settings" and white or muted
end

