function showTab(which)
    activeTab = which
    local mainOn = which == "main"
    content.Visible = mainOn
    settingsPage.Visible = not mainOn
    content.GroupTransparency = mainOn and 0 or 1
    settingsPage.GroupTransparency = mainOn and 1 or 0
    if profile then profile.Visible = mainOn and not state.collapsed end
    mainTabBtn.BackgroundColor3 = mainOn and Halloween.field or Halloween.off
    settingsTabBtn.BackgroundColor3 = (not mainOn) and Halloween.field or Halloween.off
    mainTabBtn.TextColor3 = mainOn and white or muted
    settingsTabBtn.TextColor3 = (not mainOn) and white or muted
    mainTabStroke.Transparency = mainOn and 0.35 or 0.75
    settingsTabStroke.Transparency = mainOn and 0.75 or 0.35
end
connect(mainTabBtn.Activated, function() showTab("main") end)
connect(settingsTabBtn.Activated, function() showTab("settings") end)

