function fitSender(smooth, duration)
    if state.closing or senderClosing then return end
    local usable = root.AbsoluteSize
    if usable.X < 10 or usable.Y < 10 then return end
    local height = senderCollapsed and 66 or 300
    local factor = fitScale(370, height, usable)
    senderScale.Scale, senderShadowScale.Scale = factor, factor
    if not senderPosition then
        local proposedX = (state.x or 12) + state.width * scale.Scale + 18
        local x = proposedX + 370 * factor + 12 <= usable.X and proposedX or (usable.X - 370 * factor) / 2
        senderPosition = Vector2.new(x, state.y or (usable.Y - 370 * factor) / 2)
    end
    senderPosition = Vector2.new(
        math.clamp(senderPosition.X, 12, math.max(12, usable.X - 370 * factor - 12)),
        math.clamp(senderPosition.Y, 12, math.max(12, usable.Y - height * factor - 12)))
    local position = UDim2.fromOffset(senderPosition.X, senderPosition.Y)
    local size = UDim2.fromOffset(370, height)
    if smooth then animate(senderWindow, {Position = position, Size = size}, duration or 0.12)
    else senderWindow.Position, senderWindow.Size = position, size end
    senderShadow.Visible = senderWindow.Visible
    local shadowPosition = position + UDim2.fromOffset(0, 5)
    if smooth then animate(senderShadow, {Position = shadowPosition, Size = size}, duration or 0.12)
    else senderShadow.Position, senderShadow.Size = shadowPosition, size end
    senderExpand.Text = senderCollapsed and "+" or "−"
    senderWindow:SetAttribute("collapsed", senderCollapsed)
end
connect(senderButton.Activated, function()
    if state.closing then return end
    ensureSetup()
    senderEpoch += 1
    senderClosing = false
    senderWindow.Visible = true
    senderWindow.GroupTransparency = 1
    senderShadow.BackgroundTransparency = 1
    senderBody.Visible, senderBody.GroupTransparency = not senderCollapsed, 0
    fitSender(false)
    animate(senderWindow, {GroupTransparency = 0}, 0.22)
    animate(senderShadow, {BackgroundTransparency = 0.65}, 0.22)
end)
connect(senderClose.Activated, function()
    if senderClosing or state.closing then return end
    senderEpoch += 1
    local version = senderEpoch
    senderClosing = true
    announcementBox:ReleaseFocus()
    senderPointer = nil
    animate(senderWindow, {GroupTransparency = 1, Size = senderWindow.Size - UDim2.fromOffset(12, 12),
        Position = senderWindow.Position + UDim2.fromOffset(6 * senderScale.Scale, 6 * senderScale.Scale)}, 0.22)
    animate(senderShadow, {BackgroundTransparency = 1, Size = senderWindow.Size - UDim2.fromOffset(12, 12),
        Position = senderWindow.Position + UDim2.fromOffset(6 * senderScale.Scale, 6 * senderScale.Scale + 5)}, 0.22)
    after(0.24, function()
        if senderEpoch ~= version then return end
        senderWindow.Visible = false
        senderShadow.Visible = false
        senderClosing = false
        fitSender(false)
    end)
end)
connect(senderExpand.Activated, function()
    if senderClosing or state.closing then return end
    senderEpoch += 1
    local version = senderEpoch
    senderCollapsed = not senderCollapsed
    announcementBox:ReleaseFocus()
    if senderCollapsed then
        animate(senderBody, {GroupTransparency = 1}, 0.12)
        after(0.13, function() if senderEpoch == version then senderBody.Visible = false end end)
    else
        senderBody.Visible, senderBody.GroupTransparency = true, 1
        after(0.12, function()
            if senderEpoch == version then animate(senderBody, {GroupTransparency = 0}, 0.24) end
        end)
    end
    fitSender(true, 0.36)
end)
connect(senderHeader.InputBegan, function(input)
    if senderClosing or state.closing then return end
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        senderPointer = {input = input, start = input.Position, position = senderPosition}
    end
end)
connect(Input.InputChanged, function(input)
    if not senderPointer then return end
    local mouse = senderPointer.input.UserInputType == Enum.UserInputType.MouseButton1
    if (mouse and input.UserInputType ~= Enum.UserInputType.MouseMovement) or (not mouse and input ~= senderPointer.input) then return end
    local delta = input.Position - senderPointer.start
    senderPosition = senderPointer.position + Vector2.new(delta.X, delta.Y)
    fitSender(true)
end)
connect(Input.InputEnded, function(input) if senderPointer and senderPointer.input == input then senderPointer = nil end end)
connect(Input.WindowFocusReleased, function() senderPointer = nil end)
connect(root:GetPropertyChangedSignal("AbsoluteSize"), function() if senderWindow.Visible then fitSender(false) end end)
sendNumber = 0
function sendAnnouncement(keepText)
    if senderClosing or state.closing then return end
    local message = announcementBox.Text:match("^%s*(.-)%s*$")
    if message == "" then senderStatus.Text = "Type A Message First" return end
    if not notificationRemote or not notificationRemote:IsDescendantOf(ReplicatedStorage) then
        senderStatus.Text = "Announcement Event Unavailable" return
    end
    if type(firesignal) ~= "function" then senderStatus.Text = "Firesignal Is Required" return end
    sendNumber += 1
    local id = "vexora-local-test:" .. tostring(os.clock()) .. ":" .. sendNumber
    local ok = pcall(firesignal, notificationRemote.OnClientEvent, message, 4, nil, "Top", Config.SammyUserId, id, false)
    senderStatus.Text = ok and "Sent Locally" or "Could Not Send The Local Test"
    if ok and not keepText then announcementBox.Text = "" end
end
connect(send.Activated, function() sendAnnouncement(false) end)
-- Test Send: fires 1-4 premade riddle clues through the same receive path a real
-- announcement uses, so the solver collects and solves them as a multi-part riddle.
;(function()
    local SABNeedles = {"brainrot", "lucky block", "steal", "fuse", "skull", "dragon", "mythic"}
    local SABAvoid = {" mutation ", " current ", " now ", " today ", " latest ", " newest ", " new ", " best ",
        " favorite ", " favourite ", " my ", " exist ", " exists ", " count ", " how many ", " released ",
        " release ", " update ", " event ", " date ", " day ", " month ", " year ", " time ", " price ",
        " added ", " rank ", " this ", " i "}
    local QuestionStarts = {what = true, which = true, who = true, how = true, when = true, where = true,
        is = true, does = true, ["do"] = true, ["in"] = true, the = true, name = true, tell = true, color = true,
        colour = true, income = true, cost = true, rarity = true, chance = true}
    local testPartCount = 1
    local partButtons = {}
    local function paintParts()
        for index, option in ipairs(partButtons) do
            option.BackgroundColor3 = index == testPartCount and accent or fieldColor
        end
    end
    -- Pools are built once from the live database: Steal a Brainrot question keys and
    -- general fact keys. Every key is an exact database key, so each clue has an answer.
    local pools
    local function buildPools()
        if pools then return pools end
        local sab, general, seen = {}, {}, {}
        for key, value in pairs(RiddleDatabase) do
            if type(key) == "string" and type(value) ~= "table" and #key >= 12 and #key <= 60
                and key:match("^[a-z0-9 ]+$") then
                local first = key:match("^(%a+)")
                if first and QuestionStarts[first] then
                    local padded = " " .. key .. " "
                    local isSAB = false
                    for _, needle in ipairs(SABNeedles) do
                        if key:find(needle, 1, true) then isSAB = true break end
                    end
                    if isSAB then
                        local avoid = false
                        for _, word in ipairs(SABAvoid) do
                            if padded:find(word, 1, true) then avoid = true break end
                        end
                        if not avoid then sab[#sab + 1] = key end
                    end
                end
            end
        end
        for _, key in ipairs(VexoraTestGeneral or {}) do
            if not seen[key] and RiddleDatabase[key] ~= nil then
                seen[key] = true
                general[#general + 1] = key
            end
        end
        for _, key in ipairs(VexoraTestPresets or {}) do
            if not seen[key] and RiddleDatabase[key] ~= nil then
                seen[key] = true
                general[#general + 1] = key
            end
        end
        pools = {sab = sab, general = general}
        return pools
    end
    -- Nothing repeats until every prompt in that category has been used once.
    local used, usedMath = {}, {}
    local function takeFrom(list)
        if #list == 0 then return nil end
        local unused = {}
        for _, candidate in ipairs(list) do
            if not used[candidate] then unused[#unused + 1] = candidate end
        end
        if #unused == 0 then
            for _, candidate in ipairs(list) do used[candidate] = nil end
            unused = list
        end
        local candidate = unused[math.random(1, #unused)]
        used[candidate] = true
        return candidate
    end
    local function randomArithmetic()
        local a, b = math.random(2, 30), math.random(2, 30)
        local kind = math.random(1, 4)
        if kind == 1 then return string.format("what is %d+%d?", a, b) end
        if kind == 2 then return string.format("what is %d-%d?", math.max(a, b), math.min(a, b)) end
        if kind == 3 then return string.format("what is %dx%d?", a, b) end
        return string.format("what is %d/%d?", a * b, a)
    end
    local function uniqueArithmetic()
        local prompt
        for _ = 1, 30 do
            prompt = randomArithmetic()
            if not usedMath[prompt] then break end
        end
        usedMath[prompt] = true
        return prompt
    end
    local function buildTestRiddle(count)
        local p = buildPools()
        local picks, inMessage = {}, {}
        for _ = 1, count do
            local roll = math.random(1, 100)
            local prompt = (roll <= 55 and takeFrom(p.sab)) or (roll <= 90 and takeFrom(p.general)) or uniqueArithmetic()
            if inMessage[prompt] then prompt = uniqueArithmetic() end
            inMessage[prompt] = true
            picks[#picks + 1] = prompt
        end
        return picks
    end
    local function sendTestRiddle()
        if senderClosing or state.closing then return end
        if not notificationRemote or not notificationRemote:IsDescendantOf(ReplicatedStorage) then
            senderStatus.Text = "Announcement Event Unavailable" return
        end
        if type(firesignal) ~= "function" then senderStatus.Text = "Firesignal Is Required" return end
        local picks = buildTestRiddle(testPartCount)
        -- All parts go out in one announcement, comma-separated, like a real multi-part riddle.
        sendNumber += 1
        local id = "vexora-test-riddle:" .. tostring(os.clock()) .. ":" .. sendNumber
        local ok = pcall(firesignal, notificationRemote.OnClientEvent, "Riddle: " .. table.concat(picks, ", "), 4, nil, "Top", Config.SammyUserId, id, false)
        senderStatus.Text = ok and string.format("Test Sent (%d Part%s)", #picks, #picks == 1 and "" or "s") or "Could Not Send The Test"
    end
    local partsLabel = text(senderBody, "parts_label", "Parts", UDim2.fromOffset(178, 146), UDim2.fromOffset(60, 20), 12, muted)
    for index = 1, 4 do
        local option = button(senderBody, "test_parts_" .. index, tostring(index), UDim2.fromOffset(22 + (index - 1) * 38, 142), UDim2.fromOffset(32, 28))
        partButtons[index] = option
        connect(option.Activated, function() testPartCount = index paintParts() end)
    end
    paintParts()
    local testButton = button(senderBody, "test_send", "Test Send", UDim2.fromOffset(22, 182), UDim2.fromOffset(120, 32))
    connect(testButton.Activated, sendTestRiddle)
end)()

