-- Ping Helper: live ping readout, plus the object remover script as an on/off toggle.
function createPingHelper()
    local helper = {alive = true, removerOn = false, connections = {}, labels = {}}
    local localPlayer = Players.LocalPlayer

    local modelsToRemove = {
        ["RobuxShop"] = true, ["Shop"] = true, ["EclipseSpinWheel"] = true, ["TradePlazaPortal"] = true,
        ["JumpLTMMachine"] = true, ["ShopNPCRobuxIdle"] = true, ["EventBoard"] = true, ["Haunted Base"] = true,
        ["FuseMachine"] = true, ["Cave"] = true, ["LiveBoard"] = true, ["GenerationBoard"] = true,
        ["StealsBoard"] = true, ["RobuxSpentBoard"] = true, ["Model1"] = true,
    }
    local partsToRemove = {
        ["glitchskyvfx1"] = true, ["glitchskyvfx2"] = true, ["glitchskyvfx3"] = true, ["glitchskyvfx4"] = true,
        ["glitchskyvfx5"] = true, ["glitchgroundvfx"] = true, ["RoadPanel"] = true, ["RootRun"] = true,
    }
    local foldersToRemove = {["1x1x1x1Map"] = true, ["Vfx"] = true}
    local objectsToRemove = {["Events"] = true, ["BackroomsMap"] = true}
    local eventToRemove = "La Vacca Saturno Saturnita"

    local function removeIfMatching(object)
        if not object.Parent then return end
        local name = object.Name

        -- Preserve Main from LiveBoard
        if name == "LiveBoard" and object:IsA("Model") then
            local main = object:FindFirstChild("Main", true)
            if main and main:IsA("BasePart") then
                main.Parent = object.Parent
            end
        end

        -- Remove the entire event and its contents
        if name == eventToRemove then
            local path = object:GetFullName()
            object:Destroy()
            print("Removed event: " .. path)
            return
        end

        local isModel = object:IsA("Model") and modelsToRemove[name]
        local isPart = object:IsA("BasePart") and partsToRemove[name]
        local isFolder = object:IsA("Folder") and foldersToRemove[name]
        local isOtherObject = objectsToRemove[name]
            and (object:IsA("Model") or object:IsA("Folder") or object:IsA("BasePart"))

        if isModel or isPart or isFolder or isOtherObject then
            local path = object:GetFullName()
            object:Destroy()
            print("Automatically removed: " .. path)
        end
    end

    local function setStatus(message)
        if helper.labels.status then helper.labels.status.Text = message end
    end

    function helper:setRemover(enabled)
        self.removerOn = enabled == true
        if not self.removerOn then
            for _, connection in ipairs(self.connections) do pcall(connection.Disconnect, connection) end
            self.connections = {}
            setStatus("Object Remover Off")
            return
        end
        if #self.connections > 0 then return end
        -- Remove existing objects, then keep removing objects added later.
        for _, object in ipairs(game:GetDescendants()) do removeIfMatching(object) end
        table.insert(self.connections, game.DescendantAdded:Connect(removeIfMatching))
        setStatus("Object Remover On")
    end

    -- Ping readout, refreshed twice a second while the helper is alive.
    task.spawn(function()
        while helper.alive do
            local ms = nil
            local ok, value = pcall(function() return localPlayer:GetNetworkPing() end)
            if ok and type(value) == "number" then ms = math.floor(value * 1000 + 0.5) end
            if helper.labels.ping then
                helper.labels.ping.Text = ms and ("Ping: " .. tostring(ms) .. " ms") or "Ping: ---"
            end
            task.wait(0.5)
        end
    end)

    function helper:bindLabels(labels) self.labels = labels or {} end
    function helper:stop()
        self.alive = false
        self:setRemover(false)
    end
    return helper
end

