-- Bulk general facts (direct DB writes; no per-fact local registers).
do
    local function gk(q, a)
        RiddleDatabase[string.lower(q)] = tostring(a)
    end
    -- More math identities
    for a = 0, 50 do
        gk(a .. " percent of 100", a)
        gk("what is " .. a .. " percent of 200", a * 2)
        gk("square root of " .. (a * a), a)
    end
    -- Weekdays / months
    local days = {"monday","tuesday","wednesday","thursday","friday","saturday","sunday"}
    for i, d in ipairs(days) do
        gk("day number of " .. d, i)
        gk(d .. " is day number", i)
    end
    local months = {"january","february","march","april","may","june","july","august","september","october","november","december"}
    for i, m in ipairs(months) do
        gk("month number of " .. m, i)
        gk(m .. " is month number", i)
        gk("what number month is " .. m, i)
    end
    -- Planets
    local planets = {"mercury","venus","earth","mars","jupiter","saturn","uranus","neptune"}
    for i, p in ipairs(planets) do
        gk(p .. " planet number", i)
        gk("planet number " .. i, p)
        gk("what number planet is " .. p, i)
    end
    -- Common opposites
    for _, pair in ipairs({
        {"hot","cold"},{"up","down"},{"left","right"},{"in","out"},{"yes","no"},
        {"true","false"},{"day","night"},{"black","white"},{"big","small"},{"fast","slow"},
        {"high","low"},{"open","closed"},{"start","end"},{"begin","end"},{"love","hate"},
        {"happy","sad"},{"early","late"},{"near","far"},{"empty","full"},{"wet","dry"},
    }) do
        gk("opposite of " .. pair[1], pair[2])
        gk("opposite of " .. pair[2], pair[1])
    end
    -- SI prefixes rough
    for _, row in ipairs({
        {"kilo",1000},{"mega",1000000},{"giga",1000000000},{"milli",0.001},{"centi",0.01},{"micro",0.000001},
    }) do
        gk("what does " .. row[1] .. " mean as prefix roughly", row[2])
        gk(row[1] .. " means", row[2])
    end
    -- Animals babies already partly covered; add more group names
    for _, row in ipairs({
        {"cows","herd"},{"sheep","flock"},{"birds","flock"},{"bees","swarm"},{"ants","colony"},
        {"whales","pod"},{"dolphins","pod"},{"kangaroos","mob"},{"frogs","army"},{"owls","parliament"},
    }) do
        gk("group of " .. row[1], row[2])
        gk("what is a group of " .. row[1] .. " called", row[2])
    end
    -- World wonders / landmarks short
    for _, row in ipairs({
        {"eiffel tower","paris"},{"statue of liberty","new york"},{"big ben","london"},
        {"colosseum","rome"},{"taj mahal","agra"},{"great wall","china"},{"christ the redeemer","rio"},
        {"machu picchu","peru"},{"petra","jordan"},{"chichen itza","mexico"},
    }) do
        gk("where is " .. row[1], row[2])
        gk(row[1] .. " location", row[2])
        gk(row[1] .. " city or country", row[2])
    end
    -- Programming / internet basics
    for _, row in ipairs({
        {"css","cascading style sheets"},
        {"js","javascript"},{"sql","structured query language"},
        {"ip","internet protocol"},{"dns","domain name system"},
        {"cli","command line interface"},
        {"rpg","role playing game"},
        {"hp","hit points"},{"xp","experience points"},{"aoe","area of effect"},{"dps","damage per second"},
    }) do
        gk("what does " .. row[1] .. " stand for", row[2])
        gk(row[1] .. " stands for", row[2])
        gk(row[1] .. " meaning", row[2])
    end
    -- Simple geometry
    gk("area of square side s", "s squared")
    gk("perimeter of square side s", "4s")

    gk("perimeter of rectangle", "2 times length plus width")

    gk("circumference of circle", "2 pi r")
    gk("area of circle", "pi r squared")
    -- Numbers
    for n = 1, 20 do
        gk("factorial of " .. n, (function()
            local r = 1
            for i = 2, n do r = r * i end
            return r
        end)())
    end
    -- Colors of rainbow
    local rainbow = {"red","orange","yellow","green","blue","indigo","violet"}
    for i, c in ipairs(rainbow) do
        gk("rainbow color " .. i, c)
        gk(c .. " is rainbow color number", i)
    end
    -- Chess pieces
    for _, row in ipairs({
        {"king",1},{"queen",1},{"rook",2},{"bishop",2},{"knight",2},{"pawn",8},
    }) do
        gk("how many " .. row[1] .. "s per side in chess", row[2])
        gk("chess " .. row[1] .. " count one side", row[2])
    end
    -- Card suits
    for _, s in ipairs({"hearts","diamonds","clubs","spades"}) do
        gk(s .. " is a card suit", "yes")
        gk("is " .. s .. " a suit", "yes")
    end
    gk("how many suits in a deck", "4")
    gk("how many ranks in a deck", "13")
    -- Body counts already partially there; reinforce
    gk("how many fingers on one hand", "5")
    gk("how many toes on one foot", "5")
    gk("how many fingers total", "10")
    gk("how many toes total", "10")
    gk("how many eyes", "2")
    gk("how many ears", "2")
    gk("how many legs humans", "2")
    gk("how many arms humans", "2")
end

