-- Mega general-knowledge expansion (closest-match friendly short keys).
do
    local function gk(q, a)
        RiddleDatabase[tostring(q):lower()] = tostring(a)
    end
    -- Numbers written out
    local words = {"zero","one","two","three","four","five","six","seven","eight","nine","ten",
        "eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen","twenty"}
    for i = 0, 20 do
        gk(words[i + 1], i)
        gk("number " .. words[i + 1], i)
