state.lifecycle.setupStarted = false
ensureSetup = function()
    if state.lifecycle.setupStarted or not state.alive then return end
    state.lifecycle.setupStarted = true
    defer(function()
        local ok, err = pcall(function() return state.lifecycle.run(state.lifecycle) end)
        if not ok then
            gui:SetAttribute("error", tostring(err))
            engine.status = "Connection Setup Failed"
            refresh()
        end
        if not state.responsesConnected then state.lifecycle.setupStarted = false end
    end)
end
content.Visible, profile.Visible = not state.collapsed, not state.collapsed
senderBody.Visible = not senderCollapsed
fit(false)
refresh()
if saved.fpsBoost == true then state.fps:setEnabled(true) end
if saved.adminAbuse and (saved.adminAbuse.antiRagdoll or saved.adminAbuse.lockPosition) then loadHelperRuntime() end
if saved.adminAbuse and saved.adminAbuse.lockPosition then adminHelper:setLockPosition(true) end
state.settingsRestoring = false
state.persistSettings(true)
ensureSetup() -- Capture recent trusted announcements even while the switches are off.
animate(panel, {GroupTransparency = 0}, 0.28)

-- Left Control toggles the main Vexora interface.
vexoraToggleDebounce = false
connect(Input.InputBegan, function(input, gameProcessed)
    if gameProcessed or state.closing or vexoraToggleDebounce then return end
    if input.KeyCode == Enum.KeyCode.LeftControl then
        vexoraToggleDebounce = true
        gui.Enabled = not gui.Enabled
        task.delay(0.18, function() vexoraToggleDebounce = false end)
    end
end)
